P.entries["quest:4681"] = {n="Washed Ashore"}
P.entries["quest:469"] = {n="Daily Delivery",s="Daily Delivery este o insarcinare in numele vanatorului dwarf Einar Stonegrip, care le cere calatorilor ce se indreapta spre Menethil Harbor sa livreze piei tabacite de crocolisk tabacarului local. Ca sa evite neintelegerile de acasa, Einar se bazeaza pe aventurierii aflati in trecere pentru a-si mentine aprovizionarea.",h="Daily Delivery este o insarcinare in numele vanatorului dwarf Einar Stonegrip, care le cere calatorilor ce se...",kw={"piele de crocolisc","Einar Stonegrip","James Halloran","Menethil Harbor","Sida","tabacar","Wetlands"},ang={["faction:Alliance"]="Menethil Harbor este principala poarta maritima care leaga domeniul Ironforge de continentele nordice, asa ca bunuri comerciale de baza precum pielea de crocolisc sunt esentiale pentru echiparea garzilor locale si a docherilor.",["race:Dwarf"]="Chiar si departe de Ironforge, piticii fac negot in tinuturile joase si umede, desi se pare ca disputele domestice sunt mai greu de infruntat decat fiarele mlastinii."},sec={{t="Un curier reticent",b="In tinuturile mlastinoase, Einar Stonegrip isi castiga traiul vanand vietatile locale, in special crocoliscii agresivi care pandesc de-a lungul apelor. Desi aduna multe piei pretioase, ca sa le livreze trebuie sa se intoarca la Menethil Harbor. Nedorind sa-si infrunte sotia, Sida, in perioada grea prin care trece casnicia lor, Einar prefera sa ramana pe teren si sa-si incredinteze pachetele calatorilor aflati in trecere."},{t="Comert in Menethil",b="Destinatarul acestor piei este James Halloran, un tabacar care isi desfasoara activitatea in Menethil Harbor. Halloran se bazeaza pe livrarile regulate ale vanatorilor din zona pentru a confectiona cizme si a tabaci piei pentru negustorii si marinarii care trec prin port. Observand ca Einar lipseste de o saptamana, tabacarul deduce cu usurinta ca disputa conjugala se afla in spatele livrarii prin intermediar si se intreaba daca propria lui sotie n-ar trebui sa intervina pentru a indrepta lucrurile cu Sida."}},faq={{q="De ce nu livreaza Einar Stonegrip personal pieile?",a="Einar recunoaste ca sotia sa, Sida, este cam posaca in ultima vreme. Ca sa nu-i infrunte firea apriga, trandaveste prin Wetlands si le cere calatorilor in trecere sa-i duca livrarile in oras.",al={"de ce se ascunde Einar","problema sotiei lui Einar","de ce nu vrea Einar sa se intoarca acasa"}},{q="Cine este James Halloran?",a="James Halloran este tabacar si mester in pielarie, stationat in Menethil Harbor. Cumpara blanuri si piei crude de la vanatorii locali, le tabaceste si le vinde sub forma de cizme si alte articole din piele finisata.",al={"halloran tabacar","cine este james halloran"}},{q="Cine este Sida?",a="Sida este sotia lui Einar Stonegrip si locuieste in Menethil Harbor. Starea ei proasta din ultima vreme este principalul motiv pentru care Einar isi petrece zilele prin mlastini, evitand sa se intoarca acasa.",al={"sotia lui Einar","cine este Sida"}},{q="Ce fel de blanuri sunt transportate?",a="Livrarea consta intr-un manunchi de piei de crocolisc, luate de la reptilele mari care infesteaza mlastinile si cursurile de apa din Wetlands.",al={"ce piei","obiectele pentru Daily Delivery"}},{q="Stie Halloran de ce evita Einar Menethil Harbor?",a="Da. Cand ii predai legatura, Halloran remarca faptul ca Einar nu a mai venit de aproape o saptamana si ghiceste imediat ca problema cu Sida este cauza.",al={"stie Halloran","reactia tabacarului"}},{q="Unde are loc aceasta livrare?",a="Livrarea incepe cu Einar Stonegrip, aflat pe drum in Wetlands, si se incheie la atelierul lui James Halloran din Menethil Harbor, pe coasta de vest.",al={"unde predau","locatia Daily Delivery"}}},fp="14,294,19.419.0,20.429.0,54.184.0,22.178.0,12.166.0,41.139.0,57.157.0,36.158.0"}
P.entries["quest:47"] = {n="Gold Dust Exchange",s="La intersectia din Goldshire, Gold Dust Exchange ii da lui Remy \"Two Times\" bani pentru praful de aur adunat de la koboldii din minele Elwynn. Calatorii strang praful si il vand brokerului nelinistit contra unei plati.",h="La intersectia din Goldshire, Gold Dust Exchange ii da lui Remy \"Two Times\" bani pentru praful de aur adunat...",kw={"Elwynn Forest","Fargodeep Mine","praf de aur","Goldshire","Jasperlode Mine","kobold","Remy Two Times"},ang={["class:Rogue"]="Felul discret al lui Remy si simbolul primit de la niste \"asociati\" fara nume indica existenta unor sindicate subterane sub aparenta linistita a Goldshire.",["faction:Alliance"]="Zacamintele esentiale de aur si minereuri din Elwynn se afla in mainile koboldilor salbatici, nu ale excavatorilor regali, semn ca fortele militare ale regatului sunt istovite.",["profession:Mining"]="Minerii care cauta in Fargodeep si Jasperlode dau peste kobolzi agatati de cele mai bogate filoane de cupru, asa ca trebuie alungati pentru a putea extrage minereul."},sec={{t="Un oras al buzunarelor si tarnacoapelor",b="Goldshire se afla la intersectia drumurilor din Elwynn Forest, iar calatorii, negustorii si garzile trec prin oras. Remy \"Two Times\" este un mijlocitor dubios, care are obiceiul sa-si repete vorbele si un ochi ager pentru profit. In loc sa plateasca echipe de mineri ca sa sape dupa minereuri brute, apeleaza la calatorii care trec prin Lion's Pride Inn. Ofera bani pentru praful de aur luat de la Kobold din regiune."},{t="Jaful Kobold",b="Koboldii au cotropit Fargodeep Mine la sud de Goldshire si Jasperlode Mine la nord-est. Acesti sapatori asemanatori sobolanilor scormonesc prin intuneric dupa lumanari si maruntisuri stralucitoare, adunand in pungile lor firicele de minereu neprelucrat. Alungarea lor serveste regatul, iar adunarea prafului lor transforma munca intr-un castig in monede."},{t="Umbre in spatele tejghelei",b="Remy spune ca plateste bine pentru comert obisnuit, dar fiecare plata vine cu un avertisment. Cand primeste praful, le da ajutoarelor sale un mic jeton pentru \"asociatii\" lui. Cu banditi, zidari neplatiti si retele ascunse active in umbra Stormwind, intermediarii discreti ai lui Remy ar putea avea alte planuri pentru aur decat comertul de la sat."}},faq={{q="Cine este Remy \"Two Times\"?",a="Remy \"Two Times\" este un intermediar local dubios, aflat in fata Lion's Pride Inn din Goldshire. Repeta finalurile propozitiilor, cumpara materiale pretioase de la calatori si pastreaza legaturi cu asociati din umbra.",al={"remy de doua ori","cine da Gold Dust Exchange","remy in Goldshire"}},{q="De unde fac kobolzii rost de praf de aur?",a="Kobold isi petrec viata sapand prin filoanele de minereuri din Elwynn, inclusiv in cele din Fargodeep si Jasperlode. In timp ce sapa prin stanca in cautare de comori si ceara de lumanari, in buzunarele si pungile lor se aduna fulgi si praf de aur neprelucrat.",al={"de ce au kobolzii praf de aur","de unde provine praful de aur"}},{q="Unde gasesc minele mentionate de Remy?",a="Kobolds care poarta praf de aur se gasesc mai ales in Fargodeep Mine si imprejurimi, la sud de Goldshire, si in Jasperlode Mine, la nord-est, aproape de granita spre Eastvale Logging Camp.",al={"unde sunt minele","unde gasesti koboldii din Elwynn"}},{q="De ce le permite Stormwind koboldilor sa controleze minele?",a="In lipsa regelui Varian Wrynn si in conditiile in care House of Nobles refuza sa trimita trupe la periferie, Stormwind City Guard este suprasolicitata. Garnizoanele locale nu pot curata minele, asa ca koboldii raman acolo, iar calatorii independenti se lupta cu ei.",al={"de ce minele nu sunt pazite","de ce a pierdut Stormwind minele"}},{q="Se foloseste praful de aur la fierarie sau la comert?",a="Particulele din praful de aur brut al kobolds sunt prea fine si prea impure pentru lucrul obisnuit la forja. Intermediari precum Remy il preiau ca materie prima, il aduna si apoi il rafineaza prin propriile canale private.",al={"la ce foloseste praful de aur","poti topi praful de aur"}}},fx={["9de6b9cb"]={q="De ce vrea Remy \"Two Times\" praf de aur?",a="Remy se comporta ca un oportunist local si iscusit, cumparand resurse valoroase pe nimic. In loc sa infrunte el insusi tunelurile periculoase infestate de Kobold, se bazeaza pe calatorii aventurosi pentru a extrage praful de aur brut de la vermine. Obtine castiguri rapide din comertul cu metale pretioase si foloseste afacerile pentru a te rasplati cu bani si legaturi cu asociatii sai.",al={"de ce vrea Remy praf de aur","motivul pentru care Remy vrea de doua ori"}},["3c82823a"]={q="De ce are Remy nevoie de tine, in loc sa adune singur praful de aur?",a="Remy este negustor si smecher, nu luptator din prima linie, si prefera vadit sa ramana in siguranta in Goldshire, in loc sa se aventureze in puturi de mina intunecate. Intre timp, garnizoana locala din Stormwind este deja suprasolicitata, ocupandu-se de banditi, gnolli si problema mai ampla a koboldilor, asa ca nu-i mai ramane nici interesul, nici personalul necesar pentru a strange praful mineral imprastiat. De aceea, mercenari independenti precum tine sunt solutia ideala.",al={"de ce nu obtine Remy praful de aur","de ce are Remy nevoie de mine","de ce sa nu se ocupe garzile din Stormwind"}},["27e84318"]={q="De ce cara koboldii praf de aur in minele din Elwynn?",a="Kobold sunt sapatori innascuti care au invadat minele parasite si slab aparate din Elwynn, inclusiv Fargodeep Mine si Jasperlode Mine. Impinsi de dorinta obsesiva de a sapa si de a strange maruntisuri stralucitoare, scobesc filonele subterane zi si noapte. Praful de aur se aduna pe labele, hainele si in pungile lor in timp ce se strecoara prin galerii.",al={"de ce sunt kobolzii in mine","de ce au kobolzii praf de aur","kobolzii din Fargodeep Mine"}}},fp="18,190,27.386.0,18.323.0,26.326.1,24.201.0,31.228.0,45.178.0,56.235.0,45.206.0"}
P.entries["quest:470"] = {n="Digging Through the Ooze",s="In timp ce-si aducea omagiile obisnuite la Ironbeard's Tomb, Sida a fost surprinsa de mocirlele cumplite care dadeau tarcoale mormintelor si si-a aruncat geanta ca sa le distraga atentia. Neputand sa se mai apropie de mocirla taratoare, le cere aventurierilor curajosi din Menethil Harbor sa gaseasca creatura care i-a inghitit lucrurile.",h="In timp ce-si aducea omagiile obisnuite la Ironbeard's Tomb, Sida a fost surprinsa de mocirlele cumplite care...",kw={"dun modr","ironbeard's tomb","menethil harbor","mazga","geanta acoperita de mazga","sida","geanta lui sida","wetlands"},ang={["faction:Alliance"]="Menethil Harbor este principala cale de aprovizionare a Alliance prin Wetlands, pline de primejdii, iar ajutorarea cetatenilor tulburati mentine acest port vital in siguranta si in ordine.",["race:Dwarf"]="Ironbeard's Tomb adaposteste ramasitele unui stramos dwarf onorat, iar pangarirea gorganelor de catre oozes scarboase este o ofensa pentru orice loialist Bronzebeard."},sec={{t="O retragere in panica",b="Sida, o calatoare care locuieste in Menethil Harbor, se aventureaza regulat spre nord-est, in Wetlands, pentru a aduce un omagiu la Ironbeard's Tomb. La ultima ei vizita, a gasit stravechiul tumul misunand de mase gelatinoase scarboase si baloase. Cuprinsa de panica la vederea ororilor fara forma, si-a aruncat desaga spre una dintre ele. Creatura a inghitit-o cu totul, insa distragerea i-a dat Sidei ragazul necesar sa fuga inapoi, la adapostul oraselului-port."},{t="Mlastina din Ironbeard's Tomb",b="Locul de inmormantare al vestitului erou pitic Ironbeard se afla langa fortareata disputata Dun Modr. In ciuda respectului istoric de care se bucura, mlastina din jur este predispusa la contaminare, atragand namoluri acide amorfe care devoreaza orice are ghinionul sa le iasa in cale. Sida nu-si aminteste ce monstruozitate anume i-a inghitit bunurile pretioase, asa ca le ramane calatorilor sa cerceteze imprejurimile mormantului si sa taie prin mlastina invadatoare pentru a-si recupera desaga uda leoarca."}},faq={{q="Cine este Sida?",a="Sida este o calatoare din Alliance, aflata in Menethil Harbor. Face pelerinaje regulate in Wetlands pentru a vizita Ironbeard's Tomb, obicei care a adus-o recent in mare pericol, dupa ce a fost luata prin surprindere de oozes ostile.",al={"sida","cine da misiunea","cine este sida"}},{q="Unde se afla Ironbeard's Tomb?",a="Ironbeard's Tomb se afla in tinuturile nord-estice din Wetlands, la sud de Dun Modr. Zona din jurul tumulului de piatra este invadata de geluri corozive din mlastina.",al={"locatia mormantului Ironbeard","unde se afla Ironbeard","unde sunt mocirlele"}},{q="Ce masa gelatinoasa a inghitit geanta Sidei?",a="Sida a intrat in panica in timpul atacului si nu poate deosebi creaturile. Oricare dintre masele gelatinoase ratacitoare care pandesc in afara mormantului Ironbeard's Tomb ar putea fi cea care ii adaposteste bunurile digerate.",al={"care zem","zemul cu sacul","unde este sacul"}},{q="De ce vizita Sida Ironbeard's Tomb?",a="Sida viziteaza saptamanal mormantul pentru a-i aduce omagii vechiului Dwarf ingropat acolo, dar traditia ei pasnica a fost intrerupta de aparitia neasteptata a maselor gelatinoase.",al={"de ce viziteaza sida mormantul","vizita saptamanala a sidei"}},{q="Ce se intampla dupa recuperarea sacului?",a="Dupa ce returneaza sacosa lipicioasa in Menethil Harbor, Sida ii varsa continutul pe jos ca sa-si recupereze lucrurile personale. Considerand ca recipientul distrus este prea dezgustator ca sa-l pastreze, ii ofera aventurierului care l-a recuperat punga curatata.",al={"ce era in geanta","recompensa din geanta"}},{q="Are legatura cu piticii Dark Iron din apropiere?",a="In timp ce Dun Modr, chiar la nord, este cuprins de conflict cu Dark Iron clan, masele gelatinoase care infesteaza Ironbeard's Tomb sunt pradatori salbatici ai mlastinii, originari din colturile umede si putrede ale Wetlands, nu soldati pitici.",al={"legatura cu dark iron","legatura cu dun modr"}}},fx={["93b8c575"]={q="De ce are nevoie Sida sa-si recupereze geanta?",a="In timpul vizitei saptamanale la Ironbeard's Tomb, Sida a fost luata prin surprindere de niste mase vascoase respingatoare. Cuprinsa de panica, si-a aruncat rucsacul asupra uneia dintre creaturi ca sa-i distraga atentia si sa poata scapa. Desi a iesit nevatamata din confruntare, continutul gentii este de neinlocuit pentru ea si isi doreste cu disperare sa-l recupereze inainte ca monstruozitatile acide sa-l digere cu totul.",al={"de ce isi vrea sida geanta inapoi","motivul pentru care sida vrea geanta","de ce sa iau geanta lui sida"}},["11eb18cd"]={q="Ce se afla in Sida's Bag?",a="Sida nu dezvaluie niciodata ce anume era in sac, ci doar insista ca are nevoie urgenta de continutul lui inapoi. Cand i-l aduci, varsa imediat pe jos continutul lipicios si-l strange, apoi iti da in schimb recipientul distrus si acoperit de mazga, fiindca nu mai are ce face cu pielea murdarita.",al={"ce se afla in geanta lui sida","continutul gentii lui sida","la ce foloseste geanta lui sida"}},["7f85207a"]={q="Ce sunt zemurile din Ironbeard's Tomb?",a="Mucusurile care se tarasc prin jurul mormantului Ironbeard's Tomb sunt monstruozitati lipsite de minte si nesatule, specifice zonelor umede si in descompunere din Wetlands. Atrase de ruina scufundata si de materia putrezita din apropiere de Dun Modr, devoreaza orice materie organica le iese in cale - inclusiv vizitatori neatenti precum Sida.",al={"mocirlele de la Ironbeard's Tomb","de ce sunt mocirle la mormantul lui Ironbeard","mocirle la mormantul lui Ironbeard"}}},fp="24,293,18.440.0,26.476.0,12.219.0,26.174.0,32.181.0,39.173.0,40.254.1,48.227.0"}
P.entries["quest:471"] = {n="Apprentice's Duties",s="Apprentice's Duties este un contract al Alliance oferit de tabacarul James Halloran din Menethil Harbor. Dupa ce si-a trimis tanarul ucenic in mlastini, unde baiatul a fost sfasiat de crocoliscuri uriase, Halloran angajeaza un aventurier capabil sa termine treaba periculoasa de recoltare si sa regleze socotelile.",h="Apprentice's Duties este un contract al Alliance oferit de tabacarul James Halloran din Menethil Harbor.",kw={"apprentice's duties","crocolisk","giant crocolisk","james halloran","prelucrarea pielii","menethil harbor","colibe de murloci","wetlands","piei de crocolisc tanar"},ang={["class:Hunter"]="Pradatorii de varf ai mlastinilor sunt tinte redutabile, iar urmarirea crocodiliscilor uriasi ajunsi la maturitate pune la incercare capacitatea unui urmaritor de a se orienta prin ape tulburi si printre vietuitoare agresive.",["faction:Alliance"]="Menethil Harbor este o veritabila legatura vitala intre Khaz Modan si restul Alliance, asa ca siguranta si autonomia mestesugarilor locali sunt esentiale pentru supravietuirea portului."},sec={{t="O ucenicie aspra",b="Negustorii din porturi de frontiera precum Menethil Harbor trebuie sa se bazeze pe materiile prime locale, insa mlastinile din jur sunt necrutatoare. James Halloran si-a trimis tanarul ucenic in tinuturile mlastinoase sa jupoaie crocodili uriasi din Wetlands. Cand baiatul nu s-a mai intors, Halloran a pornit sa-l caute si l-a gasit sfasiat ingrozitor de fiarele de prada."},{t="Blanuri si razbunare",b="Desi moasa locala crede ca ucenicul va supravietui, baiatul a fost mutilat si si-a pierdut un picior in atac. Avand nevoie sa-si refaca stocul si dorind sa se razbune pe bestiile care au sfasiat pe cineva pe care-l considera ca pe un fiu, Halloran ii angajeaza pe aventurierii calatori sa mearga spre nord de-a lungul coastei, sa treaca de colibele murlocilor si sa vaneze crocoliscurile uriase."}},faq={{q="Cine este James Halloran?",a="James Halloran este tabacar si pielar in Menethil Harbor. Pentru a-si sustine mestesugul, se bazeaza pe pieile animalelor salbatice din Wetlands.",al={"James Halloran","cine da sarcinile ucenicului","tabacarul din Menethil"}},{q="Ce s-a intamplat cu ucenicul lui Halloran?",a="Halloran si-a trimis ucenicul in mlastina sa jupoaie piei de la crocoliscii uriasi. Baiatul a fost atacat de pradatori si ranit grav, pierzandu-si in cele din urma un picior, desi moasa orasului se asteapta sa supravietuiasca.",al={"ce s-a intamplat cu ucenicul","cine a fost sfasiat","piciorul ucenicului"}},{q="Unde se gasesc crocodilii uriasi?",a="Crocodilii uriasi dau tarcoale mlastinilor si coastei nordice din Wetlands, chiar dincolo de asezarile murlocilor de pe tarm, la nord de Menethil Harbor.",al={"unde sunt crocodilii uriasi","locatia crocoliscului din mlastini","locul unde gasesti crocoliscul urias"}},{q="Ce misiune prealabila te conduce la aceasta sarcina?",a="Aceasta misiune este precedata de 'Young Crocolisk Skins', in care Halloran le cere mai intai aventurierilor sa vaneze crocolisci mai mici, inainte de a trece la exemplarele uriase care i-au ranit ucenicul.",al={"conditii pentru Apprentice Duties","misiunea precedenta","lantul de misiuni al crocodililor"}},{q="De ce mai vrea Halloran pieile dupa tragedie?",a="Halloran are inca o afacere de condus si comenzi de onorat, dar este manat si de furie. Se bucura sa aiba un aventurier care sa vaneze si sa ucida bestiile raspunzatoare de mutilarea baiatului pe care il iubeste ca pe propriul fiu.",al={"de ce sunt necesare pieile","motivul lui halloran"}},{q="Ii ofera Halloran o ucenicie?",a="Halloran glumeste pentru scurt timp ca te-ar lua drept nou ucenic dupa ce iti vede munca, dar renunta imediat la idee, observand ca esti mult prea in varsta si ca destinul tau este in mod clar altul.",al={"pot deveni ucenic","oferta de ucenicie"}}},fx={af87185e={q="La ce foloseste Giant Crocolisk Skin?",a="James Halloran este tabacar si pielar in Menethil Harbor. Confectioneaza bunuri rezistente din pieile fiarelor locale, iar pielea groasa si trainica recoltata de la crocodilii uriasi din Wetlands este materia prima a meseriei sale.",al={"la ce foloseste giant crocolisk skin","de ce piei","pielea de crocolisk a lui Halloran"}},["4e327c1e"]={q="Ce sunt crocoliscurile uriase?",a="Sunt reptile masive si pradatoare, originare din mlastinile si apele de coasta din Wetlands. Sunt extrem de teritoriale si vestite pentru agresivitatea lor; salasluiesc spre nord, de-a lungul coastei, dincolo de taberele murlocilor, reprezentand un pericol mortal pentru orice calator sau jupuitor incepator care se apropie prea mult.",al={"crocolisci uriasi din Wetlands","ce sunt crocodilii uriasi","crocolisci in Wetlands"}},["42f5987b"]={q="De ce are James Halloran nevoie de tine, in loc sa se ocupe singur de asta?",a="Ucenicul lui Halloran a fost sfasiat si si-a pierdut un picior in timp ce incerca sa duca sarcina la indeplinire, dovedind ca este mult prea periculoasa pentru un mestesugar obisnuit. Cu ucenicul in stare critica, sub ingrijirea moasei din partea locului, Halloran a ramas in Menethil Harbor ca sa-si supravegheze pravalie si sa vegheze asupra baiatului, apeland la un aventurier inarmat pentru a starpi fiarele in siguranta.",al={"de ce nu poate halloran sa obtina blanuri","de ce eu, halloran","de ce sa trimita un aventurier"}}},fp="19,296,22.331.0,21.386.0,22.164.0,39.221.0,39.143.0,43.179.0,57.199.0,42.194.0"}
P.entries["quest:472"] = {n="Fall of Dun Modr",s="Dun Modr, fortareata piticilor din nord, care vegheaza asupra Thandol Span, a cazut in urma unui atac violent al piticilor Dark Iron. Un supravietuitor grav ranit din Menethil Harbor cauta un aventurier din Alliance care sa se aventureze spre nord si sa afle daca comandantul Longbraid the Grim si vreun alt membru al garnizoanei au supravietuit.",h="Dun Modr, fortareata piticilor din nord, care vegheaza asupra Thandol Span, a cazut in urma unui atac violent...",kw={"dark iron","dun modr","harlo barnaby","longbraid the grim","menethil harbor","thandol span","wetlands"},ang={["faction:Alliance"]="Caderea lui Dun Modr intrerupe tranzitul terestru sigur dintre Ironforge si operatiunile Alliance din nordul zonei Arathi Highlands, lasand coridorul nordic vulnerabil la sabotaj.",["race:Dwarf"]="Masacrarea muntenilor din Ironforge si profanarea Dun Modr de catre rudele de clan din sud constituie o jignire amara si personala, care cere razbunare sangeroasa."},sec={{t="Un bastion nordic infrant",b="Dun Modr a fost multa vreme un punct de sprijin in nordul Khaz Modan, aparand drumul si podul esential care leaga Wetlands de Arathi Highlands, peste Thandol Span. In urma unei ambuscade chiar la pod, garnizoana s-a retras in graba pentru a se regrupa intre zidurile fortaretei. Inainte ca liniile defensive sa poata fi refacute, fortele Dark Iron au atacat in numar coplesitor, masacrand aparatorii si fortand evacuarea disperata."},{t="O fuga disperata",b="Harlo Barnaby, un tanar soldat din randul aparatorilor, a fost grav ranit cand un topor ratacit l-a lovit in spate in timpul retragerii haotice. Crezand ca ranile ii vor fi fatale, Longbraid the Grim si trupele ramase l-au legat pe Barnaby de ultimul lor cal teafar si l-au trimis spre sud, la Menethil Harbor. Barnaby a supravietuit incercarii, dar s-a trezit in taverna portului, mistuit de vinovatia supravietuitorului si fara sa stie daca vreunul dintre camarazii lui scapase cu viata din masacru."},{t="Ramasita sumbra",b="In adancul mlastinilor nordice, langa fortareata capturata, Longbraid the Grim este inca in viata si tine laolalta o mana de supravietuitori zdrentuiti. Desi este usurat sa afle ca tanarul Harlo a supravietuit ranii grave, comandantul veteran se confrunta cu o realitate tactica sumbra: Dun Modr se afla ferm sub control Dark Iron, iar salile sale sunt ocupate de talhari si sabotori care ameninta intregul coridor dintre Khaz Modan si tinuturile oamenilor din nord."}},faq={{q="Ce s-a intamplat cu Dun Modr?",a="Dun Modr a fost invadat si cucerit de piticii ostili Dark Iron. Garnizoana fusese deja atacata prin surprindere la Thandol Span, in apropiere, iar Dark Irons au asaltat orasul si au nimicit majoritatea regimentului de aparare inainte ca soldatii sa-si poata consolida apararea.",al={"de ce este distrusa Dun Modr","cine a atacat Dun Modr","povestea Dun Modr"}},{q="Cine este Harlo Barnaby?",a="Harlo Barnaby este un soldat din Ironforge stationat la Dun Modr, care abia a supravietuit caderii asezarii. Lovit in spate de un topor aruncat in timpul retragerii, a fost legat de singurul cal al garnizoanei, din ordinul comandantului sau, si trimis spre sud, la Menethil Harbor, pentru ingrijiri medicale.",al={"cine este Harlo","povestea lui Harlo Barnaby","soldatul ranit din Menethil"}},{q="Unde se afla Longbraid the Grim?",a="Comandantul Longbraid the Grim s-a refugiat in salbaticia de la marginea orasului ocupat Dun Modr, langa drumul principal din nord care urca spre Thandol Span.",al={"unde este longbraid","locatia lui longbraid","gaseste-l pe longbraid"}},{q="De ce este Dun Modr important din punct de vedere strategic?",a="Dun Modr este cea mai nordica asezare si fortificatie din Wetlands. Ea pazeste intrarea sudica a Thandol Span, singurul pod terestru care leaga Khaz Modan de Arathi Highlands si Lordaeron.",al={"de ce conteaza Dun Modr","legatura cu Thandol Span"}},{q="Cine sunt atacatorii de la Dun Modr?",a="Atacatorii sunt pitici Dark Iron, membri ai clanului perfid din sud, care au inaintat spre nord, in Wetlands, pentru a distruge infrastructura, precum Thandol Span, si a hartui teritoriul Ironforge.",al={"cine a cucerit dun modr","dark iron in wetlands"}},{q="Ce se intampla dupa ce-l gasesti pe Longbraid?",a="Dupa ce confirmi ca Longbraid este in viata si aduci vesti ca Barnaby a supravietuit, Longbraid te atrage intr-o misiune sumbra de razbunare si pedepsire a fortelor Dark Iron care ocupa ruinele din Dun Modr.",al={"urmare dupa caderea Dun Modr","ce urmeaza dupa caderea Dun Modr"}}},fx={b6379bde={q="De ce vrea Harlo Barnaby sa-l gasesti pe Longbraid?",a="Harlo a scapat ca prin minune de macelul de la Dun Modr, cu viata, dupa ce a fost lovit in spate de un topor ratacit chiar cand regimentul suna retragerea. Desi s-a trezit teafar in Menethil Harbor, este chinuit de soarta camarazilor sai. Refuza sa renunte la speranta ca comandantul sau, Longbraid, a supravietuit infrangerii si are nevoie disperata sa afle daca vreo ramasita a unitatii sale mai rezista in fata invadatorilor Dark Iron.",al={"de ce sa-l gasesc pe Longbraid","motivul lui Harlo Barnaby","de ce sa te trimit la Dun Modr"}},["67f9d3fa"]={q="De ce nu poate Harlo Barnaby sa-l caute singur pe Longbraid?",a="Ranile lui Harlo sunt mult prea grave ca sa poata calatori. Dupa ce a fost lovit in spate cu un topor Dark Iron in timpul fugii haotice din Dun Modr, camarazii sai supravietuitori abia au reusit sa-l lege de ultima lor calare, inainte ca el sa-si piarda cunostinta. Si-a revenit abia de curand in Menethil Harbor, slabit si plin de rani, fiind nevoit sa se bizuie cu totul pe aventurieri in putere, care sa marsaluiasca spre nord, in mlastinile ostile, in locul lui.",al={"de ce are Harlo nevoie de mine","de ce nu poate merge Harlo","de ce nu Harlo Barnaby"}}},fp="16,308,25.422.0,18.468.0,16.439.1,26.272.0,21.275.0,36.164.1,40.225.0,34.205.0,37.206.1"}
