P.entries["quest:505"] = {n="Syndicate Assassins",s="Magistrate Henry Maleb, numit de curand in Southshore dupa asasinarea magistratului precedent, crede ca Syndicate i-a platit pe ucigasi. Urmele au dus la o tabara Syndicate, la nord de Tarren Mill, iar Maleb vrea ca membrii de acolo sa fie ucisi.",h="Magistrate Henry Maleb, numit de curand in Southshore dupa asasinarea magistratului precedent, crede ca...",kw={"Alterac","talpas","Henry Maleb","magistrat","Southshore","Syndicate","Tarren Mill","hot"},sec={{t="Un magistrat ucis",b="Magistrate Henry Maleb este noul magistrat din Southshore, numit dupa asasinarea magistratului precedent. Asasinii nu au fost gasiti niciodata, dar Maleb este aproape sigur ca Syndicate i-a angajat. Syndicate este o banda de hoti condusa de nobili ticalosi din Alterac, un regat care a cazut intre timp. Ultimele indicii ale lui Maleb duceau spre o tabara Syndicate la nord de Tarren Mill, ocupata de Horde, iar Maleb iti cere sa-i ucizi pe membrii Syndicate gasiti acolo."}},faq={{q="De ce vrea Magistrate Henry Maleb ca Syndicate sa fie ucis?",a="Fostul magistrat din Southshore a fost asasinat, iar Maleb este aproape sigur ca Syndicate a angajat ucigasii, care nu au fost gasiti niciodata.",al={"de ce sa ucid membrii sindicatului","motivul sindicatului","cine l-a ucis pe magistrat"}},{q="Cine conduce Syndicate?",a="Syndicate este condus de nobili ticalosi din regatul cazut Alterac, iar membrii sai sunt hoti.",al={"cine conduce Syndicate","liderii Syndicate","Syndicate din Alterac"}},{q="Unde se afla tabara Syndicate?",a="La nord de Tarren Mill, pe care Horde l-a ocupat. Ultimele indicii ale lui Maleb duceau acolo.",al={"unde sunt talharii Syndicate","locatia taberei Syndicate","unde gasesc hotii Syndicate"}}},fp="19,239,21.467.0,57.138.0,24.84.0,28.81.0"}
P.entries["quest:5052"] = {n="Blood Shards of Agamaggan"}
P.entries["quest:506"] = {n="Blackmoore's Legacy",s="Gol'dir, eliberat din Syndicate, are informatii pentru Krusk din Tarren Mill. Liderul Syndicate, Aliden Perenolde, l-a vizitat pe Gol'dir si a vorbit despre inrobirea orcilor care i se impotrivesc; a adus cu el o fata pe nume Elysa, care purta pandantivul dorit de Warchief.",h="Gol'dir, eliberat din Syndicate, are informatii pentru Krusk din Tarren Mill.",kw={"aliden","blackmoore","elysa","goldir","krusk","mostenire","pandantiv","perenolde","syndicate","tarren mill"},sec={{t="O vizita la prizonier",b="Cu o zi sau doua in urma, capul Syndicate a venit sa-l viziteze pe Gol'dir. Il chema Aliden Perenolde si se dadea drept lordul tinutului. I-a marturisit ca intentiona sa-i inrobeasca pe orcii care i se impotriveau, asa cum planuisera odinioara tatal sau si detestatul Blackmoore, mentorul sau. Gol'dir te trimite sa-i duci vestea lui Krusk, in Tarren Mill, si va porni la drum dupa ce-si termina treburile de aici."},{t="Pandantivul lui Elysa",b="Mai important, Perenolde si-a adus amanta, o fata firava pe nume Elysa. La gatul ei atarna pandantivul dorit de Warchief."},{t="Raspunsul lui Krusk",b="Krusk este furios din cauza indraznelii oamenilor obraznici si jura ca orcs nu se vor supune niciodata. Krusk declara ca impotrivirea fata de ei este acum un obiectiv, alaturi de recuperarea talismanului dorit de Warchief, si ca, indeplinind unul dintre aceste obiective, il vor indeplini si pe celalalt."}},faq={{q="Cine ofera aceasta misiune?",a="Orcul Gol'dir, dupa ce l-ai eliberat din Syndicate.",al={"cine da blackmoore's legacy","cel care ofera misiunea","goldir"}},{q="Cine ar trebui sa primeasca vestea?",a="Krusk, in Tarren Mill.",al={"unde ma duc","cu cine vorbesc","locatia predarii"}},{q="Ce i-a dezvaluit Aliden Perenolde lui Gol'dir?",a="Perenolde, conducatorul Syndicate, i-a marturisit ca intentiona sa-i inrobeasca pe orcii care i se impotriveau, urmand planurile tatalui si mentorului sau, dispretuitul Blackmoore.",al={"planul lui Perenolde","planurile Syndicate","ce a spus Perenolde"}},{q="Ce altceva a observat Gol'dir in timpul vizitei?",a="Perenolde si-a adus amanta, o fata pe nume Elysa, care purta la gat pandantivul ravnit de Warchief.",al={"colierul elysa","pandantivul warchief","stapana"}},{q="Ce a precedat aceasta misiune?",a="Gol'dir, in care l-ai eliberat pe Gol'dir din mainile Syndicate.",al={"misiunea precedenta","ce a fost inainte"}}},fp="19,270,23.398.0,15.129.0,14.266.1,21.60.0,28.22.0,44.172.0,46.110.0,28.55.0"}
P.entries["quest:5061"] = {n="Aquatic Form"}
P.entries["quest:5062"] = {n="Sacred Fire"}
P.entries["quest:5064"] = {n="Grimtotem Spying",s="Cliffwatcher Longhorn le cere campionilor Horde sa se infiltreze in Darkcloud Pinnacle si sa afle ce comploteaza clanul evaziv Grimtotem. Trei curieri necunoscuti au fost vazuti venind pe platou, lasand in urma corespondenta bine pazita, imprastiata prin satul lor de pe varful muntelui. Dezvaluirea acestor bilete secrete scoate la iveala un complot care ameninta asezarile tauren din Thousand Needles.",h="Cliffwatcher Longhorn le cere campionilor Horde sa se infiltreze in Darkcloud Pinnacle si sa afle ce...",kw={"cliffwatcher longhorn","darkcloud pinnacle","freewind post","grimtotem","notite secrete","spionaj","tauren","thousand needles"},ang={["class:Rogue"]="Recuperarea celor trei cufere de pe podurile suspendate si din cladirile intens pazite ale Darkcloud Pinnacle este o operatiune sub acoperire ideala, rasplatind discretia mai degraba decat confruntarea directa.",["faction:Horde"]="Freewind Post este o legatura vitala pentru Horde in sudul Kalimdor. Orice complot subversiv al Grimtotem din Darkcloud Pinnacle pune in pericol liniile fragile de aprovizionare dintre Barrens si Tanaris.",["race:Tauren"]="Tradarea clanului Grimtotem ii loveste adanc pe tauren, a caror societate pretuieste armonia si onoarea familiei. Descoperirea faptului ca rudele se intalnesc pe ascuns cu conspiratori necunoscuti ameninta tot ce a cladit Cairne Bloodhoof."},sec={{t="Ochi in vant",b="Freewind Post se afla intr-o pozitie precara, pe turle inalte, insa aparatorii sai trebuie sa fie mereu cu ochii in patru din cauza rudelor ostile. Clanul Grimtotem a avut de mult o atitudine incordata si plina de resentimente fata de Horde, ramanand in fortaretele sale izolationiste din varful Darkcloud Pinnacle. Cliffwatcher Longhorn a observat o schimbare in comportamentul lor cand trei agenti misteriosi au sosit in saptamani consecutive, intalnindu-se in secret cu conducerea clanului. Longhorn banuieste ca acesti emisari au adus ordine de mobilizare sau aliante menite sa submineze prezenta Thunder Bluff in canion."},{t="Infiltrarea in Darkcloud Pinnacle",b="Darkcloud Pinnacle este o retea fortificata de platouri stancoase abrupte, legate prin poduri de franghie si lemn. Pentru a patrunde in sat trebuie sa infrunti patrulele dese de razboinici si samani ostili Grimtotem. Cercetasii lui Longhorn au confirmat ca mesajele misterioase erau incuiate in cufere separate, raspandite prin locuintele centrale si pe marginile avanpostului. Pentru a pune mana pe cele trei biletele secrete, trebuie sa te strecori sau sa lupti prin intreaga asezare si sa iei comunicarile private ale clanului de sub nasul strajerilor vigilenti."},{t="Prevestiri sumbre",b="Intoarcerea celor trei biletele recuperate la Cliffwatcher Longhorn confirma cele mai negre temeri ale celor din Freewind Post. Corespondenta dezvaluie ca Grimtotem nu doar se lauda; colaboreaza activ cu agenti din afara pentru o actiune iminenta. Desi intreaga amploare a uneltirilor lor ramane invaluita in mister, Longhorn incepe imediat sa pregateasca planuri de rezerva pentru a proteja avanposturile canionului de o tradare neasteptata."}},faq={{q="Cine trimite agenti sa se intalneasca cu Grimtotem?",a="Cliffwatcher Longhorn stie doar ca trei agenti de origine necunoscuta au fost vazuti vizitand Darkcloud Pinnacle in ultimele saptamani. Identitatea exacta a celor care ii sustin este tinuta strict secreta in notele pazite.",al={"cine i-a vizitat pe Grimtotem","agentii secreti Grimtotem","cine a trimis biletele"}},{q="Unde se afla Darkcloud Pinnacle?",a="Darkcloud Pinnacle se afla in vestul lui Thousand Needles, la sud-est de Great Lift. O carare marcata de un totem albastru urca pe stancile platoului pana in sat, unde punti de lemn leaga cateva varfuri inalte.",al={"unde este darkcloud pinnacle","cum ajung la darkcloud pinnacle","intrarea in darkcloud pinnacle"}},{q="De ce sunt Grimtotem ostili fata de ceilalti tauren?",a="Grimtotem cred ca tauren sunt superiori tuturor celorlalte rase si resping cu inversunare alianta lui Cairne Bloodhoof cu Horde. In timp ce unii Grimtotem traiesc intr-o pace fragila in Thunder Bluff, clanuri precum cele de pe Darkcloud Pinnacle actioneaza cu ostilitate deschisa atat fata de Horde, cat si fata de Alliance.",al={"de ce urasc Grimtotem Hoarda","Grimtotem contra Thunder Bluff","sunt Grimtotem rai"}},{q="Cine ofera misiunea Grimtotem Spying?",a="Cliffwatcher Longhorn ofera misiunea la Freewind Post, in Thousand Needles, dar numai dupa ce ti-ai dovedit seriozitatea indeplinind sarcini anterioare pentru avanpost.",al={"cine incepe grimtotem spying","cel care da misiunea grimtotem spying"}},{q="Ce misiuni prealabile trebuie indeplinite inaintea acesteia?",a="Trebuie sa finalizezi 'Message to Freewind Post' si 'Pacify the Centaur' inainte ca Cliffwatcher Longhorn sa aiba suficienta incredere in tine pentru a-ti incredinta misiunea de spionaj impotriva lui Grimtotem.",al={"cerinte preliminare pentru spionajul Grimtotem","cum deblochezi spionajul Grimtotem","lantul de misiuni de spionaj Grimtotem"}},{q="Ce se intampla cand predai cele trei biletele secrete?",a="Dupa ce citeste continutul, Cliffwatcher Longhorn reactioneaza socat si declara ca vestile sunt sumbre. Recunoaste ca Freewind Post trebuie sa-si pregateasca urgent apararea impotriva oricarui plan pus la cale de Grimtotem.",al={"finalizarea misiunii Grimtotem Spying","ce scrie in notite"}}},fx={e48c00e3={q="De ce vrea Cliffwatcher Longhorn ca acest lucru sa fie facut?",a="Cliffwatcher Longhorn a vazut trei agenti misteriosi vizitand Darkcloud Pinnacle in ultimele saptamani, pentru a se intalni pe ascuns cu clanul Grimtotem. Cei din Grimtotem sunt vestiti pentru tradarea si lipsa lor de incredere, iar intalnirile clandestine arata ca se tese o conspiratie tacuta in Needles. Longhorn are nevoie sa fie recuperate acele mesaje pazite, inainte ca planul lor sa-i ia pe nepregatite pe cei din Freewind Post.",al={"de ce spionajul grimtotem","motivele lui Cliffwatcher Longhorn","de ce sa spionezi grimtotem"}},["219e0f02"]={q="Impotriva cui esti trimis la Darkcloud Pinnacle?",a="Esti trimis direct in inima Darkcloud Pinnacle, un sat fortificat locuit de Clanul Grimtotem. Spre deosebire de triburile pasnice aflate sub conducerea lui Cairne Bloodhoof, acest clan tauren agresiv si secretos isi apara cu inversunare teritoriul de-a lungul piscurilor din Thousand Needles. Pentru a te infiltra in asezarea lor, trebuie sa infrunti santinelele si sa le jefuiesti cuferele pazite, ca sa descoperi ce ascund.",al={"cine se afla la darkcloud pinnacle","pe cine infiltrezi","tinta spionajului grimtotem"}},c76c115b={q="De ce iti incredinteaza Cliffwatcher Longhorn aceasta misiune?",a="Ti-ai dovedit deja loialitatea si forta ajutand Freewind Post si infruntand amenintarea centaurilor locali. Infiltrarea unei mese Grimtotem puternic fortificate este o operatiune secreta delicata si mortala, nu un atac deschis pe care sa-l intreprinda garzile obisnuite ale avanpostului. Longhorn are nevoie de un strain cu experienta si capabil, care sa se poata strecura inauntru, sa puna mana pe documente si sa supravietuiasca.",al={"de ce te trimite Longhorn","de ce eu pentru Grimtotem Spying"}}},fp="16,381,16.574.0,34.512.0,13.410.1,49.216.0,36.216.0,46.303.0,37.166.0,54.181.0,53.213.1"}
P.entries["quest:507"] = {n="Lord Aliden Perenolde",s="Krusk il vrea mort pe Lord Aliden Perenolde, liderul Syndicate, si vrea recuperat pandantivul Warchief-ului. Conacul lui se afla la nord, pe malul Lordamere Lake, iar amanta lui, Elysa, este cea pe care trebuie s-o intrebi despre pandantiv.",h="Krusk il vrea mort pe Lord Aliden Perenolde, liderul Syndicate, si vrea recuperat pandantivul Warchief-ului.",kw={"alterac mountains","dandred's fold","elysa","krusk","lord aliden perenolde","lordamere lake","syndicate","pandantivul Tarethei"},sec={{t="Lordul Syndicate",b="Dupa Blackmoore's Legacy, Krusk spune ca Perenolde trebuie sa moara si ca lumea trebuie sa scape de ticalosia lui. Conacul se afla la oarecare distanta spre nord, pe malul Lordamere Lake, la Dandred's Fold. Dupa ce-ti duci treaba la bun sfarsit, trebuie sa-i pui amantei sale, Elysa, intrebarile despre pandantivul lui Taretha, pe care il doreste Warchief."},{t="O stapana inspaimantata",b="Elysa este ingrozita cand vii la ea. Plange si spune ca nu a vrut niciodata sa faca rau poporului tau, ca Perenolde a tinut-o impotriva vointei ei si implora sa fie crutata."}},faq={{q="Cine te trimite sa-l ucizi pe Lord Aliden Perenolde?",a="Krusk, dupa ce termini Blackmoore's Legacy.",al={"cine ofera misiunea Lord Aliden Perenolde","unde il gasesc pe Lord Aliden Perenolde"}},{q="Unde se afla Lord Aliden Perenolde?",a="In conacul lui de pe tarmul Lordamere Lake, spre nord. Se afla la etaj, in casa din Dandred's Fold.",al={"unde se afla perenolde","locatia lui lord aliden perenolde","conacul din dandred's fold"}},{q="Cine este Lord Aliden Perenolde?",a="Liderul Syndicate.",al={"cine este aliden perenolde","povestea lui perenolde"}},{q="Ce obiect esti trimis sa recuperezi dupa ce-l ucizi pe Perenolde?",a="Pandantivul lui Taretha, pe care il doreste Warchief. Trebuie sa o intrebi pe amanta lui Perenolde, Elysa, despre el.",al={"ce pandantiv vrea Thrall","ce are Perenolde"}},{q="Ce urmeaza dupa aceasta misiune?",a="Taretha's Gift, urmatoarea parte a lantului.",al={"ce urmeaza dupa Lord Aliden Perenolde","misiunea urmatoare dupa Perenolde"}}},fp="21,219,25.313.0,21.165.1,44.51.0,39.112.0,29.28.0,59.100.0,28.43.0"}
P.entries["quest:508"] = {n="Taretha's Gift",s="Dupa etapa cu Lord Aliden Perenolde, Elysa renunta la pandantivul lui Taretha si cere doar sa fie lasata in pace. Il duci inapoi lui Krusk, in Tarren Mill.",h="Dupa etapa cu Lord Aliden Perenolde, Elysa renunta la pandantivul lui Taretha si cere doar sa fie lasata in...",kw={"aliden perenolde","elysa","hillsbrad foothills","krusk","taretha's gift","colierul lui taretha","tarren mill","thrall"},sec={{t="Pandantivul",b="Elysa nu doreste sa pastreze nicio amintire despre Lord Aliden Perenolde. Poti lua pandantivul, spune Elysa si te roaga doar sa pleci apoi in pace. Candva i-a apartinut lui Taretha Foxton, prietena din copilarie a lui Thrall. Trebuie sa-l duci la Krusk, in Tarren Mill, pentru a se intoarce la orcs."},{t="Verdictul lui Krusk",b="Krusk considera ciudat ca Warchief ar face atatea eforturi pentru un fleac. Krusk nu pretinde ca-l intelege pe Thrall, dar ii va urma ordinele oricum si iti lauda munca, fiind sigur ca Thrall se va bucura sa afle."}},faq={{q="Cine iti da colierul lui Taretha?",a="Elysa renunta la el fara sa protesteze, nedorind sa pastreze nicio amintire despre Lord Aliden Perenolde si cerand doar sa fie lasata in pace.",al={"cine da pandantivul","de unde obtii colierul lui Taretha","cine incepe Taretha's Gift"}},{q="Cui trebuie inapoiat colierul?",a="Krusk, in Tarren Mill.",al={"cine preda taretha's gift","unde duc pandantivul","locatia lui krusk"}},{q="A cui era pandantivul?",a="Ii apartinuse lui Taretha Foxton, prietena lui Thrall din copilarie, iar intoarcerea lui reda orcilor o amintire pretioasa a ei.",al={"de ce vrea Thrall pandantivul","semnificatia colierului lui Taretha Foxton","ce este Taretha's Gift"}},{q="Ce urmeaza inainte de aceasta parte a lantului?",a="Etapa care implica Lord Aliden Perenolde. Aceasta este ultima parte a seriei.",al={"misiunea anterioara","conditie preliminara pentru Taretha's Gift"}}},fp="14,153,11.292.0,15.230.1,34.115.0,38.22.0,21.118.0,36.77.0"}
P.entries["quest:5088"] = {n="Arikara",s="\"Arikara\" este deznodamantul unei misiuni prevestitoare incredintate de Magatha Grimtotem in Thunder Bluff. Avertizand ca un sarpe al vantului stravechi ar putea sa-l vaneze pe inaltul sef Cairne Bloodhoof, batrana samana trimite aventurieri Horde sa invoce si sa ucida bestia pe turlele funerare din Thousand Needles.",h="\"Arikara\" este deznodamantul unei misiuni prevestitoare incredintate de Magatha Grimtotem in Thunder Bluff.",kw={"arikara","cairne bloodhoof","darkcloud pinnacle","incendia powder","magatha grimtotem","motega firemane","thousand needles","whitereach post","sarpe de vant"},ang={["class:Shaman"]="Aventurierii Shaman vor observa tensiunea dintre ritualurile elementale si intrigile politice, precum si reticenta lui Motega de a contesta autoritatea spirituala fara egal a lui Magatha.",["faction:Horde"]="Jurati sa-l apere pe Cairne Bloodhoof, razboinicii Horde pornesc fara ezitare spre Thousand Needles pentru a inlatura orice amenintare la adresa venerabilului High Chieftain.",["race:Tauren"]="Pentru tauren, misiunea atinge conflictul dintre vechile rituri stramosesti si schimbarile politice care au loc sub conducerea lui Cairne Bloodhoof, mijlocite de cei mereu calculati din Grimtotem."},sec={{t="O fiara in fum",b="Dupa ce obtine pulberea rafinata de Incendia, Magatha Grimtotem vrajeste reactivul ca sa-l transforme intr-un catalizator de invocare. Ea avertizeaza ca vechile traditii tauren s-au schimbat prea repede sub noua alianta cu Horde, starnind razbunarea lui Arikara, un spirit feroce de sarpe al vantului. Magatha ii indruma pe eroi spre sud, in canionul batut de vanturi din Thousand Needles, cerandu-le sa arunce pulberea pe un rug ritualic aflat printre locurile de inhumare inaltate din Darkcloud Pinnacle."},{t="Indoieli la Whitereach Post",b="Dupa ce ucid sarpele de pe acul funerar si ii iau pielea, aventurierii ii duc ramasitele lui Motega Firemane, la Whitereach Post. In loc sa-si arate usurarea, Motega isi exprima nedumerirea sincera. Nu-i vine sa creada ca un spirit primordial precum Arikara ar nutri dusmanie fata de Cairne Bloodhoof. Totusi, nefiind dispus sa puna fatis la indoiala statutul Magathei de cea mai puternica samana a tribului, Motega isi lasa banuielile deoparte si il rasplateste pe campion pentru ca l-a aparat pe capetenie."}},faq={{q="Cine este Arikara?",a="Arikara este un sarpe al vantului puternic, invocat in varful Darkcloud Pinnacle, in Thousand Needles. Magatha Grimtotem sustine ca fiara a fost impinsa la razbunare de indepartarea moderna de traditiile taurenilor.",al={"ce este arikara","povestea lui arikara","cine este sarpele"}},{q="De ce vrea Magatha Grimtotem ca Arikara sa moara?",a="Magatha sustine ca Arikara il vaneaza pe Cairne Bloodhoof, Marele sef de trib al taurenilor. Te trimite sa distrugi sarpele cu pulbere Incendia vrajita, inainte ca acesta sa ameninte conducatorul din Thunder Bluff.",al={"motivul Magatha","de ce sa-l omori pe Arikara","de ce sa-l invoci pe Arikara"}},{q="Unde se afla focul sacru pentru a o invoca?",a="Focul sacru al vietii, stins, se afla in varful unei turle izolate din Darkcloud Pinnacle, in Thousand Needles, o masa de pamant inalta folosita de taurenii locului pentru a-si ingropa mortii.",al={"locatia lui Arikara","unde o invoc pe Arikara","locatia Sacred Fire of Life"}},{q="De ce priveste Motega Firemane vanatoarea cu scepticism?",a="Magatha se teme ca Arikara l-ar putea urmari pe Cairne si iti cere sa-i aduci lui Motega dovada vanatorii. Reactia lui Motega se dezvaluie cand ii predai ramasitele.",al={"reactia lui Motega","de ce e Motega confuz","Cairne si Arikara au sens"}},{q="Este Cairne cu adevarat in pericol din cauza lui Arikara?",a="Magatha spune ca se teme ca Arikara il pandeste pe Cairne. Misiunea iti cere sa actionezi in urma avertismentului ei; nu confirma pericolul in mod independent.",al={"a fost Cairne cu adevarat vanat","il voia Arikara pe Cairne","minte Magatha"}},{q="Care este misiunea anterioara din acest lant?",a="Aceasta misiune urmeaza direct dupa \"Sacred Fire\", in care aventurierii culeg Incendia Agave din Boiling Pool, in Thousand Needles, pentru ca Magatha Grimtotem sa o transforme prin vrajire in pulbere Incendia.",al={"cerinta preliminara pentru Arikara","misiunea dinaintea lui Arikara","misiunea Focul sacru"}}},fx={["4b4aa583"]={q="La ce foloseste Arikara Serpent Skin?",a="Pielea sarpelui este o dovada fizica de netagaduit ca spiritul razbunator a fost invocat si ucis. Magatha Grimtotem te trimite sa-i duci ramasitele direct lui Motega Firemane, la Whitereach Post, dovedind astfel ca presupusa amenintare care-l pandeste pe Marele Capetenie Cairne Bloodhoof a fost nimicita.",al={"arikara serpent skin","piele de sarpe arikara","de ce pielea lui arikara"}}},fp="7,292,20.477.0,24.478.1,15.199.0,45.201.0,47.170.0,45.155.1,42.144.1,41.182.0"}
P.entries["quest:509"] = {n="Elixir of Agony",s="In Tarren Mill, Apothecary Lydon recruteaza aventurieri Horde pentru a aduna ciuperci toxice de la o ferma napadita din Hillsbrad Foothills. Aceste Mudsnout Blossoms virulente sunt materie prima esentiala pentru experimentele chimice sinistre ale Royal Apothecary Society. Amestecul rezultat ar urma sa sprijine planul pe termen lung al lui Lady Sylvanas de a-i eradica atat pe cei vii, cat si Scourge.",h="In Tarren Mill, Apothecary Lydon recruteaza aventurieri Horde pentru a aduna ciuperci toxice de la o ferma...",kw={"apothecary lydon","elixir of agony","hillsbrad","mudsnout blossom","nethander stead","noua plaga","royal apothecary society","tarren mill"},ang={["faction:Horde"]="Emisarii Horde care isi desfasoara activitatea in Tarren Mill trebuie sa gaseasca un echilibru intre ajutorul oferit aliatilor lor Forsaken si realitatea tulburatoare a experimentelor chimice ale acestora.",["profession:Herbalism"]="Herbalistii si culegatorii vor recunoaste Mudsnout Blossom drept o specie fungica rara si extrem de toxica, ce prospera in solul necultivat, contaminat de prezenta gnollilor.",["race:Undead"]="Pentru agentii Forsaken, sprijinirea lui Lydon contribuie direct la munca vitala a Royal Apothecary Society de a apara Lordaeron atat de oameni, cat si de Lich King."},sec={{t="O molima in devenire",b="In timp ce Scourge devasteaza nordul, iar Alliance se agata de orase precum Southshore, Forsaken isi urmeaza propria solutie bine calculata: crearea unei molime letale, concepute dupa nevoile lor. Lucrand din Tarren Mill, Apothecary Lydon trudeste sub porunca Dark Lady. Desi personal este cinic in privinta muncii migaloase de alchimie, Lydon aduna cu sarguinta toxine organice puternice din imprejurimi, pentru a prepara elixire care sa grabeasca nimicirea dusmanilor Sylvanas."},{t="Campurile de la Nethander Stead",b="La sud de Tarren Mill si la est de rau se afla Nethander Stead, o ferma omeneasca abandonata, acum cotropita de gnollii feroce Mudsnout. Printre murdarie si pamantul neingrijit, infloresc ciuperci ciudate si rau mirositoare, cunoscute sub numele de Mudsnout Blossoms. Aceste ciuperci mari si intepatoare contin otrava organica concentrata, foarte cautata de Royal Apothecary Society. Pentru a le procura, trebuie strabatute haite de gnolli sau strecurat pe furis printre taberele lor darapanate."}},faq={{q="Cine este Apothecary Lydon?",a="Apothecary Lydon este un alchimist al Royal Apothecary Society, stationat la Tarren Mill, in Hillsbrad Foothills. Lucrand in numele lui Lady Sylvanas Windrunner, indatoririle sale se axeaza pe perfectionarea amestecurilor letale si crearea unei noi plagi care sa-i invinga atat pe muritorii vii, cat si pe Scourge.",al={"lydon","cine este lydon","povestea apothecary lydon"}},{q="La ce se folosesc florile Mudsnout Blossom?",a="Mudsnout Blossoms sunt ciuperci otravitoare, urat mirositoare, culese din Nethander Stead. Apothecary Lydon le foloseste proprietatile toxice puternice si naturale ca ingredient de baza pentru a prepara Elixir of Agony, parte a cercetarilor mai ample ale Forsaken in domeniul razboiului chimic si biologic.",al={"mudsnout blossoms","la ce folosesc ciupercile","folosirea florii"}},{q="Unde se afla Nethander Stead?",a="Nethander Stead este o ferma cotropita de vegetatie, situata la sud de Tarren Mill si la est de raul important care trece pe langa Southshore. Ferma a fost ocupata de gnolli Mudsnout agresivi, care pazesc ogoarele unde cresc ciupercile.",al={"locatia lui nethander stead","unde se afla nethander stead","unde se afla gnolii"}},{q="De ce vor Forsaken sa creeze o plaga noua?",a="Lady Sylvanas si Forsaken cauta o arma suficient de puternica pentru a nimici atat Scourge, neobosit, cat si rasele vii ostile din Alliance. Prin crearea propriei molime, Royal Apothecary Society urmareste sa asigure suveranitatea si supravietuirea celor din Forsaken in Lordaeron.",al={"de ce sa creezi o plaga","motivul plagi Forsaken","plaga Sylvanas"}},{q="De ce se plange Lydon ca trebuie sa prepare aceste elixire?",a="Lydon este oarecum obosit si macabru, remarcand ca oamenii si Scourge sunt deja hotarati sa se macelareasca intre ei fara ajutor din afara. Totusi, fiindca Lady Sylvanas vrea sa le grabeasca distrugerea reciproca, el se supune ordinelor si continua sa prepare bauturi mortale.",al={"atitudinea lui Lydon","de ce este Lydon cinic"}},{q="Ce se intampla dupa ce aduni florile?",a="Dupa ce primeste Mudsnout Blossoms, Lydon trece la prepararea amestecului toxic si, in scurt timp, are nevoie de ingrediente suplimentare si de teste pe teren pentru a se asigura ca elixirul atinge puterea letala maxima.",al={"urmatoarea misiune","ce urmeaza dupa Elixir of Agony"}}},fx={["744a331d"]={q="Cine pazeste Mudsnout Blossoms la Nethander Stead?",a="Campurile de la Nethander Stead au fost cotropite de gnolli Mudsnout. Aceste creaturi murdare cultiva ciupercile intepatoare care cresc pe intreaga ferma sau le pazesc cu inversunare, transformand orice incercare de a le culege intr-o incursiune primejdioasa pe teritoriul revendicat de ele.",al={"ce pazeste Mudsnout Blossom","dusmanii de la Nethander Stead","gnolii Mudsnout"}}},fp="15,377,22.501.0,29.448.0,24.280.0,36.270.0,33.226.0,48.283.0,59.277.0,43.197.0"}
P.entries["quest:510"] = {n="Foreboding Plans",s="Documentele Syndicate contin o lista cu proviziile cerute de Syndicate, de care aveau nevoie in graba pentru ceea ce actele numesc o intreprindere importanta impotriva Southshore. Magistrate Henry Maleb din Southshore le asteapta.",h="Documentele Syndicate contin o lista cu proviziile cerute de Syndicate, de care aveau nevoie in graba pentru...",kw={"alterac mountains","foreboding plans","magistrate henry maleb","southshore","syndicate","documentele syndicate"},sec={{t="Lista de provizii",b="Documentele contin o lista de provizii solicitate. Unele sunt banale: hrana, arme si imbracaminte. Altele sunt mai neobisnuite: masti, ulei si otrava. Ceea ce iese cel mai mult in evidenta este urgenta: actele spun ca proviziile erau necesare in curand, pentru o actiune importanta impotriva Southshore. Magistrate Henry Maleb din Southshore este destinatarul lor."},{t="Verdictul lui Maleb",b="Maleb citeste documentele si le gaseste foarte tulburatoare. Din ce spun acestea si din faptele din trecut ale Syndicate, Maleb concluzioneaza ca acesti talhari au pornit razboi impotriva orasului."}},faq={{q="Ce spun documentele Syndicate?",a="Ei enumera proviziile cerute: lucruri obisnuite, precum hrana, arme si imbracaminte, dar si altele neobisnuite, precum masti, ulei si otrava. Documentele subliniaza ca erau necesare in curand pentru o operatiune importanta impotriva Southshore.",al={"ce sunt foreboding plans","continutul documentelor syndicate","ce se afla in planuri"}},{q="Cui ar trebui sa-i fie aratate aceste planuri?",a="Magistrate Henry Maleb, in Southshore.",al={"cui trebuie sa-i duc planurile","predarea Foreboding Plans","unde duc planurile"}}},fp="16,210,15.345.0,15.186.1,36.217.0,27.37.0"}
P.entries["quest:511"] = {n="Encrypted Letter",s="Printre documentele Syndicate, una dintre scrisorile de pe o masa este criptata si de neinteles. Trebuie sa i-o arati lui Loremaster Dibbs in Southshore.",h="Printre documentele Syndicate, una dintre scrisorile de pe o masa este criptata si de neinteles.",kw={"Alterac","scrisoare criptata","Hillsbrad Foothills","Loremaster Dibbs","Southshore","documentele Syndicate"},sec={{t="O scrisoare pe care nimeni n-o poate citi",b="Printre documentele Syndicate se afla un tabel cu litere, iar una dintre ele este criptata si de neinteles. Trebuie sa i-l arati lui Loremaster Dibbs din Southshore."},{t="Ce crede Dibbs despre asta",b="Dibbs cerceteaza mai atent si recunoaste ca nu a mai vazut pana acum acest tip de criptare. Dibbs marturiseste ca mai are mult de invatat."}},faq={{q="De unde provine scrisoarea?",a="Este una dintre scrisorile de pe masa printre documentele Syndicate, iar aceasta este criptata.",al={"originea scrisorii","unde gasesc scrisoarea","inceputul scrisorii criptate"}},{q="Cui ii este dusa scrisoarea?",a="Loremaster Dibbs, in Southshore.",al={"cine citeste scrisoarea","cine o poate descifra","scrisoarea lui dibbs"}}},fp="16,147,24.157.0,22.146.1,32.93.0,27.31.0"}
P.entries["quest:512"] = {n="Noble Deaths",s="Magistrate Henry Maleb se teme ca liderii Syndicate vor sa distruga Southshore si vrea sa fie doborati inainte ca planurile lor sa se implineasca. Trebuie sa te indrepti spre nord, in Alterac Mountains, la ruinele din Strahnbrad, unde se crede ca Syndicate si-a stabilit cartierul general.",h="Magistrate Henry Maleb se teme ca liderii Syndicate vor sa distruga Southshore si vrea sa fie doborati...",kw={"muntii alterac","inel cu sigiliu alterac","henry maleb","noble deaths","southshore","strahnbrad","syndicate"},sec={{t="Vanatoarea liderilor Syndicate",b="Dupa Foreboding Plans, Magistrate Henry Maleb din Southshore vrea ca liderii Syndicate sa fie inlaturati inainte ca planurile lor sa se implineasca. Asasinii din Syndicate raspund in fata fostilor nobili din Alterac, care s-ar putea ascunde sub infatisarea unor agenti de rand. Un nobil poate fi recunoscut dupa inelul cu sigiliu pe care il poarta. Maleb iti cere sa-i aduci sapte inele cu sigiliu din Alterac la Southshore si crede ca Syndicate si-a stabilit cartierul general in ruinele din Strahnbrad, spre nord, in Alterac Mountains."},{t="Speranta lui Maleb",b="Maleb este convins ca Syndicate, lipsit de nobilime, nu ar mai putea actiona hotarat si s-ar reduce la niste batausi de rand."}},faq={{q="Cine te trimite la Strahnbrad?",a="Magistrate Henry Maleb din Southshore te trimite spre nord, sa ataci liderii din spatele Syndicate.",al={"cel care da misiunea","cine ofera Noble Deaths","misiunea henry maleb"}},{q="Unde se afla nobilii din Syndicate?",a="Maleb crede ca Syndicate si-a stabilit cartierul general printre ruinele din Strahnbrad, la nord, in Alterac Mountains.",al={"unde sa mergi","locatia Strahnbrad","locatia nobililor din Syndicate"}},{q="Cum poti deosebi nobilii de membrii obisnuiti ai Syndicate?",a="Nobilii se pot deghiza in agenti obisnuiti ai Syndicate, dar fiecare poate fi identificat dupa inelul cu sigiliu pe care il poarta.",al={"identificarea nobililor","cine lasa inele","cum recunosc nobilii"}},{q="Ce urmeaza inainte de aceasta parte a lantului?",a="Urmeaza dupa Foreboding Plans.",al={"misiune prealabila","misiunea anterioara","misiunea prealabila pentru noble deaths"}}},fp="12,277,31.472.0,12.129.1,28.100.0,39.108.0,66.94.0,36.28.0"}
P.entries["quest:513"] = {n="Elixir of Agony",s="Aceasta insarcinare duce Mudsnout Composite, proaspat zdrobita de Apothecary Lydon, din Tarren Mill direct in inima Royal Apothecary Society, in Undercity. Master Apothecary Faranell are nevoie de pasta vegetala pentru a o trata cu un coloid al descompunerii, contribuind astfel la dezvoltarea unei noi molime de catre Forsaken.",h="Aceasta insarcinare duce Mudsnout Composite, proaspat zdrobita de Apothecary Lydon, din Tarren Mill direct in...",kw={"Apothecarium","Apothecary Lydon","coloid al descompunerii","Elixir of Agony","Master Apothecary Faranell","amestec Mudsnout","ciuma noua","Undercity"},ang={["faction:Horde"]="Horde se bazeaza pe teritoriul Forsaken pentru a stapani nordul Lordaeronului, iar cercetarile Royal Apothecary Society sunt esentiale pentru apararea acestor granite vulnerabile.",["race:Undead"]="Fiecare transport de materie vegetala neprelucrata livrat lui Faranell contribuie la supravietuirea Forsaken si la apararea suveranitatii lor impotriva celor vii si a Scourge."},sec={{t="Un curier spre capitala",b="In cadrul eforturilor continue ale Royal Apothecary Society, cercetatorii regionali isi trimit adesea descoperirile brute inapoi la Undercity, pentru prelucrare specializata. Apothecary Lydon a zdrobit local Mudsnout Blossoms si a obtinut un amestec, dar pentru a-l transforma intr-un preparat letal sunt necesari reactivi avansati, pastrati numai in laboratorul capitalei."},{t="Urgenta maestrului",b="Master Apothecary Faranell lucreaza sub o presiune uriasa in Apothecarium. Prinsa intre umbra permanenta a Scourge din nord si populatiile umane agresive din sud, Lady Sylvanas Windrunner a cerut o noua plaga puternica pentru a-si apara poporul. Primirea amestecului lui Lydon ii ofera lui Faranell exact genul de descoperire toxica asteptata de Dark Lady."}},faq={{q="De ce trebuie sa duc Mudsnout Composite la Undercity?",a="Apothecary Lydon din Tarren Mill nu are reactivii necesari pentru a incheia aceasta etapa a experimentului sau. Master Apothecary Faranell are un coloid al descompunerii in Apothecarium, care trebuie aplicat asupra Mudsnout Composite inainte ca amestecul sa poata fi prelucrat mai departe.",al={"de ce sa mergi la Undercity","destinatia amestecului Mudsnout","de ce sa-l duci la Faranell"}},{q="Cine este Master Apothecary Faranell?",a="Master Apothecary Faranell conduce Royal Apothecary Society din laboratorul sau, aflat in adancurile Undercity. El supravegheaza toate cercetarile chimice si alchimice majore ale Forsaken si ii raporteaza direct Lady Sylvanas Windrunner.",al={"cine este Faranell","povestea lui Master Apothecary Faranell","conducatorul Apothecarium"}},{q="Care este noua plaga despre care tot vorbesc alchimistii?",a="Noua molima este un proiect Forsaken aflat in desfasurare, condus de Lady Sylvanas. A fost conceputa pentru a nimici atat viii, cat si mortii vii ai Scourge, oferindu-le celor din Forsaken o arma absoluta impotriva dusmanilor lor.",al={"ce este noua plaga","proiectul plaga Forsaken","de ce sa creeze o noua plaga"}},{q="Unde il pot gasi pe Master Apothecary Faranell?",a="Faranell isi are resedinta in Apothecarium, cartierul sud-vestic al Undercity, dedicat in intregime alchimiei, prepararii otravurilor si experimentelor chirurgicale.",al={"unde este faranell","locatia lui faranell","locatia Apothecarium"}},{q="Ce incearca Apothecary Lydon sa creeze?",a="Lydon prepara Elixir of Agony, o toxina extrem de virulenta, obtinuta din flora din Hillsbrad si agenti de putrezire, menita sa demonstreze eficienta noilor varietati in teren.",al={"ce prepara lydon","scopul Elixir of Agony","experimentul lui lydon"}},{q="De ce se grabeste atat de mult Royal Apothecary Society?",a="Forsaken percep amenintari din toate partile. Scourge din Northrend ameninta sa-i copleseasca, in timp ce ramasitele rezistentei umane exercita o presiune neincetata din sud, ceea ce face ca desavarsirea unei arme biologice decisive sa fie de o urgenta extrema.",al={"de ce sa te grabesti","Faranell e ocupat","amenintarea pentru Undercity"}}},fx={c9de6b5a={q="De ce te trimite Apothecary Lydon in loc sa mearga el insusi?",a="Apothecary Lydon este stationat in Hillsbrad Foothills, unde desfasoara cercetari esentiale pe teren pentru Royal Apothecary Society. Pregatirea compusilor toxici si monitorizarea evolutiilor locale ii cer atentia neintrerupta la Tarren Mill, asa ca niste curieri de incredere trebuie sa-i duca amestecurile brute la Undercity pentru prelucrare specializata.",al={"de ce sa ma trimita","de ce nu merge Lydon la Undercity","de ce nu poate Lydon sa-l livreze"}}},fp="15,304,24.340.0,20.392.0,62.260.0,34.225.0,56.214.0,44.160.0,42.179.0,46.242.0"}
P.entries["quest:514"] = {n="Letter to Stormpike",s="Loremaster Dibbs din Southshore are o scrisoare criptata cu iscusinta si stie de cineva din Ironforge care ar putea s-o descifreze. Te trimite cu scrisoarea la Prospector Stormpike, in Library din Hall of Explorers.",h="Loremaster Dibbs din Southshore are o scrisoare criptata cu iscusinta si stie de cineva din Ironforge care ar...",kw={"scrisoare criptata","hall of explorers","biblioteca din Ironforge","letter to stormpike","loremaster dibbs","prospector stormpike","southshore"},sec={{t="Un coleg in Ironforge",b="Prospector Stormpike se afla in Library, in Hall of Explorers din Ironforge. Dibbs vrea sa-i spui lui Stormpike ca te-a trimis el si sa-i arati scrisoarea. Dibbs socoteste ca, daca poate s-o citeasca cineva la nord de Blackrock Spire, acela este Stormpike."},{t="Bun venit din partea lui Stormpike",b="Stormpike intreaba ce mai face batranul carturar cand afla ca Dibbs te-a trimis. Apoi declara ca criptarea este specialitatea sa si incepe sa cerceteze scrisoarea."}},faq={{q="Cine te trimite la Ironforge cu scrisoarea?",a="Loremaster Dibbs din Southshore te trimite, in speranta ca un coleg din Ironforge poate descifra scrisoarea.",al={"cine mi-a dat aceasta misiune","cel care ofera misiunea","cine incepe Letter to Stormpike"}},{q="Unde se afla Prospector Stormpike?",a="Prospector Stormpike se afla in Library, in Hall of Explorers din Ironforge.",al={"stormpike location","unde este stormpike","biblioteca Prospector Stormpike"}},{q="De ce crede Dibbs ca Stormpike poate citi scrisoarea?",a="Dibbs spune ca, daca cineva aflat la nord de Blackrock Spire poate sa-l citeasca, acela este Stormpike.",al={"de ce stormpike","de ce sa trimiti la stormpike","criptarea stormpike"}}},fp="19,216,24.255.0,19.165.1,43.97.0,38.81.0,53.80.0"}
P.entries["quest:5147"] = {n="Wanted - Arnak Grimtotem"}
P.entries["quest:515"] = {n="Elixir of Agony",s="Aceasta misiune continua dezvoltarea noii molime a Royal Apothecary Society, trimitand un curier din Undercity inapoi la Tarren Mill. Master Apothecary Faranell imbogateste amestecul Mudsnout al lui Lydon cu propriile sale compusi in descompunere, cerand reactivi de coasta si potiuni alchimice pentru a declansa fermentarea fierturii letale.",h="Aceasta misiune continua dezvoltarea noii molime a Royal Apothecary Society, trimitand un curier din...",kw={"Daggerspine","Elixir of Agony","Faranell","Lydon","Mudsnout","Tarren Mill","Torn Fin","Umpi","Undercity"},ang={["faction:Horde"]="Tarren Mill se afla in pragul unor incaierari de granita necontenite cu Alliance din Southshore; experimentele toxice ale lui Lydon au menirea de a inclina balanta puterii in regiune.",["race:Undead"]="Fiecare reactiv rafinat din aceasta serie de misiuni aduce Royal Apothecary Society cu un pas mai aproape de indeplinirea dorintei lui Lady Sylvanas: obtinerea unei arme supreme impotriva celor vii."},sec={{t="Un coloid al descompunerii",b="Cand munca de teren a lui Apothecary Lydon a produs un compus puternic din Mudsnout Blossoms culese de la Nethander Stead, aflat sub controlul gnollilor, acesta l-a trimis direct la Apothecarium din Undercity. Master Apothecary Faranell, conducatorul Royal Apothecary Society, a recunoscut imediat potentialul sinistru al amestecului. Incantat de proprietatile sale toxice, Faranell si-a adaugat propriul coloid specializat al putrefactiei in amestec, apoi a schitat catalizatorii necesari pentru a-l transforma pe deplin intr-o arma."},{t="Catalizatori de pe coasta",b="Activarea agentilor contaminanti volatili necesita reactivi precisi, pe care Lydon trebuie sa-i pregateasca in Tarren Mill. Pe langa o potiune reparatorie din Strong Troll's Blood, necesara pentru a alimenta si stabiliza reactia chimica, Faranell are nevoie de componente organice recoltate de pe tarmul sudic din Hillsbrad: solzi smulsi de la naga serpentine Daggerspine si ochi scosi din murlocii Torn Fin de pe coasta."},{t="cruzime in Tarren Mill",b="In Tarren Mill, Lydon isi petrece orele de asteptare amuzandu-se macabru: isi otraveste, infecteaza si reanimeaza in mod regulat nefericitul sau subiect de testare, strigoiul Umpi. Livrarea amestecului imbogatit al lui Faranell si a catalizatorilor de coasta il apropie pe apotecar de scopul sau suprem: perfectionarea unei noi tulpini de molima chinuitoare, pe care sa o dezlantuie asupra asezarilor celor vii din Hillsbrad."}},faq={{q="De ce necesita molima un elixir cu sange de troll pentru vindecare?",a="Amestecurile alchimistilor folosesc adesea substante regenerative pentru a intretine, alimenta si transforma rapid agenti biologici agresivi. Proprietatile reparatorii ale Strong Troll's Blood mentin culturile toxice active suficient de mult pentru a reactiona cu celelalte tesuturi.",al={"de ce sange de troll","la ce foloseste sangele trollilor puternici","elixirul din sange de troll si molima"}},{q="Unde se gasesc solzii Daggerspine?",a="Solzii Daggerspine sunt recoltati de la naga ostili Daggerspine care populeaza plajele estice din Hillsbrad Foothills, de-a lungul tarmului, la est de orasul Southshore al Alliance.",al={"locatia solzilor Daggerspine","unde sunt solzii naga","de unde iau solzi"}},{q="De unde se obtin ochii Torn Fin?",a="Ochii Torn Fin se aduna de la murlocii Torn Fin, care traiesc in triburi de-a lungul coastei vestice din Hillsbrad Foothills, chiar la vest de Southshore.",al={"locatia ochiului torn fin","unde se gasesc murlocii torn fin","ochii murlocilor din hillsbrad"}},{q="Cine este Umpi?",a="Umpi este broasca pe care Apothecary Lydon o tine drept 'asistenta' in Tarren Mill. Lydon isi petrece timpul liber folosind-o ca pe un cobai de unica folosinta, administrandu-i in repetate randuri toxine si boli letale, doar pentru a o readuce la viata inca o data.",al={"cine este umpi","umpi din hillsbrad","umpi, asistentul lui lydon"}},{q="De ce este Master Apothecary Faranell implicat in acest proiect local?",a="In calitate de conducator al Royal Apothecary Society, Faranell supravegheaza toate cercetarile privind noii agenti biologici si molimele. Farmacistii de campanie precum Lydon ii trimit lui Faranell, in Undercity, descoperirile promitatoare din salbaticie, pentru a fi perfectionate si aprobate.",al={"de ce Faranell","rolul lui Master Apothecary Faranell","liderul Royal Apothecary Society"}},{q="Ce este Mudsnout Mixture?",a="Este un amestec toxic neprelucrat, preparat de Lydon din Mudsnout Blossoms si ciuperci scarboase culese de la Nethander Stead, infestata de gnolli, din Hillsbrad Foothills. Recunoscandu-i virulenta neobisnuita, Lydon l-a trimis la Undercity, unde Faranell l-a combinat cu coloizi descompusi pentru a crea o molima si mai letala.",al={"amestecul Mudsnout","otravirea gnoll-ilor","compozitul Mudsnout"}}},fx={["45c57bb0"]={q="La ce folosesc Daggerspine Scale-urile si Torn Fin Eye-urile?",a="Master Apothecary Faranell precizeaza ca sunt necesare atat solzii reptilieni ai naga Daggerspine, cat si ochii murlocilor Torn Fin, reactivi care activeaza agentii contaminanti latenti din Mudsnout Mixture. Combinata cu propriul sau coloid al descompunerii si sangele vindecator al trolilor, aceasta recolta de vietati acvatice de coasta furnizeaza catalizatorul reactiv de care Apothecary Lydon are nevoie pentru a-si pune compusul mortal in miscare.",al={"solzi Daggerspine","de ce e necesar ochiul Torn Fin","de ce solzii Daggerspine"}},ff4494e7={q="Cine sunt Daggerspine si Torn Fin de-a lungul coastei?",a="Tarmul sudic din Hillsbrad Foothills a fost napadit de triburi acvatice ostile, care ameninta Southshore din ambele flancuri. La est, naga Daggerspine au patruns pe plaje venind din Great Sea, revendicand teritoriu cu inversunare serpentina. La vest salasluiesc murlocii Torn Fin, necrofagi care se agata de apele putin adanci. Biologia lor ii face, fara voia lor, surse de reactivi pentru razboiul alchimic al celor Forsaken.",al={"naga si murloci din Hillsbrad","cine sunt Daggerspine","cine sunt Torn Fin"}}},fp="15,315,18.470.0,24.410.0,22.380.1,63.272.0,39.195.0,37.152.0,12.233.0,65.251.0,29.299.0"}
P.entries["quest:5151"] = {n="Hypercapacitor Gizmo",s="Dupa o ambuscada mortala a centaurilor asupra unei caravane de negustori din Thousand Needles, goblinul inventator Wizlo Bearingshiner a ramas singurul supravietuitor. Disperat sa-si recupereze inventia mult pretuita, el angajeaza aventurieri sa patrunda printre ruine, sa descuie o cusca de fier si sa smulga dispozitivul de la gatul unui pradator fioros, aflat in captivitate.",h="Dupa o ambuscada mortala a centaurilor asupra unei caravane de negustori din Thousand Needles, goblinul...",kw={"caravana centaurilor","pantera furioasa","inginerie goblin","dispozitiv hipercondensator","panther cage key","thousand needles","whitereach post","wizlo bearingshiner"},ang={["class:Hunter"]="Pantera furioasa tinuta in caravana distrusa este o fiara neobisnuit de puternica, destul de feroce incat sa ingrozeasca o intreaga ceata de razboinici centauri.",["faction:Horde"]="Actionand din Whitereach Post, cercetasii si calatorii Horde se lupta fara incetare cu clanurile centaurilor pradatoare care ameninta rutele de transport prin centrul Kalimdor.",["profession:Engineering"]="Urmarirea febrila de catre Wizlo a unei inventii al carei scop nu si-l aminteste prea bine este un exemplu al filozofiei haotice, bazate pe incercari si greseli, specifice ingineriei goblinilor."},sec={{t="Ambuscada in Needles",b="Caravanele care trec pe sub turlele uriase de gresie din Thousand Needles trebuie sa strabata o ruta primejdioasa. Centaurii ostili pandesc pe fundul canionului, aparandu-si cu indarjire teritoriul si atacand orice calator destul de indraznet ca sa treaca. Cand o asemenea caravana comerciala a fost nimicita chiar la nord de Whitereach Post, centaurii i-au masacrat pe calatori si au pradat carele, lasandu-l doar pe goblinul Wizlo Bearingshiner sa se tarasca inapoi in siguranta."},{t="Un gardian neasteptat",b="In haosul raidului, centaurii au pradat aproape orice lucru de pret, dar s-au tinut departe de o caruta distrusa. Legata intr-o cusca solida de transport se afla o pantera feroce si furioasa, cu dispozitivul hipercondensator mult ravnit de Wizlo prins chiar in jurul gatului. Descurajati de furia marainda a pradatorului, centaurii au abandonat cusca intacta, silindu-l pe Wizlo sa-i incredinteze cheia unor mercenari neinfricati, in stare sa ucida fiara si sa-i recupereze gadgetul."},{t="Ambitia unui mester",b="Fidela firii goblinilor, pasiunea lui Wizlo pentru minunatiile mecanice o ia adesea inaintea intelegerii practice. Desi lauda dispozitivul hipercondensator drept cea mai buna creatie a sa si isi risca viata pentru a-l recupera din ghearele unui pradator de varf, la intoarcerea lui recunoaste ca trebuie inca sa mesteresca la el ca sa-si dea seama ce face de fapt."}},faq={{q="Cine este Wizlo Bearingshiner?",a="Wizlo Bearingshiner este un mestesugar si negustor goblin care s-a refugiat la Whitereach Post dupa ce centaurii i-au atacat si distrus caravana pe fundul canionului din Thousand Needles.",al={"cine este Wizlo","povestea lui Wizlo Bearingshiner","Wizlo, cel care da misiunea"}},{q="De ce are pantera un mecanism in jurul gatului?",a="In timpul transportului sau al haosului provocat de ambuscada centaurilor, dispozitivul a ajuns prins in jurul gatului bestiei captive. Pantera era atat de inspaimantatoare, incat centaurii pradalnici au refuzat sa atinga cusca, transformand fara sa vrea pradatorul in paznicul dispozitivului.",al={"de ce are pantera gadgetul","colierul panterei","gadgetul de la zgarda"}},{q="Unde se afla caravana naufragiata?",a="Caravana distrusa se afla chiar la nord de Whitereach Post, in Thousand Needles, printre vagoane sfaramate si inconjurata de tabere de centauri ostili.",al={"locatia caravanei","unde sa gasesti cusca panterei","locatia custii"}},{q="De ce nu a jefuit centaurul cusca?",a="Potrivit lui Wizlo, pantera furioasa este atat de feroce, incat pana si nemilosii jefuitori centauri tremurau in prezenta ei si au ales sa lase bestia inchisa in cusca, in loc sa riste sa o deschida.",al={"de ce a parasit centaurul pantera","centaurul se teme de pantera","de ce este cusca neatinsa"}},{q="Ce face, de fapt, Hypercapacitor Gizmo?",a="Wizlo proclama ca este cea mai buna inventie a sa, dar, dupa ce i se returneaza, marturiseste ca mai trebuie sa petreaca timp studiind-o si mesterind la ea ca sa descopere ce functie indeplineste de fapt.",al={"ce face mecanismul","functia hipercondensatorului","ce este mecanismul"}},{q="Cine controleaza Whitereach Post?",a="Whitereach Post este o asezare tauren aliata cu Horde, asezata printre platourile canionului pentru a supraveghea activitatea centaurilor si a le oferi adapost calatorilor Horde.",al={"whitereach post factiune","whitereach este hoarda"}}},fx={["64badd6f"]={q="De ce vrea Wizlo Bearingshiner sa-si recupereze Hypercapacitor Gizmo?",a="Wizlo este singurul supravietuitor al unei caravane napadite de centauri in campiile canionului. El considera hipercondensatorul drept cea mai buna inventie a sa, desi recunoaste ca inca nu si-a dat seama deloc ce face. Disperat sa-si recupereze inventia pretioasa din ramasitele expeditiei, este gata sa rasplateasca pe oricine are curajul s-o ia inapoi.",al={"motivul lui Wizlo Bearingshiner","de ce sa recuperez Hypercapacitor","de ce vrea Wizlo gizmo-ul"}},["01614ead"]={q="Ce bestie pazeste Hypercapacitor Gizmo?",a="Dispozitivul atarna de gatul unei pantere neobisnuit de feroce, inchise in cusca si prinse in caruta ruinata. Bestia era atat de salbatica, incat centaurii jefuitori n-au indraznit sa-i atinga cusca de fier cand au pradat restul proviziilor, lasand pradatorul blocat printre daramaturi, chiar la nord de avanpost.",al={"cine pazeste mecanismul","tinta pantera","ce este pantera"}},["6ff4273d"]={q="De ce are Wizlo Bearingshiner nevoie de ajutorul tau?",a="Wizlo abia a scapat cu viata din masacrul centaurilor si este inginer, nu razboinic. Taurenii de la Whitereach Post isi fac singuri de straja impotriva triburilor ostile, asa ca nu au prea multa vointa sau oameni de trimis sa ajute un goblin excentric sa-si recupereze proiectele abandonate din ghearele unui monstru inchis in cusca si inconjurat de jefuitori.",al={"de ce are wizlo nevoie de mine","de ce sa ceara unui aventurier","de ce nu poate wizlo sa ia gizmo"}}},fp="20,320,21.433.0,20.454.0,19.336.1,27.185.0,43.260.0,37.143.0,37.198.0,47.187.1,29.165.0"}
P.entries["quest:516"] = {n="Beren's Peril",s="Beren's Peril este o misiune Horde coordonata de Shadow Priest Allister din Sepulcher. Agentii Forsaken au aflat de existenta unei adunari ascunse de Scourge, care se strange intr-o pestera izolata din dealurile sudice ale regiunii Silverpine, si urmaresc sa-i nimiceasca inainte de inceperea unei ofensive.",h="Beren's Peril este o misiune Horde coordonata de Shadow Priest Allister din Sepulcher.",kw={"ambermill","beren's peril","berens peril","ravenclaw drudger","ravenclaw guardian","scourge","shadow priest allister","silverpine forest","the sepulcher"},ang={["class:Priest"]="La ordinele lui Shadow Priest Allister, vrajitorii intunecati ajuta la consolidarea autoritatii din Sepulcher, nimicind grozaviile strigoi rivale.",["faction:Horde"]="Eliminarea cuiburilor ascunse ale Scourge de-a lungul granitelor Silverpine contribuie la stabilizarea nordului Lordaeron pentru intreaga Horde.",["race:Undead"]="Pentru Forsaken, starpirea ramasitelor Scourge, precum cele din Beren's Peril, este o chestiune de supravietuire pura, care le consolideaza suveranitatea in fata influentei persistente a Lich King."},sec={{t="O lovitura preventiva",b="Vestea a ajuns la Shadow Priest Allister, in Sepulcher: slujitorii lipsiti de minte ai Lich King-ului se adunau in adancurile partii sudice din Silverpine Forest. Lasate nesupravegheate, aceste forte Scourge reprezentau o amenintare imediata pentru operatiunile factiunii Forsaken din intreaga regiune. In loc sa astepte dezlantuirea atacului, Allister le cere cercetasilor sa preia initiativa si sa nimiceasca hoarda care se aduna in ascunzatoarea ei izolata, inainte ca aceasta sa se mobilizeze."},{t="Pestera ascunsa",b="Beren's Peril este o retea de pesteri putin cunoscuta, sapata in dealurile de la sud de asezarea Ambermill, aflata sub influenta Dalaranului. Terenul inselator face ca pesterile sa fie usor de trecut cu vederea; singura cale de a ajunge la ele este ocolind versantii sudici. In umbra lor locuiesc muncitorii si gardienii Ravenclaw, ramasite inradacinate ale ciumei, a caror nimicire contribuie la mentinerea controlului subred al Forsaken asupra padurii."}},faq={{q="Ce este Beren's Peril?",a="Beren's Peril este o pestera retrasa, aflata in dealurile muntoase din sudul regiunii Silverpine Forest, la sud de Ambermill. Este ascunzatoarea unor ramasite ale Scourge, cunoscute drept strigoii Ravenclaw.",al={"berens peril","unde este berens peril","ce este pestera aceasta"}},{q="Cine incredinteaza misiunea Beren's Peril?",a="Shadow Priest Allister, aflat la Sepulcher, in Silverpine Forest, le ofera misiunea aventurierilor din Horde dupa ce afla ca strigoi ostili pregatesc o ofensiva din pestera.",al={"cine ofera misiunea Beren's Peril","cel care ofera misiunea Beren's Peril","misiunea lui Shadow Priest Allister"}},{q="De ce ii ataca Forsaken pe undead de acolo?",a="Mortii-vii din Beren's Peril sunt loiali Lich King-ului si fac parte din Scourge. Forsaken s-au eliberat de sub controlul Lich King-ului si lupta activ pentru a-i curata de pe meleagurile lor pe acolitii care-i mai slujesc.",al={"de ce sa ucizi strigoi","de ce sa te lupti cu ravenclaw","nu sunt forsaken strigoi"}},{q="Cum gasesti intrarea in pestera?",a="Pestera se afla ascunsa in dealurile de la sud de Ambermill. Din cauza crestelor abrupte, intrarea trebuie abordata dinspre versantul sudic, nu direct din nord.",al={"cum ajung la Beren's Peril","locatia intrarii in pestera","unde este intrarea in pestera"}},{q="Ce dusmani salasluiesc in Beren's Peril?",a="Pestera este locuita de robi ai Scourge, mai exact de Ravenclaw Drudgers si Ravenclaw Guardians, care par sa se adune pentru a ataca asezarile din apropiere.",al={"creaturi in Beren's Peril","ce se afla in Beren's Peril"}},{q="Ce rol are Dalaran in aceasta misiune?",a="Dalaran nu are un rol direct in misiune, desi vrajitori umani din Dalaran locuiesc in apropiatul Ambermill. Allister le mentioneaza prezenta doar ca reper care sa-i ajute pe cercetasi sa gaseasca pestera ascunsa.",al={"legatura cu dalaran","legatura cu ambermill"}}},fp="13,289,19.433.0,15.428.0,22.200.0,41.184.0,48.209.0,41.183.0,35.168.0,44.196.0"}
P.entries["quest:517"] = {n="Elixir of Agony",s="Aceasta misiune este al patrulea capitol din eforturile neobosite ale Apothecary Lydon de a dezvolta o otrava devastatoare pentru Forsaken, in Tarren Mill. Dupa ce Elixir of Agony a fost in sfarsit preparat, Lydon trimite campionii Horde la Dun Garok sa fure un butoi de Shindigger Stout pentru a-l livra.",h="Aceasta misiune este al patrulea capitol din eforturile neobosite ale Apothecary Lydon de a dezvolta o otrava...",kw={"Apothecary Lydon","Dun Garok","Dwarves","Elixir of Agony","Hillsbrad","Shindigger Stout","Tarren Mill","Umpi"},ang={["class:Rogue"]="Sa te strecori nevazut prin salile de mese aglomerate din Dun Garok este o lectie desavarsita de hotie sub nasul alpinistilor.",["faction:Horde"]="Subminarea prezentei Alliance la Dun Garok o ajuta pe Tarren Mill sa-si mentina pozitia fragila in fata amenintarilor neincetate din sud.",["race:Dwarf"]="Profanarea berii traditionale a piticilor, transformata intr-un mijloc de ucidere chimica, reprezinta o insulta grava la adresa mestesugului din Ironforge.",["race:Undead"]="Fiecare serie perfectionata de Lydon ii apropie pe Forsaken de transformarea mortii intr-o arma impotriva dusmanilor vii care patrund in Lordaeron."},sec={{t="O bautura amara",b="In tinuturile umede din Tarren Mill, Apothecary Lydon lucreaza neobosit in slujba Royal Apothecary Society si a Lady Sylvanas. Dupa ce a adunat ingrediente letale din toate colturile Hillsbrad, si-a desavarsit noua potiune. Lydon nu are de gand sa iroseasca o tulpina atat de puternica pe creaturi neinsemnate precum broastele sau cainii vagabonzi; cauta un test real, concret, impotriva unor adversari in viata."},{t="Infiltrarea in Dun Garok",b="Pentru a-si pune experimentul in scena, Lydon are nevoie de un mijloc de transport discret. La sud de Hillsbrad, piticii din Ironforge au fortificat bastionul Dun Garok. Lydon le ordona agentilor Horde sa se infiltreze in cazarmele subterane si in salile de mese, sa se strecoare pe langa pustile si topoarele piticilor si sa fure un butoi pretios de Shindigger Stout."},{t="Reteta dezastrului",b="Lydon intentioneaza sa amestece toxina sa letala direct in bautura preferata a piticilor. Odata turnat in butoiul furat, elixirul poate fi administrat unei tinte nestiutoare sub pretextul unei bauturi festive, transformand berea neagra indragita de pitici intr-un instrument al unei agonii cumplite."}},faq={{q="Cine este Apothecary Lydon?",a="Apothecary Lydon este un alchimist Forsaken stationat in Tarren Mill. Reprezentand Royal Apothecary Society, face experimente pentru a crea plagi si elixiruri mortale pentru Banshee Queen, Lady Sylvanas.",al={"lydon","cine ofera aceasta misiune","povestea lui apothecary lydon"}},{q="De ce are nevoie Lydon de un butoi de Shindigger Stout?",a="Lydon vrea sa testeze Elixir of Agony finalizat pe tinte vii. Amestecand toxina intr-un butoi cu bere piticeasca populara, el creeaza o metoda discreta si puternica de a-si otravi victimele.",al={"de ce bere Dwarven","de ce Shindigger Stout","scopul butoiului"}},{q="Unde se afla Dun Garok?",a="Dun Garok este o reduta piticeasca puternic fortificata, situata in sud-estul regiunii Hillsbrad Foothills, pazita de alpinisti si tragatori cu pusca din Ironforge, care isi apara interesele nordice.",al={"unde este Dun Garok","locatia Dun Garok","unde gasesc butoiul"}},{q="Cine este Umpi?",a="Umpi este ajutorul lui Apothecary Lydon in Tarren Mill. Lydon remarca in gluma ca deschiderea borcanelor cu formaldehida prin laborator tinde sa-l faca pe Umpi vizibil de nervos.",al={"umpi","cine este umpi","asistentul lui Lydon"}},{q="Care este scopul final al Elixir of Agony?",a="Elixir of Agony este o otrava experimentala, creata de Royal Apothecary Society pentru a-i starpi pe cei vii, in slujba campaniei Forsaken de a securiza Lordaeron impotriva avanposturilor Human si dwarven.",al={"ce face Elixir of Agony","scopul ciumei","scopul otravii Forsaken"}},{q="Ce urmeaza dupa ce recuperezi butoiul?",a="Dupa ce primeste butoiul, Lydon amesteca elixirul toxic in Shindigger Stout si iti cere sa duci berea alterata unui subiect de testare care nu banuieste nimic.",al={"urmatoarea misiune","ce urmeaza dupa Dun Garok","elixirul, partea 5"}}},fx={["9a9bdb3b"]={q="Impotriva cui esti trimis la Dun Garok?",a="Misiunea ta este sa te infiltrezi in Dun Garok, un avanpost pitic puternic fortificat din sud-estul zonei Hillsbrad Foothills. Alpinistii si puscasii din Ironforge stationati acolo fac parte din Alliance, aparand interesele piticilor din regiune si reprezentand o amenintare constanta pentru prezenta Forsaken in Tarren Mill.",al={"piticii din Dun Garok","cine se afla la Dun Garok","cine pazeste berea tare"}}},fp="15,277,13.380.0,22.329.0,21.278.1,24.209.0,46.194.0,27.175.0,12.159.0,49.199.0,41.158.1"}
P.entries["quest:518"] = {n="The Crown of Will",s="In Tarren Mill, Melisara vrea sa reduca numarul ogriilor Crushridge inainte de a-l lovi cu adevarat pe Mug'Thol, ai carui ogri stapanesc acum Ruins of Alterac. Esti trimis sa dobori jefuitorii Crushridge.",h="In Tarren Mill, Melisara vrea sa reduca numarul ogriilor Crushridge inainte de a-l lovi cu adevarat pe...",kw={"crushridge maulers","melisara","mug'thol","ruins of alterac","sharlindra","tarren mill","the crown of will"},sec={{t="Imblanzirea celor din Crushridge",b="Mug'Thol si ogrele Crushridge au cucerit Ruins of Alterac. Melisara spune ca va fi greu sa-l pedepseasca pe Mug'Thol cat timp sunt atat de multe ogre in jur. Mai intai trebuie sa le reduca numarul si abia apoi va urma urmatoarea miscare. Tu trebuie sa vanezi zdrobitorii Crushridge."},{t="Inca nu e vreme de odihna",b="Dupa ce maulerii sunt morti, Melisara remarca faptul ca zapada se inroseste de sangele ogres si spune ca lupta nu se va opri pana cand Crushridge nu vor fi infranti atat in spirit, cat si ca numar."}},faq={{q="Cine ofera aceasta parte din The Crown of Will?",a="Melisara din Tarren Mill ti-o da si tot la ea trebuie sa te intorci.",al={"cine ofera Crown of Will","Melisara, cea care ofera misiunea","cine ofera misiunea Crown of Will 2"}},{q="Unde se afla ogrii Crushridge?",a="Ei detin Ruins of Alterac, pe care Mug'Thol si ogrii lui le-au cucerit.",al={"locatia lui Crushridge Maulers","unde sunt ogrii Crushridge","ogrii din ruinele Alterac"}},{q="De ce ii vizeaza Melisara mai intai pe maulers?",a="Melisara spune ca va fi greu sa-l pedepseasca pe Mug'Thol cat timp capcanii lui sunt atat de numerosi, asa ca trebuie sa le reduca numarul inainte ca planul sa avanseze.",al={"de ce sa ucizi Crushridge maulers","de ce sa rarefiezi ogrele"}}},fp="17,200,24.279.0,11.178.1,41.76.0,39.74.0,44.137.0"}
P.entries["quest:519"] = {n="The Crown of Will",s="Cu apararea ogre-lor slabita, Melisara din Tarren Mill vrea capetele celor trei locotenenti ai lui Mug'Thol, Targ, Muckrake si Glommus, inainte sa se ocupe de Mug'Thol insusi.",h="Cu apararea ogre-lor slabita, Melisara din Tarren Mill vrea capetele celor trei locotenenti ai lui Mug'Thol...",kw={"alterac","crown of will","glommus","hillsbrad","melisara","muckrake","mug'thol","targ","tarren mill"},sec={{t="Atacuri asupra conducerii",b="Locotenentii lui Mug'Thol sunt Targ, Muckrake si Glommus, toti loiali lui, desi Melisara se intreaba ce ar putea face un ogre sa fie loial. Trebuie sa-i ucizi pe toti trei si sa le duci capetele inapoi la Tarren Mill. Dupa aceea, nu va mai ramane decat capul lui Mug'Thol, cu tot cu coroana."},{t="Ce se intampla cu capetele",b="Melisara remarca duhoarea ogre-lor. Odata ce soseste si capul lui Mug'Thol, toate patru vor fi infipte in sulite deasupra Alterac, ca avertisment pentru oricine se pune cu Dark Lady."}},faq={{q="Cine ofera aceasta parte din The Crown of Will?",a="Melisara, din Tarren Mill, ti-l da si tot ea este cea careia ii duci capetele.",al={"cine incepe the crown of will","locatia lui melisara","unde predau the crown of will"}},{q="Cine sunt Targ, Muckrake si Glommus?",a="Sunt locotenentii lui Mug'Thol si ii sunt loiali. Melisara le vrea capetele.",al={"locotenentii lui mugthol","cine sunt locotenentii ogri","targ muckrake glommus"}},{q="Ce a precedat aceasta parte?",a="A doua parte din The Crown of Will, in care numarul ogres a fost redus.",al={"lantul crown of will","ce misiune vine inaintea acesteia","crown of will anterioara"}}},fp="17,174,25.269.0,25.174.1,41.85.0,36.74.0,27.79.0"}
P.entries["quest:52"] = {n="Protect the Frontier",s="Guard Thomas supravegheaza podul estic din Elwynn, in timp ce pradatorii ameninta tinutul de frontiera. Fortele din Stormwind sunt putine aici, iar lupii si ursii au devenit indrazneti in apropiere de Eastvale Logging Camp. El le cere aventurierilor capabili sa starpeasca fiarele care-i ameninta pe calatori si muncitori.",h="Guard Thomas supravegheaza podul estic din Elwynn, in timp ce pradatorii ameninta tinutul de frontiera.",kw={"Eastvale Logging Camp","Elwynn Forest","lup cenusiu de padure","Guard Thomas","Protect the Frontier","pantera","urs tanar de padure"},ang={["class:Hunter"]="Ca Hunter, iti poti pune la incercare priceperea de a urmari si de a trage la tinta impotriva lupilor si ursilor care pandesc prin estul Elwynn Forest.",["faction:Alliance"]="Asigurarea drumurilor estice ajuta cheresteaua din Eastvale sa ajunga pe teritoriile Alliance, unde sprijina reconstructia si apararea."},sec={{t="O aparare tot mai slaba",b="Guard Thomas supravegheaza podul peste rau, la marginea estica a Elwynn Forest. Goldshire si Northshire Valley au garnizoane Stormwind vizibile, dar aceasta zona de frontiera primeste mult mai putina protectie. Cu fortele Stormwind raspandite prin tot tinutul, Thomas este unul dintre putinii santinele dintre tinuturile locuite si salbaticie. Calatorii ajuta la mentinerea deschisa a drumurilor esentiale de aprovizionare."},{t="Amenintarea pradatoare",b="Eastvale Logging Camp furnizeaza lemn orasului Stormwind City, dar taietorii de lemne care doboara copaci la marginea padurii intalnesc vietuitoare periculoase. Pantere de prada, lupi cenusii de padure si ursi tineri de padure dau acum tarcoale pe langa drumuri si depozitele de cherestea. Rarirea lor reduce pentru o vreme pericolul pentru muncitorii locali. Thomas banuieste ca o tulburare din adancul padurii impinge fiarele spre asezari."}},faq={{q="Cine ofera misiunea Protect the Frontier?",a="Guard Thomas da ordinul. El supravegheaza podul estic de pe drumul principal din padurea Elwynn Forest, intre interiorul padurii si regiunea Eastvale.",al={"cine da misiunea Protect the Frontier","cine incepe Protect the Frontier","misiunea lui Guard Thomas"}},{q="De ce ataca lupii si ursii frontiera?",a="Lupii si ursii se apropie de drumurile si locurile de munca din jurul Eastvale Logging Camp. Thomas banuieste ca ceva mai adanc in salbaticie ii agita si ii impinge spre zonele locuite.",al={"de ce sunt agresivi ursii","de ce ataca lupii Eastvale","atacurile animalelor din Elwynn"}},{q="Unde se afla Eastvale Logging Camp?",a="Eastvale Logging Camp se afla in estul Elwynn Forest, chiar la est de podul lui Guard Thomas. Furnizeaza lemn esential pentru Stormwind si asezarile de la granita.",al={"locatia Eastvale","unde este tabara de taietori de lemne din Elwynn","tabara Eastvale"}},{q="De ce pazeste Guard Thomas singur podul?",a="Armata si garda orasului Stormwind sunt suprasolicitate in tot regatul. Avanposturile de pe rauri si de la intersectii au adesea doar una sau doua garzi care supravegheaza drumurile principale, asa ca se bazeaza pe calatori pentru a face fata amenintarilor venite din partea vietatilor mari.",al={"de ce este Guard Thomas singur","postul lui Guard Thomas","garzile din Stormwind la Eastvale"}},{q="Ce animale trebuie rarite pentru aceasta sarcina?",a="Trebuie sa ucizi opt lupi, fie panditori, fie lupi cenusii de padure, si cinci ursi tineri de padure care cutreiera estul Elwynn Forest.",al={"tinte pentru protect the frontier","lupi si ursi de ucis","ce inamici pentru protect the frontier"}},{q="Ce se intampla dupa ce fauna salbatica este redusa?",a="Cand te intorci sa-i raportezi, Guard Thomas iti multumeste, iar caravanele de busteni pot calatori mai in siguranta. El ramane insa precaut, de teama ca influenta intunecata care a agitat fiarele ar putea aduce si alte necazuri in padure.",al={"continuarea misiunii Protect the Frontier","preda misiunea Protect the Frontier"}}},fx={ad29ae35={q="De ce vrea Guard Thomas sa fie starpite fiarele salbatice?",a="Eastvale Logging Camp este atacata fara incetare de lupi si ursi tot mai agresivi, care dau tarcoale partii de est din Elwynn Forest. Guard Thomas este postat la podul estic pentru a-i proteja pe muncitori si calatori de-a lungul drumului, dar pradatorii sunt destul de indrazneti incat sa perturbe operatiunile esentiale de taiere a lemnului si sa ameninte pe oricine trece dincolo de perimetrul taberei.",al={"de ce sa rarefiezi lupii pentru guard thomas","de ce Protect the Frontier","de ce sa aperi eastvale"}},ce43057a={q="Impotriva caror animale esti trimis in Protect the Frontier?",a="Ti se cere sa starpesti pradatorii, lupii cenusii de padure si ursii tineri de padure care cutreiera codrii din jurul Eastvale Logging Camp. Animalele salbatice, de obicei timide, din vestul Elwynn au devenit neobisnuit de feroce si indraznete aici, la granita, punand in pericol calatoriile de zi cu zi si munca la taiatul lemnelor.",al={"ce lupi si ursi pentru protect the frontier","protect the frontier fiare","ce animale cere guard thomas"}}},fp="20,265,18.376.0,20.371.0,41.142.0,48.194.0,35.150.0,46.217.0,45.128.0,41.196.0"}
P.entries["quest:520"] = {n="The Crown of Will",s="Dupa moartea locotenentilor lui Mug'Thol, Melisara din Tarren Mill te trimite dupa Mug'Thol insusi. Trebuie sa-i aduci capul si Crown of Will, iar rezistenta Crushridge va lua sfarsit.",h="Dupa moartea locotenentilor lui Mug'Thol, Melisara din Tarren Mill te trimite dupa Mug'Thol insusi.",kw={"alterac","crown of will","crushridge","poalele Hillsbrad","melisara","mug'thol","tarren mill"},sec={{t="Ultimul cap",b="Acum a mai ramas doar Mug'Thol. Melisara se asteapta sa refuze sa renunte la Crown of Will si crede ca probabil te asteapta, avand in vedere ce li s-a intamplat locotenentilor sai. Gaseste-l, ucide-l si du-i capul si Crown inapoi la Tarren Mill."},{t="Raspunsul Melisarei",b="Melisara este multumita de treaba. Capul lui Mug'Thol va impodobi cel mai inalt varf al Ruins of Alterac, in timp ce Deathguard se va ocupa de ce a mai ramas din Crushridge."}},faq={{q="Cine te trimite sa-l ucizi pe Mug'Thol?",a="Melisara, in Tarren Mill, careia trebuie sa-i aduci capul.",al={"cine da misiunea crown of will","cine ofera crown of will","misiunea lui melisara"}},{q="Ce ii cere Melisara lui Mug'Thol?",a="Capul lui si Crown of Will.",al={"obiectivele lui mugthol","ce primesc de la mugthol","obiectele lui mug'thol"}},{q="De ce crede Melisara ca Mug'Thol se asteapta la probleme?",a="Locotenentii lui au fost ucisi, asa ca Melisara banuieste ca te asteapta si ca nu va renunta usor la Crown.",al={"de ce e Mugthol pregatit","Mugthol se asteapta la o lupta","Mug'thol a fost alertat"}},{q="Unde se incadreaza aceasta in Crown of Will?",a="Urmeaza dupa a treia parte, in care au fost vanati locotenentii lui Mug'Thol, si este urmata de o a cincea parte.",al={"crown of will chain","ce misiune preceda crown of will 4","progresul crown of will"}}},fp="17,189,13.243.0,16.173.1,31.68.0,41.32.0,49.129.0,42.108.0"}
P.entries["quest:521"] = {n="The Crown of Will",s="A mai ramas un singur lucru. Coroana trebuie dusa la Sharlindra, in Undercity, care se va asigura ca ajunge la Lady Sylvanas.",h="A mai ramas un singur lucru.",kw={"crown of will","hillsbrad","melisara","mugthol","sharlindra","sylvanas","undercity"},sec={{t="Spre Undercity",b="Melisara spune ca nu mai ramane decat sa duci Coroana la Sharlindra, in Undercity, iar ea i-o va inmana lui Lady Sylvanas. Melisara te avertizeaza si sa nu te gandesti sa o folosesti in scopuri proprii. Soarta lui Mug'Thol, spune Melisara, este o dovada mai mult decat graitoare."},{t="Reactia lui Sharlindra",b="Sharlindra recunoaste obiectul drept relicva folosita de ogre pentru a scapa de vointa Dark Lady. I se pare ciudat ca un lucru atat de banal avea o asemenea putere si ca a ajuns in maini atat de neindemanatice. Sharlindra il va duce la Lady Sylvanas si ii va povesti ce ai facut."}},faq={{q="Cine primeste Crown of Will in Undercity?",a="Sharlindra, in Undercity. Melisara spune ca se va asigura ca Lady Sylvanas il primeste.",al={"cine primeste Crown of Will","unde duc coroana","predare catre Sharlindra"}},{q="De ce avertizeaza Melisara sa nu foloseasca coroana?",a="Melisara va spune sa nu-l folositi in interes propriu si arata spre ce i s-a intamplat lui Mug'Thol, ca avertisment suficient.",al={"pot echipa coroana","de ce sa nu folosesc crown of will","avertisment despre soarta lui mugthol"}},{q="Cine te trimite cu coroana?",a="Melisara, ca a cincea si ultima parte din The Crown of Will, dupa a patra.",al={"ultima parte din Crown of Will","cine da Crown of Will 5"}}},fp="17,119,16.257.0,21.278.1,48.84.0,47.110.0,29.76.0"}
P.entries["quest:522"] = {n="Assassin's Contract",s="Un Shadowy Assassin din Hillsbrad Foothills poarta un contract care ordona uciderea lui Magistrate Henry Maleb. Este pecetluit cu ceara rosie, imprimata cu un sigiliu distinctiv, si trebuie sa i-l duci lui Maleb in Southshore.",h="Un Shadowy Assassin din Hillsbrad Foothills poarta un contract care ordona uciderea lui Magistrate Henry...",kw={"assassin's contract","dealurile Hillsbrad","magistrate henry maleb","asasin misterios","inel cu sigiliu","southshore","sindicat"},sec={{t="Un magistrat insemnat",b="Documentul cere uciderea lui Magistrate Henry Maleb. E inchis cu sigiliu de ceara rosie, imprimat cu o pecete distinctiva. Un Shadowy Assassin din Hillsbrad Foothills il poarta, iar Maleb din Southshore e persoana careia trebuie sa i-l arati."},{t="Verdictul lui Maleb",b="Maleb se uita peste contract si spune ca acesta explica atacul recent asupra Southshore. Maleb este sigur ca Syndicate vrea sa-l ucida pe magistrat, asa cum a vrut si sa-l ucida pe magistratul dinaintea lui."}},faq={{q="Ce scrie in contract?",a="Ordona uciderea lui Magistrate Henry Maleb, iar sigiliul de ceara rosie este imprimat cu un inel-sigiliu distinctiv.",al={"ce spune contractul","detalii despre contractul asasinilor","cine este tinta"}},{q="De unde provine acest contract?",a="Este purtat de un Shadowy Assassin in Hillsbrad Foothills.",al={"cine a scapat contractul","unde gasesc contractul","prada de la asasinul misterios"}},{q="Cui trebuie sa-i fie livrat contractul?",a="Lui Magistrate Henry Maleb din Southshore, magistratul pe care contractul il condamna la moarte.",al={"cui ii dau contractul","unde predau contractul asasinilor","locatia lui maleb"}}},fp="19,217,19.228.0,15.193.1,32.110.0,35.59.0,41.85.0"}
P.entries["quest:523"] = {n="Baron's Demise",s="Contractul pe care l-ai recuperat poarta numele lui Baron Vardus, un nobil din vechiul regat Alterac. Magistrate Henry Maleb din Southshore vrea sa fie gasit si adus in fata justitiei si iti cere capul baronului.",h="Contractul pe care l-ai recuperat poarta numele lui Baron Vardus, un nobil din vechiul regat Alterac.",kw={"muntii alterac","baron vardus","baron's demise","magistrate henry maleb","southshore","strahnbrad","syndicate"},sec={{t="Dreptate pentru un contract",b="Dupa Assassin's Contract, Magistrate Henry Maleb iti spune ca Baron Vardus si-a pus numele pe contract. Vardus este un nobil din vechiul regat Alterac, un om cu inima rece si metode brutale, asa ca Maleb nu este surprins sa afle ca se afla in spatele acestuia. Southshore nu va ingadui baronului sa-si trimita batausii impotriva orasului fara sa raspunda pentru fapta. Maleb vrea sa-l gasesti printre ascunzatorile Syndicate, poate in ruinele din Strahnbrad sau in valea de la nord de ele, si iti cere capul baronului."},{t="Usurarea lui Maleb",b="Cand aduci capul baronului, Maleb iti multumeste si spune ca, stiind ca raufacatorul si-a pierdut propriul cap, magistratul se poate odihni ceva mai linistit."}},faq={{q="Cine este Baron Vardus?",a="Un nobil din vechiul regat Alterac, cu inima rece si metode brutale. Numele lui apare pe contractul care l-a condamnat pe Maleb la moarte.",al={"povestea baronului vardus","cine este vardus","vardus alterac"}},{q="De ce il vrea Magistrate Maleb mort pe Baron Vardus?",a="Vardus si-a pus numele pe contractul pe care l-ai recuperat, iar Maleb nu-l va lasa sa trimita golani impotriva Southshore fara sa raspunda pentru asta.",al={"de ce sa-l omori pe baron vardus","maleb vardus","motivul pentru baron's demise"}},{q="Unde poate fi gasit Baron Vardus?",a="Maleb crede ca Vardus se afla undeva in ascunzatorile Syndicate, poate printre ruinele Strahnbrad sau in valea de la nord de ele.",al={"locatia baronului vardus","unde este vardus","vardus in strahnbrad"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa Assassin's Contract, contractul recuperat de tine, care poarta semnatura baronului.",al={"misiune premergatoare pentru Baron's Demise","lantul dinainte de Baron's Demise","cerinta pentru Assassin's Contract"}}},fp="14,210,22.484.0,14.142.1,20.135.0,49.133.0,32.121.0,23.92.0"}
P.entries["quest:524"] = {n="Elixir of Agony"}
P.entries["quest:525"] = {n="Further Mysteries",s="Prospector Stormpike a descifrat scrisoarea pe care ai gasit-o la hotii din zona de la poalele Alterac, dar nu-i poate intelege sensul. Iti spune s-o duci magistratului din Southshore.",h="Prospector Stormpike a descifrat scrisoarea pe care ai gasit-o la hotii din zona de la poalele Alterac, dar...",kw={"alterac","scrisoare descifrata","further mysteries","magistrate henry maleb","prospector stormpike","southshore","syndicate"},sec={{t="O scrisoare fara inteles",b="Dupa Letter to Stormpike, prospectorul spune ca a descifrat scrisoarea, dar nu-si poate da seama ce inseamna. I se pare foarte ciudat ca ai gasit-o printre hoti, in zona de la poalele muntilor Alterac. Scrisoarea e criptica, dar Southshore e cel mai aproape de Alterac, asa ca, daca se pregateste o amenintare, magistratul de acolo trebuie sa afle. Trebuie sa duci scrisoarea descifrata la Magistrate Henry Maleb."},{t="Ce citeste Maleb",b="Maleb studiaza scrisoarea si hotaraste ca n-ar fi putut fi scrisa de niciun hot si de niciun nobil din Alterac. Lui Maleb i se pare ca indica o putere mai intunecata aflata in spatele Syndicate, iar gandul la ceea ce ar putea fi acea putere il face sa se cutremure."}},faq={{q="Cine te trimite cu scrisoarea descifrata?",a="Prospector Stormpike, care a descifrat-o, dar nu-i poate intelege continutul, iti spune sa o duci la magistratul din Southshore.",al={"cine da further mysteries","cel care ofera misiunea further mysteries","unde incepe further mysteries"}},{q="Cine trebuie sa vada scrisoarea descifrata?",a="Magistrate Henry Maleb din Southshore. Stormpike subliniaza ca Southshore se afla cel mai aproape de Alterac, asa ca, daca se pregateste o amenintare, magistratul ar trebui sa stie.",al={"cine primeste scrisoarea descifrata","unde predau Further Mysteries","unde duc scrisoarea"}},{q="De unde provine scrisoarea criptata originala?",a="Ai gasit-o printre hotii de pe colinele Alterac inainte sa ajunga la Prospector Stormpike.",al={"originea scrisorii descifrate","unde a fost gasita scrisoarea","cine avea scrisoarea"}}},fp="17,181,24.385.0,16.206.1,40.121.0,38.154.0,50.91.0"}
P.entries["quest:5261"] = {n="Eagan Peltskinner",s="In afara Northshire Abbey, Eagan Peltskinner le da de lucru recrutilor, deoarece lupii de padure ameninta valea. Blanarul local are nevoie de vanatori care sa rareasca haitele si sa aduca inapoi blanuri.",h="In afara Northshire Abbey, Eagan Peltskinner le da de lucru recrutilor, deoarece lupii de padure ameninta...",kw={"adjunctul Willem","Eagan Peltskinner","Northshire Abbey","Northshire Valley","lupi de padure","lupi de peste granita"},ang={["faction:Alliance"]="Fiecare mica sarcina din Northshire contribuie la securizarea teritoriului natal al Stormwind, in timp ce armata de baza a regatului ramane suprasolicitata in alte locuri.",["race:Human"]="Ca tanar Human care pleaca din Northshire Abbey, ajutorul dat mestesugarilor locali precum Eagan este prima ta lectie despre apararea patriei."},sec={{t="O vorba cu blanarul",b="Deputy Willem le trimite adesea pe recruti de la manastire sa-l gaseasca pe Eagan Peltskinner, care lucreaza in apropiere, pe terenul acesteia. Livezile si campurile din Northshire Valley se invecineaza cu paduri salbatice, unde pandesc lupii de padure. Eagan vrea ca nou-venitii sa vaneze haitele agresive si sa adune blanuri pentru meseria lui."},{t="Necazuri la periferie",b="Lupii de padure ameninta muncitorii, acolitii si proviziile care circula spre si dinspre Northshire. Trimiterea tinerilor campioni la Eagan ajuta la mentinerea in siguranta a drumurilor din apropiere si ii scuteste pe putinii gardieni ramasi in Stormwind. Acestia sunt deja ocupati de tensiunile tot mai mari din Elwynn Forest."}},faq={{q="Cine te trimite sa vorbesti cu Eagan Peltskinner?",a="Deputy Willem, aflat in fata intrarii in Northshire Abbey, ii trimite pe recruti promitatori la Eagan dupa ce le prezinta problemele de securitate din vale.",al={"cine ofera aceasta misiune","cine incepe misiunea lui Eagan Peltskinner"}},{q="Unde se afla Eagan Peltskinner?",a="Eagan Peltskinner lucreaza langa zidurile exterioare ale Northshire Abbey, in jurul laturii stangi a cladirii principale, printre rastelele sale de uscare si echipamente.",al={"unde este eagan","locatia lui eagan peltskinner","gaseste-l pe eagan"}},{q="Cu ce are nevoie de ajutor Eagan Peltskinner?",a="Eagan are nevoie de un Hunter care sa ucida lupii timber agresivi din padurile din jur si sa le aduca blanurile, curatand perimetrul din Northshire.",al={"ce vrea Eagan","de ce sa vanezi lupi","scopul lui Eagan"}},{q="Poti sari peste aceasta misiune si sa vorbesti direct cu Eagan?",a="Da. Eagan isi ofera direct munca de vanator oricui se apropie de el. Daca vorbesti mai intai cu el, pur si simplu ratezi prezentarea facuta de Deputy Willem.",al={"pot sari peste misiunea lui Eagan","direct la Wolves Across the Border"}},{q="De ce sunt atat de multi lupi in Northshire Valley?",a="Northshire Valley se invecineaza cu paduri dese si salbatice, prin care umbla in voie lupi de padure. Garzile locale sunt raspandite in prea multe locuri din cauza altor amenintari din regat, lasand pradatorii nestingheriti.",al={"de ce sunt lupi in Northshire","problema lupilor in Elwynn"}},{q="Ce sarcina urmeaza dupa ce vorbesti cu Eagan Peltskinner?",a="Dupa ce vorbesti cu Eagan, acesta iti cere sa vanezi lupi de padure dincolo de tinuturile abatiei si sa le aduni blanurile rezistente.",al={"urmatoarea misiune","ce misiune ofera Eagan in continuare"}}},fx={b90d340a={q="De ce te trimite Deputy Willem la Eagan Peltskinner?",a="Adjunctul Willem are sarcina de a mentine siguranta in jurul Northshire Abbey. Inmultirea aparitiilor lupilor prin vale face ca o cerere de ajutor pentru rarirea haitei sa fie binevenita. Willem ii trimite pe recruti voluntari la Eagan, astfel incat putinii paznici ai manastirii sa se poata ocupa de probleme mai importante, tinand totodata la distanta pradatorii care se apropie de asezare.",al={"de ce te trimite willem la eagan","motivul lui willem si eagan peltskinner","de ce sa-l vizitezi pe eagan"}}},fp="17,175,23.281.0,24.264.0,46.137.0,35.136.0,43.143.0,51.149.0,50.185.0,50.117.0"}
P.entries["quest:527"] = {n="Battle of Hillsbrad",s="Battle of Hillsbrad este prima lovitura din campania Forsaken de nimicire a asezarii umane Hillsbrad. Incredintata de High Executor Darthalia la ordinul lui Varimathras, aceasta misiune vizeaza fermierii si infrastructura din nordul Hillsbrad Fields, pentru a taia aprovizionarea cu hrana a orasului.",h="Battle of Hillsbrad este prima lovitura din campania Forsaken de nimicire a asezarii umane Hillsbrad.",kw={"battle of hillsbrad","darthalia","farmer getz","farmer ray","hillsbrad fields","ciuma noua","tarren mill","varimathras"},ang={["faction:Alliance"]="Masacrarea colonistilor din nord arata realitatea inspaimantatoare cu care se confrunta ultimele enclave Human din Lordaeron.",["faction:Horde"]="In timp ce Thrall propovaduieste onoarea, campania din nord pornita din Tarren Mill dezvaluie brutalitatea nemiloasa a razboiului lui Sylvanas impotriva Alliance.",["race:Undead"]="Pentru Forsaken, recucerirea Lordaeronului inseamna stergerea fiecarui grup de supravietuitori vii care isi trateaza patria drept pamant furat."},sec={{t="Infometarea rezistentei",b="Tarren Mill se inalta ca varf de lance sudic al imperiului Forsaken, infruntand o populatie umana inradacinata, care se agata de Hillsbrad Foothills. High Executor Darthalia actioneaza conform unor directive stricte, primite direct de la Varimathras din Undercity. Strategia ei este cea a uzurii totale: inainte de a porni direct asupra orasului Hillsbrad, bine aparat, ordona distrugerea sistematica a agriculturii acestuia. Atacarea campurilor din nord priveaza militia umana de provizii esentiale, raspandind totodata haos in gospodariile localnicilor."},{t="O actiune de tergiversare",b="Campania mai ampla impotriva prezentei oamenilor in Hillsbrad are un scop tactic sumbru. In timp ce armatele Forsaken ii tin pe loc pe aparatorii locali si le macina fortele, Royal Apothecary Society lucreaza neincetat la crearea unei noi plagi, capabile sa-i extermine deopotriva pe cei vii si pe Scourge. High Executor Darthalia considera aceste prime ciocniri - si moartea proprietarilor de pamant locali precum Farmer Ray si Farmer Getz - pasi necesari pentru a suprima infestarea umana pana cand arma suprema va fi gata de folosire."}},faq={{q="De ce ii ataca Forsaken pe simpli fermieri?",a="Fermierii si lucratorii agricoli umani din Hillsbrad Fields formeaza baza logistica a orasului Hillsbrad. Epuizandu-le forta de munca si ucigandu-i pe marii proprietari de pamant, precum Farmer Ray si Farmer Getz, Forsaken taie aprovizionarea cu hrana a garnizoanei umane si ii slabesc apararea inaintea unui atac direct.",al={"de ce sa omoram fermieri","tinte la fermele din Hillsbrad","de ce sa ataci fermele"}},{q="Cine ordona acest atac?",a="High Executor Darthalia, comandanta militara Forsaken stationata la Tarren Mill, da misiunea. Ea se afla sub comanda directa a dreadlordului Varimathras si a Lady Sylvanas Windrunner.",al={"cine da misiunea","ordinele Darthaliei","cine este Darthalia"}},{q="Care este rolul Royal Apothecary Society in aceasta campanie?",a="Darthalia observa ca razboiul conventional impotriva oamenilor are menirea de a inabusi populatia vie si de a castiga timp, in vreme ce apotecarii Forsaken dezvolta o noua ciuma, menita sa-si nimiceasca dusmanii cu totul.",al={"de ce noua ciuma","alchimistii din Hillsbrad","planul ciumei Forsaken"}},{q="Unde se afla Farmer Ray si Farmer Getz?",a="Ambii proprietari de pamant supravegheaza partea de nord a Hillsbrad Fields. Farmer Ray se gaseste de obicei langa casa mare de la ferma sau lucreaza in gradina, chiar la est de aceasta, in timp ce Farmer Getz merge des la hambar, la casa mai mica sau pe ogoarele din jur.",al={"gaseste-l pe Farmer Ray","gaseste-l pe farmer getz","locatia lui ray si getz"}},{q="Ce se intampla dupa incheierea acestui raid?",a="Intoarcerea victorioasa la Darthalia duce atacul mai departe, spre campurile sudice si orasul Hillsbrad, deschizand totodata operatiuni secundare, precum strangerea trofeelor sinistre din Souvenirs of Death.",al={"continuarea Battle of Hillsbrad","ce urmeaza","evolutia lantului de misiuni"}},{q="De ce isi ameninta Darthalia soldatii?",a="High Executor Darthalia cere disciplina absoluta si cruzime. Ea considera orice ezitare sau gluma despre razboiul cu Alliance drept tradare, pedepsita cu executia pe loc.",al={"dialogul lui Darthalia","amenintarea lui Darthalia cu decapitarea"}}},fx={a66392fb={q="Impotriva cui esti trimis in Hillsbrad Fields?",a="Esti trimis impotriva fermierilor si a lucratorilor agricoli oameni care muncesc loturile din nordul regiunii Hillsbrad Fields, vizandu-i in special pe proprietarii Farmer Ray si Farmer Getz. Acesti locuitori formeaza coloana vertebrala a agriculturii din regiune, cultivand recolte si crescand animale care sustin asezarea oamenilor din apropiere, Hillsbrad, si fortele Alliance care tin zona.",al={"tinte din battle of hillsbrad","pe cine atacam in hillsbrad","cine sunt farmer ray si getz"}}},fp="19,302,23.523.0,17.505.0,46.318.0,23.197.0,61.208.0,45.258.0,40.201.0,41.198.0"}
P.entries["quest:528"] = {n="Battle of Hillsbrad",s="Battle of Hillsbrad este o misiune militara Forsaken, condusa de High Executor Darthalia din Tarren Mill. Dupa primele lovituri asupra fermelor umane din nord, agentii Horde sunt trimisi spre sud sa-i masacreze pe taranii Hillsbrad care fug sa se adaposteasca in livezi.",h="Battle of Hillsbrad este o misiune militara Forsaken, condusa de High Executor Darthalia din Tarren Mill.",kw={"Battle of Hillsbrad","Doamna Intunecata","Darthalia","Deathstalkers","Forsaken","Hillsbrad Fields","tarani din Hillsbrad","Tarren Mill"},ang={["faction:Alliance"]="Masacrarea refugiatilor neinarmati in livezile din sud subliniaza razboiul total si nemilos purtat de Forsaken impotriva supusilor in viata ramasi in Lordaeron.",["faction:Horde"]="Tarren Mill serveste drept bastion vital al Horde in tinuturile de la poalele muntilor. Infrangerea rezistentei din Hillsbrad asigura securitatea liniilor de comunicatii si aprovizionare ale Horde impotriva incursiunilor Alliance.",["race:Undead"]="Pentru Forsaken, aceasta epurare este pragmatica si fara compromisuri: eliminarea muncitorilor in viata lipseste Alliance de provizii si intareste stapanirea Dark Lady asupra sudului Lordaeron."},sec={{t="Semantand teroare pe campuri",b="Campania impotriva oamenilor din Hillsbrad Foothills inainteaza cu o raceala calculata. Dupa ce fortele Horde lovesc fermele din nord, asezarea este cuprinsa de panica. In loc sa puna mana pe arme, multi muncitori fug spre sud, in livezile si pasunile din Hillsbrad Fields, sperand sa se ascunda de strigoii care inainteaza. High Executor Darthalia nu vede in spaima lor un motiv de mila, ci un prilej strategic de a zdrobi cu totul forta de munca si moralul ramas in Hillsbrad."},{t="Avansarea lui Dark Lady",b="La ordinul direct al celor din Tarren Mill, campionii Horde ii vaneaza pe acesti muncitori stramutati de pe campuri. Lipsiti de aparare, taranii sunt eliminati sistematic pentru a opri aprovizionarea cu hrana a tinutului Hillsbrad si a zdrobi moralul civililor. Pentru Darthalia si Forsaken, fiecare om ucis strange tot mai mult cercul mortii in jurul orasului supravietuitor, asigurandu-se ca Lordaeron ramane ferm in mainile Forsaken."}},faq={{q="De ce ii vizeaza Forsaken pe taranii simpli?",a="Atacarea taranilor distruge temelia agricola care asigura hrana asezarii din Hillsbrad. Ucidandu-i pe muncitorii ascunsi in livezile sudice, High Executor Darthalia se asigura ca orasul se afunda tot mai mult in panica si foamete, ceea ce face cucerirea sa mult mai usoara.",al={"de ce sa omori taranii","de ce sa ataci fermierii","planul lui Darthalia pentru tarani"}},{q="Cine ordona acest atac?",a="High Executor Darthalia, comandantul Forsaken stationat la Tarren Mill, conduce intreaga campanie militara impotriva asezarilor omenesti locale, in numele lui Lady Sylvanas Windrunner.",al={"cine ofera Battle of Hillsbrad 2","cel care ofera misiunea Battle of Hillsbrad","ordinele lui Darthalia"}},{q="De unde au fugit acesti tarani?",a="Au fugit de la fermele din nordul Hillsbrad dupa atacurile anterioare ale Horde. Cuprinsi de panica si lipsiti de aparare, si-au gasit refugiul printre copacii si pasunile din sudul Hillsbrad Fields.",al={"de unde vin taranii","fermele din nordul Hillsbrad"}},{q="Unde pot fi gasiti taranii care fug?",a="Taranii sunt raspanditi prin livezile si pasunile din sudul Hillsbrad Fields, chiar la sud de drumul principal care strabate dealurile.",al={"locatia taranilor din Hillsbrad","unde sunt taranii din Hillsbrad"}},{q="Ce urmeaza dupa ce ucizi taranii?",a="Dupa ce ogoarele sudice au fost eliberate de muncitori, High Executor Darthalia intensifica campania si isi indreapta atentia asupra fierarului Verringtan si a fierariei care inarmeaza aparatorii din Hillsbrad, apropiind luptele tot mai mult de centrul orasului.",al={"ce urmeaza dupa tarani","urmatorul pas in Battle of Hillsbrad"}},{q="De ce lupta Horde atat de necrutator aici?",a="Orasul oamenilor Hillsbrad este una dintre ultimele cetati Alliance ramase in Lordaeron. Forsaken considera regiunea drept teritoriul lor suveran de drept si urmaresc sa alunge sau sa elimine orice enclave Alliance care le ameninta granita sudica.",al={"de ce ataca Hoarda Hillsbrad","razboiul dintre Forsaken si Hillsbrad"}}},fx={cca64c76={q="Cine sunt taranii din Hillsbrad?",a="Sunt oamenii de rand din Hillsbrad care au fugit de primul atac asupra fermelor din nord. Ingroziti de inaintarea celor din Forsaken, s-au risipit spre sud, in livezile din Hillsbrad Fields, sperand sa se ascunda de macel, dar cercetasii Darthalia le-au descoperit repede adapostul.",al={"taranii din Hillsbrad","cine sunt taranii","tarani din livezi"}}},fp="19,271,27.478.0,23.422.0,47.266.0,24.186.0,35.185.0,40.148.0,38.220.1,45.259.0"}
P.entries["quest:529"] = {n="Battle of Hillsbrad",s="Aceasta operatiune reprezinta o etapa esentiala in campania Forsaken de cucerire a Hillsbrad Foothills. High Executor Darthalia ordona distrugerea fierariei locale din Hillsbrad Fields, pentru a opri aprovizionarea cu arme a indaratnicilor locuitori umani.",h="Aceasta operatiune reprezinta o etapa esentiala in campania Forsaken de cucerire a Hillsbrad Foothills.",kw={"fierar ucenic","battle of hillsbrad","darthalia","hillsbrad fields","transport de fier","tarren mill","verringtan"},ang={["faction:Alliance"]="Macelarirea lui Verringtan si furtul fierului din asezare lasa fermele de la marginea Southshore fara singurul lor mijloc de autoaparare.",["profession:Blacksmithing"]="Forja lui Verringtan a fost inima pulsanda a rezistentei locale, dovedind ca o nicovala poate fi la fel de periculoasa pentru o armata invadatoare ca un regiment de pedestrasi.",["race:Undead"]="Pentru Forsaken, distrugerea fierariei umane este un pas pragmatic spre securizarea granitelor sudice ale Lordaeronului si strangerea metalului necesar efortului lor de razboi, aflat in dificultate."},sec={{t="Distrugerea nicovalei",b="Rezistenta intampinata de Forsaken in inaintarea prin Hillsbrad Foothills a fost mai indarjita decat se asteptase High Executor Darthalia. Oamenii de la sate au refuzat pur si simplu sa fuga sau sa se predea in fata Deathstalkers si a soldatilor trimisi din Tarren Mill. Cercetarile au dezvaluit ca taranii din zona nu luptau doar cu furci si coase: chiar in mijlocul campurilor li se ofereau arme si echipament de razboi."},{t="Intreruperea liniei de aprovizionare",b="La marginea de sud-vest a campurilor Hillsbrad Fields, fierarul Verringtan si ucenicii sai lucrau fara incetare la forja, transformand minereul brut in lame si armuri pentru garda locala. Trimitand un agent sa-l elimine pe Verringtan, sa-i macelareasca ucenicii si sa le confiste transportul de fier pus deoparte, Darthalia urmarea sa schilodeasca apararea asezarii si sa redirectioneze metalul spre viitorul atac asupra Southshore."}},faq={{q="De ce il vizeaza High Executor Darthalia tocmai pe fierar?",a="Orasenii si fermierii umani opun rezistenta militara neasteptata inaintarii Forsaken. Darthalia a descoperit ca Blacksmith Verringtan si ucenicii sai fauresc arme pentru militia, transformand taranii obisnuiti intr-o amenintare inarmata.",al={"de ce sa-l ucizi pe verringtan","obiectivul fierarului","misiunea verringtan"}},{q="Unde se afla fieraria?",a="Fieraria se afla in partea de sud-vest a Hillsbrad Fields, inconjurata de ucenici la lucru, garzi si patrule locale.",al={"locatia lui Verringtan","unde este fieraria","fieraria din Hillsbrad"}},{q="La ce foloseste transportul de fier?",a="Darthalia confisca fierul pentru a sustine masinaria de razboi Forsaken. Intentioneaza sa foloseasca materiile prime capturate pentru a fauri arme si provizii destinate atacului planificat asupra orasului-port Southshore, aflat sub controlul Alliance.",al={"ce se intampla cu fierul","povestea transportului de fier"}},{q="Cum se inscrie acest lucru in campania mai ampla Battle of Hillsbrad?",a="Aceasta marcheaza a treia etapa a efortului sistematic al lui Darthalia de a desfiinta prezenta oamenilor in tinuturile deluroase: de la eliminarea muncitorilor rurali si a fermierilor, trece la inlaturarea conducerii, logisticii si capacitatii de productie.",al={"lantul Battle of Hillsbrad","campania lui Darthalia"}},{q="Fac oamenii din Hillsbrad Fields parte din armata Alliance?",a="Desi se identifica din punct de vedere cultural cu Southshore si Alliance, locuitorii campurilor sunt in principal fermieri, muncitori si oameni ai orasului din partea locului, care au format o militie ad-hoc pentru a-si apara casele de Forsaken.",al={"sunt fermierii din Hillsbrad aliati","militia din Hillsbrad"}},{q="Cine ordona acest atac?",a="High Executor Darthalia, ofiterul militar superior care coordoneaza operatiunile Forsaken din fortareata Tarren Mill.",al={"cel care da misiunea","cine este darthalia"}}},fx={c3d79e95={q="Cine este fierarul Verringtan?",a="Fierarul Verringtan este metalurgistul local de la atelierul de fierarie aflat la marginea sud-vestica a Hillsbrad Fields. Alaturi de ucenicii sai, el fabrica arme si unelte pentru populatia umana locala, sustinand rezistenta lor apriga impotriva inaintarii Forsaken in zona de coline.",al={"cine este Verringtan","fierarul Verringtan","fierarul din Hillsbrad"}}},fp="19,249,18.390.0,24.422.0,68.262.0,28.129.0,38.214.0,64.233.0,65.211.0,23.123.0"}
P.entries["quest:530"] = {n="A Husband's Revenge",s="A Husband's Revenge incheie o poveste tragica despre o tradare din trecut, care a dainuit si dupa moarte. Raleigh Andrean, un Forsaken care locuieste in Undercity, le cere calatorilor sa-l gaseasca pe fostul sau prieten Valdred Moray, care i-a ucis sotia pe cand era in viata.",h="A Husband's Revenge incheie o poveste tragica despre o tradare din trecut, care a dainuit si dupa moarte.",kw={"Deliah","inel gravat","Greymane Wall","Raleigh Andrean","inelul dispretului","padurea Silverpine","Undercity","Valdred Moray"},ang={["faction:Horde"]="Infaptuirea dreptatii in Silverpine Forest contribuie la apararea granitelor din jurul Undercity impotriva proscrisilor umani ramasi.",["race:Undead"]="Detasarea rece a lui Raleigh fata de sotia sa moarta, alaturi de obsesia persistenta pentru ura si razbunare, zugraveste fara menajamente felul in care strigoii deformeaza psihologia muritorilor."},sec={{t="O amintire amara",b="Cand Raleigh Andrean a primit inelul gravat adus din Silverpine Forest, acesta i-a trezit amintiri din viata de muritor, in mare parte ofilite de strigoi. Printre ele se afla o tradare cumplita: prietenul sau apropiat, Valdred Moray, o omorase pe sotia lui Raleigh, Deliah. Desi frigul Scourge si viata ulterioara in randul Forsaken ii tocisera capacitatea de a simti durerea si iubirea, setea lui de razbunare ramasese nestirbita."},{t="Dreptate la zid",b="Fugind de consecintele faptelor sale din trecut si de ororile din Lordaeron, Valdred Moray s-a indreptat spre sud, traversand Silverpine Forest, disperat sa scape in regatul uman izolationist de dincolo de Greymane Wall. Insa portile colosale au ramas inchise in fata refugiatilor si proscrisilor deopotriva. Prins langa zidul de piatra, Valdred si-a gasit sfarsitul la porunca prietenului pe care il tradase; mainile i-au fost taiate si duse inapoi in Undercity."},{t="Amintiri reci",b="Primind mainile fostului sau prieten, Raleigh nu simte niciun val de caldura sau izbavire - doar o finalitate rece. Dupa ce si-a reglat socotelile, ii inmaneaza fara nicio emotie verigheta Deliahei, declarand-o o podoaba fara rost. In locul ei, mainile taiate ale lui Valdred Moray raman in Undercity, drept amintire sumbra si vesnica a tradarii muritorilor pentru Raleigh."}},faq={{q="De ce vrea Raleigh in mod special mainile lui Valdred?",a="Raleigh cere mainile lui Valdred fiindca ele sunt instrumentele fizice care au pus capat vietii sotiei sale. Vrea sa le pastreze in Undercity drept trofeu permanent si amintire a tradarii prietenului sau.",al={"de ce maini","mainile lui valdred","raleigh vrea maini"}},{q="Unde se ascunde Valdred Moray?",a="Valdred Moray se afla in sudul indepartat al Silverpine Forest, campand langa colosala Greymane Wall, dupa ce nu a reusit sa intre in regatul inchis Gilneas.",al={"unde este valdred","locatia lui valdred","locul unde se afla valdred moray"}},{q="De ce da Raleigh inapoi verigheta?",a="Dupa ce a devenit mort-viu, atasamentul emotional al lui Raleigh fata de Deliah s-a stins cu totul. Nemaifiind capabila de durere sau afectiune, verigheta ei nu este pentru el decat un fleac gol; doar rautatea razbunarii mai avea vreo valoare reala.",al={"de ce sa dai inelul","povestea inelului dispretului","de ce sa arunci inelul"}},{q="Poate Valdred Moray sa intre in Gilneas?",a="Nu. Regele Genn Greymane a izolat Gilneas in spatele unui zid dupa Second War, pentru a se inchide fata de restul lumii, iar portile au ramas inchise. Valdred, la fel ca multi refugiati disperati, a ramas blocat in fata portilor zavorate.",al={"Greymane Wall este inchis","de ce este Valdred in afara zidului"}},{q="Ce misiuni duc la aceasta sarcina?",a="Lantul de misiuni incepe cu 'The Engraved Ring' in Silverpine Forest, care te trimite in Undercity prin 'Raleigh and the Undercity' si deblocheaza 'A Husband's Revenge'.",al={"lantul razbunarii sotului","misiunea necesara anterior","misiunea precedenta"}}},fx={f744ed49={q="De ce vrea Raleigh Andrean sa se razbune?",a="Valdred Moray a fost candva prieten apropiat al lui Raleigh, dar i-a ucis sotia, Deliah. Desi stransoarea rece a mortii i-a rapit lui Raleigh putinta de a jeli sau de a-si plange iubirea pierduta, dorinta arzatoare de razbunare a ramas. Razbunarea mortii ei si pedepsirea tradarii fostului sau prieten sunt singurele dorinte care i-au mai ramas in viata de strigoi.",al={"de ce-l vrea Raleigh mort pe Valdred","motivul lui Raleigh Andrean","de ce sa-l ucizi pe Valdred Moray"}},["71a98bea"]={q="Cine este Valdred Moray si de ce se afla la Greymane Wall?",a="Valdred Moray este fostul prieten al lui Raleigh Andrean, care a ucis-o pe sotia lui Raleigh, Deliah. Dupa ce a comis crima, a fugit spre sud, in Silverpine Forest, si s-a ascuns langa portile pecetluite ale Greymane Wall, disperat sa scape in regatul inchis al Gilneas inainte ca trecutul sa-l ajunga din urma.",al={"cine este Valdred Moray","de ce se afla Valdred Moray in Silverpine","Valdred Moray Greymane Wall"}}},fp="19,249,15.439.0,19.433.1,14.357.1,51.203.0,30.166.0,44.212.1,32.209.0,33.163.0"}
P.entries["quest:532"] = {n="Battle of Hillsbrad",s="Aceasta etapa esentiala a campaniei Forsaken impotriva tinuturilor din jurul Southshore vizeaza conducerea civila a orasului Hillsbrad. Indrumate de High Executor Darthalia din Tarren Mill, fortele Horde il ataca pe Magistrate Burnside, consiliul sau si documentele administrative, pentru a nimici cu totul guvernarea oamenilor de la poalele dealurilor.",h="Aceasta etapa esentiala a campaniei Forsaken impotriva tinuturilor din jurul Southshore vizeaza conducerea...",kw={"battle of hillsbrad","darthalia","consilierii hillsbrad","hillsbrad proclamation","hillsbrad town registry","magistrate burnside","tarren mill","primarie"},ang={["faction:Alliance"]="Uciderea magistratului Burnside si arderea cartei orasului marcheaza prabusirea catastrofala a ultimului guvern local legitim din Hillsbrad.",["faction:Horde"]="Lovirea primariei paralizeaza capacitatea Alliance de a coordona militia locala, asigurand temeinic frontiera sudica a Tarren Mill impotriva contraatacurilor oamenilor.",["race:Undead"]="Pentru Forsaken, eradicarea guvernarii human din Hillsbrad inseamna atat extindere strategica, cat si razbunare nemiloasa impotriva celor vii care contesta granitele Lordaeronului."},sec={{t="Decapitarea consiliului orasului",b="Chiar si dupa ce au suferit pierderi grele pe campuri si in patrule, aparatorii umani din Hillsbrad se agata de autoritatea civila ramasa. High Executor Darthalia intelege ca taranii de rand si militia se raliaza in jurul conducatorilor lor civici. Pentru a garanta prabusirea completa a orasului, agentii Forsaken sunt trimisi direct in Town Hall pentru a-l executa pe Magistrate Burnside si pe cinci dintre consilierii sai, curmand lantul de comanda."},{t="Stergerea registrelor cetatenesti",b="Pe langa asasinatele fizice, Darthalia urmareste dezmembrarea psihologica si administrativa totala a tinutului Hillsbrad. Agentii trebuie sa arda Proclamatia din Hillsbrad, un document politic venerat, care simbolizeaza statutul si mandria asezarii. Odata cu distrugerea acestuia, se confisca si registrul orasului, lipsindu-i pe supravietuitorii loiali Alliance de documentele oficiale si registrele cetatenilor, in timp ce serviciile de informatii din Undercity obtin date detaliate despre populatia locala."}},faq={{q="Cine ordona acest atac?",a="High Executor Darthalia, comandanta Forsaken stationata la Tarren Mill, coordoneaza atacul ca parte a campaniei sale mai ample de nimicire a asezarilor Alliance din piemont.",al={"cine da aceasta misiune","cel care da misiunea Battle of Hillsbrad","Darthalia Hillsbrad"}},{q="Cine este magistratul Burnside?",a="Magistrate Burnside este magistratul si liderul politic al orasului uman Hillsbrad. Aflat in primaria orasului alaturi de consilierii sai, foloseste magia arcana pentru a apara autoritatea ramasa a asezarii.",al={"magistratul burnside","cine este burnside","conducatorul hillsbrad"}},{q="Ce este Proclamatia din Hillsbrad?",a="Proclamatia Hillsbrad este o carta politica respectata, pastrata intr-un loc de cinste in Town Hall. Intruchipeaza guvernarea legala si spiritul locuitorilor orasului, iar distrugerea ei ar fi o lovitura devastatoare pentru moralul civic.",al={"ce este proclamarea","povestea proclamarii din Hillsbrad","distruge proclamarea"}},{q="De ce vrea Darthalia registrul orasului?",a="Registrul orasului contine un recensamant complet si documente administrative despre populatia din Hillsbrad. Furtul lui ii lipseste pe oamenii supravietuitori de memoria lor administrativa si le ofera celor Forsaken informatii vitale despre cine a mai ramas in zona.",al={"de ce sa furi registrul","Hillsbrad Town Registry","la ce foloseste registrul"}},{q="Unde se desfasoara aceasta lupta?",a="Tinte se afla in si in jurul cladirii mari Town Hall, din asezarea oamenilor Hillsbrad, situata la poalele sudice ale dealurilor, intre Tarren Mill si Southshore.",al={"unde este Magistrate Burnside","locatia primariei din Hillsbrad","unde sunt consilierii"}},{q="Ce rol au consilierii?",a="Consilierii din Hillsbrad formeaza corpul de conducere care il ajuta pe Magistrate Burnside. Sunt vrajitori priceputi, care apara atat interiorul Town Hall, cat si terenurile din jurul acestuia.",al={"consilieri din hillsbrad","cine sunt consilierii"}}},fx={["1e1aeb4f"]={q="De ce vrea High Executor Darthalia ca acest lucru sa fie facut?",a="Orasul Hillsbrad este in dezordine dupa atacurile repetate ale Forsaken, dar aparatorii sai Human refuza sa se predea atata vreme cat conducerea locala rezista. High Executor Darthalia intentioneaza sa le zdrobeasca de tot spiritul si sa-i alunge pentru totdeauna de pe coline. Asasinandu-l pe Magistratul Burnside si consiliul, distrugand venerata Proclamatie Hillsbrad si confiscandu-le documentele, ea urmareste sa sfarame structura ramasa care mentine ordinea in Hillsbrad Fields.",al={"de ce sa atac conducerea hillsbrad","motivul lui darthalia battle of hillsbrad","de ce il vrea darthalia mort pe burnside"}},acee9bfa={q="Impotriva cui esti trimis in Hillsbrad?",a="Esti trimis sa-l asasinezi pe magistratul Burnside si pe cinci membri ai consiliului sau, in cladirea primariei din Hillsbrad. In ciuda pierderilor grele suferite pe campuri si in livezi, Burnside si consiliul sau continua sa organizeze apararea locala si sa mobilizeze populatia umana impotriva Tarren Mill. Uciderea magistratului si a consiliului politic priveaza orasul de autoritatea sa de conducere.",al={"pe cine omoram in hillsbrad","tinta din battle of hillsbrad","cine este magistrate burnside si consiliul"}},["827d131a"]={q="La ce foloseste Hillsbrad Town Registry?",a="Hillsbrad Town Registry este registrul civic oficial, care consemneaza populatia locala si proprietatile din Hillsbrad. Acapararea lui ii priveaza pe oamenii supravietuitori de recensamantul administrativ, oferindu-i totodata lui High Executor Darthalia informatii complete despre fiecare locuitor, proprietar si contribuabil din asezare.",al={"ce este hillsbrad town registry","scopul registrului din hillsbrad","de ce sa fur registrul orasului"}}},fp="19,335,29.444.0,24.472.0,23.179.0,27.221.0,35.223.0,42.237.0,33.182.0,33.185.0"}
P.entries["quest:5321"] = {n="The Sleeper Has Awakened"}
P.entries["quest:533"] = {n="Infiltration",s="In Tarren Mill, Krusk afla in sfarsit vesti si zvonuri despre Gol'dir, un Orc tinut prizonier de Syndicate. Oamenii isi tot muta prizonierul, asa ca Krusk si-a restrans cautarile la tabara mare a Syndicate, chiar la nord de oras, si vrea sa-i aduci orice informatie poti gasi.",h="In Tarren Mill, Krusk afla in sfarsit vesti si zvonuri despre Gol'dir, un Orc tinut prizonier de Syndicate.",kw={"alterac","gol'dir","hillsbrad","infiltrare","krusk","misiva","syndicate","tarren mill"},sec={{t="Cuvantul lui Gol'dir",b="Krusk a inceput sa auda vesti si zvonuri despre Gol'dir. Oamenii Syndicate il tot muta pe orc dintr-un loc in altul, dar cautarile se indreapta spre tabara lor mare, chiar la nord de Tarren Mill. Krusk te trimite acolo sa pui mana pe orice informatie poti si sa o aduci inapoi. Krusk se teme ca, pe zi ce trece, perspectivele lui Gol'dir devin tot mai sumbre."},{t="Vesti pentru Krusk",b="Ce aduci inapoi ii arata lui Krusk unde este tinut Gol'dir. Tabara nu este departe de Tarren Mill, iar Krusk spera ca aparatorii ei vor fi mai putin pregatiti decat cei care l-au capturat pe Krusk si pe ceilalti prima oara."}},faq={{q="Pe cine cauta Krusk?",a="Gol'dir, un orc tinut prizonier de Syndicate, ai carui oameni il muta mereu dintr-un loc in altul.",al={"pe cine cauta krusk","cine este goldir","cine trebuie salvat"}},{q="Unde te trimite Krusk pentru a gasi informatiile?",a="La tabara mare a celor din Syndicate, chiar la nord de Tarren Mill, pentru a aduce inapoi orice informatie gasesti despre locul unde se afla Gol'dir.",al={"unde merg pentru infiltrare","locatia taberei Syndicate","unde este scrisoarea Syndicate"}},{q="De ce informatii este nevoie pentru a-l localiza pe Gol'dir?",a="Orice care arata unde se afla Gol'dir. O misiva a Syndicate este cea care trebuie adusa inapoi la Krusk.",al={"ce trebuie sa gasesc","ce obiect cauta Krusk","ce este misiva"}},{q="Cine il tine prizonier pe Gol'dir?",a="Syndicate. Oamenii lor il tot muta dintr-un loc in altul.",al={"cine l-a capturat pe goldir","cine tine prizonier orcul"}}},fp="12,299,15.328.0,14.214.1,25.83.0,50.136.0,45.91.0,23.48.0"}
P.entries["quest:535"] = {n="Valik",s="Henchman Valik zace ranit si pe moarte intr-o tabara Syndicate, fata in fata cu un dusman. Convins ca oricum ii vei ucide, Valik face o intelegere: o halba de Southshore Stout in schimbul unor raspunsuri.",h="Henchman Valik zace ranit si pe moarte intr-o tabara Syndicate, fata in fata cu un dusman.",kw={"Alterac Mountains","acolitul Valik","Southshore Stout","Syndicate","Valik"},sec={{t="Un targ pe moarte",b="Valik e ranit, pe moarte si te vede stand in fata sa ca pe un dusman. Se asteapta ca oricum sa-l ucizi, dar iti propune o intelegere: du o cana de Southshore Stout in tabara Syndicate, iar Valik iti va raspunde la intrebari. Se intreaba chiar cu voce tare daca cei din neamul tau beau macar."},{t="Ultima bautura a lui Valik",b="Valik declara ca berea neagra este cel mai dulce lucru gustat vreodata, avand in vedere moartea care te asteapta. Valik iti da ceva ce nu le este de folos mortilor, apoi iti spune sa treci la treaba."}},faq={{q="Cine este Valik?",a="Henchman Valik este un acolit ranit si pe moarte al Syndicate, gasit in tabara Syndicate.",al={"acolitul Valik","cine este Valik","Valik din Alterac"}},{q="Ce vrea Valik?",a="O halba de Southshore Stout, dusa in tabara Syndicate.",al={"de ce are nevoie valik","bautura lui valik","berea tare a lui valik"}},{q="Ce promite Valik in schimbul berii tari?",a="Valik promite sa-ti impartaseasca ceea ce cauti, desi se asteapta oricum sa fie ucis dupa aceea.",al={"povestea recompensei lui Valik","ce iti spune Valik","schimbul lui Valik"}}},fp="5,193,15.291.0,18.165.1,13.94.0,21.57.0,48.91.0"}
P.entries["quest:536"] = {n="Down the Coast",s="Down the Coast este o misiune a Alliance incredintata de Lieutenant Farren Orinelle in Southshore. Profund nemultumit de transferul sau de la Stormwind la frontiera, locotenentul de garda prefera sa bea bere in loc sa patruleze si angajeaza aventurieri sa alunge murlocii Torn Fin care inainteaza de-a lungul Western Strand.",h="Down the Coast este o misiune a Alliance incredintata de Lieutenant Farren Orinelle in Southshore.",kw={"de-a lungul coastei","farren orinelle","hillsbrad","murloc","redpath","southshore","torn fin","western strand"},ang={["faction:Alliance"]="Southshore este principalul bastion de coasta al Alliance din nord, ceea ce face ca pana si neglijenta marunta a garnizoanei sa puna in pericol supravietuirea orasului.",["race:Human"]="Contrastul dintre centrul ocrotit al Stormwindului si lupta cruda pentru supravietuire din asezarile nordice devine dureros de limpede prin indolenta lui Orinelle."},sec={{t="O repartizare nedorita",b="Lieutenant Farren Orinelle a fost transferat de pe strazile pavate si ingrijite ale garzii orasului Stormwind in portul indepartat si sarat Southshore. Gasind orasul mohorat si mirosul de peste din port de nesuportat, Orinelle isi petrece zilele band la hanul local, in loc sa patruleze linia frontului. Cand Marshal Redpath ii porunceste sa apere Southshore de primejdiile din jur, Orinelle isi subcontracteaza indatoririle unor mercenari aflati in trecere."},{t="Ameninarea Torn Fin",b="Sarcina se desfasoara pe Western Strand, tarmul care se intinde spre vest pornind din Southshore. Desi Orinelle dispretuieste amenintarea reprezentata de 'pesti prea mari', tribul de murloci Torn Fin este cu adevarat primejdios pentru calatoriile de coasta si transporturile navale locale. Adunati in tabere aglomerate de-a lungul valurilor, vinatorii lor ai mareelor si oracolele mistice ii ataca pe toti cei care se indeparteaza prea mult de zidurile orasului, astfel ca eliberarea tarmului devine o treaba singeroasa."}},faq={{q="De ce nu se ocupa Farren Orinelle insusi de murloci?",a="Farren considera ca Southshore este un exil nedorit din viata sa de odinioara, in garda orasului Stormwind. Resentimentar din cauza postului primit si dezgustat de orasul de coasta, ar prefera sa stea in taverna, band bere, in loc sa intre in valuri pentru a lupta cu murlocii, asa ca le plateste aventurierilor sa-i faca treaba.",al={"de ce bea Farren","personalitatea lui Farren Orinelle","de ce sa angajezi aventurieri"}},{q="Cine este 'ol Redpath, mentionat de Orinelle?",a="Se refera la Marshal Redpath, maresalul din Southshore. Redpath raspunde de mentinerea ordinii si apararea asezarii asediate, inclusiv de emiterea ordinelor militare pe care Lieutenant Orinelle cauta pe fata sa le evite.",al={"cine este redpath","magistratul redpath","comandantul din orinelle"}},{q="Unde se afla murlocii Torn Fin?",a="Murlocii Torn Fin traiesc de-a lungul Western Strand, plajele de coasta care se intind spre vest, chiar de la Southshore, in Hillsbrad Foothills.",al={"unde se gasesc Torn Fin","locatia murlocilor din Hillsbrad","locatia de pe Western Strand"}},{q="Ce feluri de murloci trebuie eliminate?",a="Ordinul cere sa-i ucizi pe vanatorii Torn Fin, luptatorii din prima linie ai tribului, precum si pe oracolele Torn Fin, care folosesc magia elementala si acvatica pentru a-si intari semenii.",al={"tinte murloc","ce murloci sa omori","Tidehunter Oracle"}},{q="Ce se intampla dupa ce cureti plaja pentru Orinelle?",a="Dupa ce termina cautarea, Orinelle isi da seama ca are nevoie de dovezi concrete pentru a satisface cercetarile atente ale maresalului Redpath, declansand o serie de sarcini menite sa adune dovezi materiale despre murlocii ucisi.",al={"urmatoarea misiune dupa Down the Coast","lantul de misiuni Down the Coast","urmatorul pas dupa dovada lui Farren"}},{q="Este amenintarea murlocilor cu adevarat serioasa sau doar un pretext?",a="Desi Farren ia in deradere aceste creaturi, considerandu-le doar niste pesti inofensivi si prea mari, Torn Fin sunt numerosi, agresivi si se afla neplacut de aproape de docurile din Southshore, amenintand rutele comerciale si pescarii.",al={"sunt murlocii periculosi in Hillsbrad","pericolul reprezentat de murlocii din Southshore"}}},fx={dc8aa8a8={q="De ce vrea Lieutenant Farren Orinelle ca murlocii sa fie ucisi?",a="Locotenentul Orinelle detesta Southshore si se simte exilat dupa ce a fost transferat din garda orasului Stormwind. Superiorul sau, Marshal Redpath, i-a ordonat sa securizeze litoralul impotriva murlocilor din zona. Farren considera misiunea nedemna de el si isi bate joc de pestii uriasi, spunand ca e o treaba neinsemnata. Punandu-te sa le raresti randurile, spera sa creeze impresia ca se supune ordinelor si mentine Southshore in siguranta, in timp ce isi bea berea si tanjeste dupa o transferare inapoi in capitala.",al={"motivul lui Farren","de ce sa omori murlocii pentru Farren","de ce vrea Farren sa moara murlocii"}},["11ea9e8a"]={q="Ce sunt murlocii Torn Fin de-a lungul coastei?",a="Torn Fin sunt un trib agresiv de murloci care infesteaza Western Strand si tarmurile sudice din Hillsbrad Foothills. Adunati in tabere de pescuit de-a lungul apei, vanatorii lor ai mareelor si oracolele mistice ataca litoralul si sunt o pacoste constanta pentru orasul Southshore. Desi locotenentul Orinelle ii ia in deradere, numindu-i doar niste pesti, numarul lor urias de-a lungul tarmului ii transforma intr-o sursa neintrerupta de necazuri pentru portul local si calatorii de pe coasta.",al={"cine sunt Torn Fin","murlocii Torn Fin","murlocii din Hillsbrad"}}},fp="14,293,19.458.0,19.442.0,58.293.0,42.242.0,39.139.0,44.179.0,51.196.1,56.195.0"}
P.entries["quest:5361"] = {n="Family Tree",s="Cliffwatcher Longhorn iti cere sa duci un raport la Nataka Longhorn, fratele lui Cliffwatcher, stationat in Desolace. Vestea despre activitatea neobisnuita a centaurilor trebuie sa ajunga la Ghost Walker Post.",h="Cliffwatcher Longhorn iti cere sa duci un raport la Nataka Longhorn, fratele lui Cliffwatcher, stationat in...",kw={"centaur","charred vale","cliffwatcher longhorn","desolace","arbore genealogic","ghost walker post","nataka longhorn","stonetalon","thousand needles"},sec={{t="Un raport pentru un frate",b="Nataka, fratele lui Cliffwatcher, este detasat la Ghost Walker Post din Desolace. A trecut un an de cand Cliffwatcher i-a scris ultima oara si, in acest timp, centaurii s-au purtat ciudat. Nataka ar trebui sa afle, iar tu esti rugat sa-i duci raportul."},{t="Drumul pana acolo",b="Drumul duce la Stonetalon Mountain, la nord de Crossroads, apoi spre vest, in Charred Vale. De acolo coteste spre sud, in Desolace, unde un drum merge spre sud pana la Ghost Walker Post."},{t="O primire la avanpost",b="Nataka Longhorn nu poate spune de unde stii de Cliffwatcher, dar pare ca Cliffwatcher are incredere in tine. Nataka iti ureaza bun venit la Ghost Walker Post, unde sunt multe de facut, si te sfatuieste sa vorbesti cu ceilalti de acolo, fiindca cineva s-ar putea sa aiba nevoie de ajutorul tau."}},faq={{q="Cu cine incearca sa ia legatura Cliffwatcher Longhorn?",a="Nataka Longhorn, fratele lui Cliffwatcher, stationat la Ghost Walker Post, in Desolace.",al={"cine este Nataka","fratele Longhorn","cine primeste raportul"}},{q="De ce trimite acum Cliffwatcher Longhorn un raport?",a="Cliffwatcher nu a mai scris de un an, iar de atunci centaurii s-au purtat neobisnuit, asa ca ar trebui sa i se spuna lui Nataka.",al={"de ce sa trimiti raportul","raport despre activitatea centaurilor","motivul mesajului"}},{q="Unde se afla Nataka Longhorn?",a="La Ghost Walker Post din Desolace, la care ajungi pe un drum ce se indreapta spre sud.",al={"locatia Nataka","unde este Ghost Walker Post","unde trebuie predat raportul"}},{q="Ce drum duce de la Thousand Needles la Ghost Walker Post?",a="Indreapta-te spre Stonetalon Mountain, la nord de Crossroads. De acolo, mergi spre vest in Charred Vale, apoi spre sud, in Desolace, si continua pe drum pana la Ghost Walker Post.",al={"cum ajung in Desolace","drumul spre Ghost Walker Post","calea de urmat"}}},fp="11,192,22.255.0,13.192.0,21.239.1,47.88.0,50.122.0,33.74.0,59.161.0"}
P.entries["quest:537"] = {n="Dark Council",s="Magistrate Henry Maleb din Southshore a aflat ca scrisoarea pe care ai adus-o a fost trimisa de o fiinta care se numeste Nagaz si face parte din Argus Wake. Daca Argus Wake este aliat cu Syndicate, spune Maleb, atunci trebuie sa reprezinte o amenintare. Esti trimis sa-i vanezi pe Nagaz si pe Argus Shadow Mages din Uplands.",h="Magistrate Henry Maleb din Southshore a aflat ca scrisoarea pe care ai adus-o a fost trimisa de o fiinta care...",kw={"argus shadow mage","argus wake","dark council","henry maleb","nagaz","southshore","strahnbrad","syndicate","uplands"},sec={{t="Emisari in Uplands",b="Dupa Further Mysteries, Maleb iti spune ca scrisoarea provenea de la o fiinta care isi spune Nagaz si face parte din Argus Wake. Maleb nu stie ce este Argus Wake, dar o alianta cu Syndicate i-ar transforma intr-o amenintare. Maleb vrea ca Nagaz si Argus Shadow Mages, pomeniti in scrisoare, sa fie gasiti si ucisi si iti cere capul lui Nagaz. Trebuie sa cauti in Uplands, la nord de Strahnbrad, unde Syndicate este cel mai puternic. Maleb spera ca trimisii lui Argus Wake se afla acolo."},{t="Concluziile lui Maleb",b="Maleb nu se bucura la gandul ca o organizatie precum Argus Wake ar putea conduce Syndicate. Nagaz nu era decat slujitorul altcuiva, adauga Maleb, iar influenta Argus Wake s-ar putea intinde departe pe continent sau chiar in intreaga lume."}},faq={{q="Cine te trimite dupa Nagaz?",a="Magistrate Henry Maleb din Southshore, care a citit scrisoarea pe care i-ai adus-o.",al={"cine ofera Dark Council","cel care da misiunea Dark Council","unde accept misiunea Dark Council"}},{q="Unde se afla Nagaz si Argus Shadow Mages?",a="Maleb iti spune sa cauti in Uplands, la nord de Strahnbrad, unde Syndicate este cel mai puternic.",al={"unde este nagaz","locatia lui argus shadow mage","unde sunt zonele inalte"}},{q="Ce este Argus Wake?",a="Maleb nu stie. Stie doar ca Nagaz ii apartine si ca, daca este aliat cu Syndicate, trebuie sa fie o amenintare.",al={"cine sunt Argus Wake","ce este Argus Wake","povestea Argus Wake"}},{q="Ce se intampla inainte de asta?",a="Urmeaza dupa Further Mysteries, in care i-ai dus scrisoarea descifrata lui Maleb.",al={"cerinta prealabila pentru dark council","misiunea anterioara","ce misiune urmeaza inainte"}}},fp="12,301,21.471.0,20.214.1,26.74.0,51.93.0,23.126.0,25.81.0"}
P.entries["quest:5381"] = {n="Hand of Iruxos"}
P.entries["quest:5386"] = {n="Catch of the Day",s="La Ghost Walker Post nu s-a mai simtit de mult miros de peste gatit, iar Nataka Longhorn ar vrea sa schimbe asta. Nataka ii considera pe trolls din Shadowprey Village cei mai priceputi pescari, insa toata activitatea centaurilor lasa putin timp pentru calatorie. Ti se cere sa mergi in locul lui Nataka si sa aduci inapoi doi pesti Bloodbelly.",h="La Ghost Walker Post nu s-a mai simtit de mult miros de peste gatit, iar Nataka Longhorn ar vrea sa schimbe...",kw={"peste bloodbelly","catch of the day","centaur","desolace","ghost walker post","jinar'zillen","nataka longhorn","shadowprey village"},sec={{t="Gustul coastei",b="De multa vreme nu s-a mai simtit miros de peste gatit la Ghost Walker Post. Nataka Longhorn ii considera pe troll din Shadowprey Village cei mai priceputi pescari, dar, cu atata activitate a centaurilor, nu prea exista timp pentru calatorie. Asa ca ti se cere sa mergi acolo, sa vorbesti cu pescarul local Jinar'Zillen si sa te intorci cu doi pesti Bloodbelly, preferatii lui Nataka. Drumul de la sud de avanpost coteste spre vest si te duce la satul troll."}},faq={{q="Cine cauta pesti Bloodbelly?",a="Nataka Longhorn de la Ghost Walker Post din Desolace. Pestii Bloodbelly sunt preferatii lui Nataka.",al={"cine da Catch of the Day","misiunea Nataka Longhorn"}},{q="De ce nu poate Nataka Longhorn sa prinda singura pestele?",a="Din cauza activitatii intense a centaurilor, Nataka are putin timp sa faca drumul pana la Troll.",al={"de ce nu poate pleca nataka","de ce are nataka nevoie de ajutor"}},{q="Unde pot fi gasiti pestii Bloodbelly?",a="Nataka te trimite la Shadowprey Village, un sat de Troll, sa vorbesti cu pescarul local Jinar'Zillen.",al={"unde gasesc pestele bloodbelly","locatia lui jinar'zillen"}},{q="Cum ajungi la Shadowprey Village din Ghost Walker Post?",a="Drumul spre sud de la avanpost duce spre vest, la satul Troll.",al={"drumul spre Shadowprey Village","cum ajung in satul Troll"}},{q="Cati pesti Bloodbelly vrea Nataka?",a="Doi.",al={"cati pesti","numarul pestilor Bloodbelly"}}},fp="16,338,20.435.0,35.88.0,47.88.0,39.104.0,59.61.0,42.4.0"}
P.entries["quest:539"] = {n="Battle of Hillsbrad",s="Acest ordin de campanie de la High Executor Darthalia le cere agentilor Horde sa loveasca in adancul Azurelode Mine, o mina vitala de fier, la sud de Hillsbrad Fields. Eliminandu-l pe Foreman Bonds si pe oamenii sai, Forsaken urmaresc sa opreasca transporturile de fier catre arsenalele Alliance si sa puna stapanire pe tuneluri.",h="Acest ordin de campanie de la High Executor Darthalia le cere agentilor Horde sa loveasca in adancul...",kw={"Azurelode","legaturi","Darthalia","Hillsbrad","fier","mineri","Southshore","Tarren Mill","Undercity"},ang={["faction:Horde"]="Perturbarea aprovizionarii principale cu metal a Alliance in Hillsbrad slabeste presiunea asupra frontului din Tarren Mill, impiedicand trupele umane sa-si inlocuiasca usor echipamentul.",["profession:Mining"]="Azurelode Mine este una dintre cele mai bogate exploatari de fier din regiunea deluroasa, ceea ce o transforma intr-un punct firesc de conflict pentru toti cei care se lupta pentru filoanele valoroase de minereu.",["race:Undead"]="Cucerirea Azurelode Mine asigura fierul vital pentru Deathguard, punand industria umana in slujba inarmarii armatelor lui Sylvanas din tot Lordaeron."},sec={{t="Intreruperea aprovizionarii cu fier",b="Dupa ce a pus mana in raidurile anterioare pe Hillsbrad Town Registry, High Executor Darthalia a identificat Azurelode Mine drept un punct esential pentru rezistenta militara a oamenilor din regiune. Mina se afla chiar la sud de campurile disputate si extrage fara incetare filoane bogate de minereu de fier, pentru a aproviziona armurarii si arsenalele Alliance. Daca ar ramane neatinsa, fortele din Southshore si-ar putea reface inarmarea si-si putea intari garnizoanele, anuland astfel victoriile de pana atunci ale Tarren Mill."},{t="Un mesaj hotarator",b="Pentru a opri complet productia, Darthalia tinteste atat conducerea, cat si forta de munca. Fortele Horde primesc ordinul de a-l elimina pe Foreman Bonds, supraveghetorul uman al sapaturii, impreuna cu o parte insemnata din muncitori. Lovitura data in puturile intunecate transmite un mesaj limpede catre Southshore: nici liniile lor de aprovizionare, nici taberele de munca izolate nu sunt in afara razei de actiune a celor din Forsaken."},{t="Prada pentru Dark Lady",b="Pe langa faptul ca priveaza Alliance de materiale de razboi, acest atac are si un scop secundar practic pentru Undercity. Ocuparea minei le permite fortelor lui Sylvanas Windrunner sa puna mana pe filoanele bogate de minereu pentru propriile lor turnatorii. Tarren Mill are nevoie de un flux constant de metal pentru fabricarea armelor si armurilor in razboiul din Lordaeron, transformand odata o resursa a oamenilor intr-un motor al cuceririi Forsaken."}},faq={{q="De ce este Azurelode Mine atat de importanta pentru Forsaken?",a="Azurelode Mine furnizeaza minereu de fier de inalta calitate direct arsenalelor Alliance. Cucerirea ei lipseste garnizoanele umane precum cea din Southshore de materialele necesare fauririi armelor, oferind in acelasi timp Undercity o sursa bogata de metal brut pentru echiparea fortelor Forsaken.",al={"de ce sa ataci azurelode","scopul azurelode mine","de ce sa vizezi mina"}},{q="Cine este Foreman Bonds?",a="Foreman Bonds este supraveghetorul uman responsabil de excavarea Azurelode. El gestioneaza minerii si poate chema in ajutor aparatori dwarven neclintiti daca este incoltit adanc in galeriile de jos.",al={"foreman Bonds","cine este Bonds","cine conduce mina"}},{q="Unde se afla Azurelode Mine?",a="Azurelode Mine este sapata in dealurile de la sud de Hillsbrad Fields, la vest de Southshore, de-a lungul falezelor de coasta.",al={"unde se afla Azurelode Mine","locatia Azurelode","cum sa gasesti mina"}},{q="Cum a aflat Darthalia despre operatiunile minei?",a="Darthalia a descoperit valoarea logistica si activitatea minei consultand Hillsbrad Town Registry, recuperat de agentii Horde in timpul unor raiduri anterioare asupra asezarilor oamenilor.",al={"de unde a aflat darthalia","registrul orasului si mina","informatii despre hillsbrad"}},{q="Ce se intampla dupa ce Foreman Bonds este ucis?",a="Cu mina scoasa din functiune si resursele ei destinate controlului Forsaken, High Executor Darthalia intensifica ofensiva, indreptand atentia Horde spre distrugerea infrastructurii ramase din Hillsbrad si inaintarea spre Southshore.",al={"ce urmeaza dupa Battle of Hillsbrad","dupa uciderea lui Bonds","urmari ale misiunii"}},{q="Apara Alliance mina?",a="Da. Pe langa minerii umani care lucreaza in galerii, Alliance mentine garzi inarmate la intrare, iar Foreman Bonds are la indemana intarituri dwarven rezistente, adanc in tuneluri.",al={"garzile minei","prezenta Aliantei in Azurelode","piticii din mina"}}},fp="19,299,24.454.0,18.389.0,24.402.1,51.235.0,21.187.0,36.121.0,55.191.0,42.247.1,34.187.0"}
P.entries["quest:54"] = {n="Report to Goldshire",s="Report to Goldshire marcheaza trecerea oficiala a unui aventurier din tinuturile ocrotite ale Northshire Valley sub jurisdictia mai vasta a Elwynn Forest. Ducand ordine de la Marshal McBride la Marshal Dughan, recrutii primesc statutul de adjuncti temporari, in vreme ce neglijenta nobilimii din Stormwind fata de regiune se accentueaza.",h="Report to Goldshire marcheaza trecerea oficiala a unui aventurier din tinuturile ocrotite ale Northshire...",kw={"adjunct in functie","elwynn forest","goldshire","marshal dughan","marshal mcbride","northshire","raporteaza-te la goldshire","maresali din stormwind"},ang={["faction:Alliance"]="Cu armata din Stormwind trimisa in alta parte, apararea regiunii Elwynn se bazeaza tot mai mult pe recruti locali si voluntari abia numiti in functie.",["race:Human"]="Trecerea de la Northshire in slujba din Goldshire marcheaza prima recunoastere oficiala a unui aventurier Human de catre ierarhia militara din Stormwind."},sec={{t="Din Northshire in Padurea Mare",b="Dupa ce si-au dovedit valoarea in fata problemelor locale din Northshire Valley, recrutilor li se da oficial dezlegare de la garda locala din Northshire de catre Marshal McBride. In semn de recunoastere pentru serviciul lor, McBride pregateste acte de transfer care ii trimit spre sud, dincolo de portile de la granita, pe drumul catre Goldshire, unde responsabilitatile lor trec in seama administratiei mai largi din Elwynn Forest."},{t="Povara maresalilor",b="La sosirea in Goldshire, Marshal Dughan primeste ordinele scrise ale lui McBride si ii atribuie oficial recrutului gradul de adjunct interimar in cadrul maresalilor din Stormwind. Totusi, bun venit-ul lui Dughan vine cu un avertisment sumbru: Northshire e o gradina linistita in comparatie cu primejdiile care cutreiera Elwynn, mai ales cand armata regala din Stormwind e prinsa in jocuri politice pentru nobili indepartati, in loc sa apere meleagurile natale."}},faq={{q="Cine este Marshal Dughan?",a="Marshal Dughan este ofiterul comandant al maresalilor din Stormwind stationati in Goldshire, responsabil de organizarea apararii si a patrulelor din Elwynn Forest.",al={"cine este Marshal Dughan","unde se afla Dughan","rolul lui Dughan"}},{q="De ce sunt trimisi recrutii la Goldshire?",a="Dupa ce se ocupa de amenintarile imediate din valea linistita Northshire Valley, Marshal McBride ii trimite pe recrutele capabile spre sud, la Goldshire, pentru a contribui la infruntarea pericolelor mult mai ample care ameninta Elwynn Forest.",al={"de ce sa mergi la Goldshire","plecarea din Northshire","urmatorul pas dupa Northshire"}},{q="Ce inseamna statutul de adjunct interimar?",a="Gradul de adjunct interimar este un rang provizoriu de teren acordat prin documentele lui Marshal McBride, care le permite recrutilor promitatori sa intre in randurile garzilor din Stormwind si sa ajute la mentinerea ordinii la nivel local.",al={"adjunct interimar","ce inseamna statutul de adjunct interimar","semnificatia statutului de adjunct"}},{q="Unde se afla armata din Stormwind?",a="Potrivit lui Marshal Dughan, cea mai mare parte a armatei permanente din Stormwind a fost trimisa in alta parte, ocupata cu misiuni si indatoriri impuse de nobilii de la curte, in loc sa patruleze asezarile locale.",al={"unde este armata din Stormwind","armata din Stormwind a disparut","de ce nu este Elwynn aparat"}},{q="Cine este Marshal McBride?",a="Marshal McBride supravegheaza garnizoana din Northshire Abbey, instruind noii aparatori inainte de a-i trimite pe cei care se dovedesc vrednici pe linia frontului din Goldshire.",al={"cine este mcbride","rolul lui mcbride"}},{q="Cum ajungi la Goldshire din Northshire?",a="Goldshire se afla de-a lungul drumului principal care coboara spre sud din Northshire Valley, trece de portile de hotar si ajunge in inima Elwynn Forest.",al={"drumul spre Goldshire","cum ajung la Goldshire","indicatii spre Goldshire"}}},fp="19,313,37.373.0,26.407.0,22.161.0,35.211.0,36.191.0,28.177.0,23.155.0,42.134.0"}
P.entries["quest:540"] = {n="Preserving Knowledge"}
P.entries["quest:541"] = {n="Battle of Hillsbrad",s="Aceasta etapa cruciala a campaniei Forsaken din Hillsbrad vizeaza fortareata piticilor din Dun Garok. High Executor Darthalia trimite campioni Horde sa distruga garnizoana piticilor care ii ajuta pe oamenii din zona si sa-l execute pe comandantul acesteia, Captain Ironhill.",h="Aceasta etapa cruciala a campaniei Forsaken din Hillsbrad vizeaza fortareata piticilor din Dun Garok.",kw={"battle of hillsbrad","captain ironhill","dun garok","high executor darthalia","alpinist","puscas","tarren mill","thoradin's wall"},ang={["faction:Horde"]="Atacarea Dun Garok intrerupe sosirea intaririlor militare esentiale trimise de Ironforge pentru a-i ajuta pe oamenii asediati din Southshore.",["race:Dwarf"]="Dun Garok reprezinta loialitatea neclintita a celor din Ironforge fata de aliatii lor Human, rezistand asediului Forsaken pentru a apara frontiera nordica.",["race:Undead"]="Pentru Forsaken, eliminarea garnizoanei dwarf asigura sud-estul Lordaeron si impiedica orice avangarda sudica a Alliance sa marsaluiasca usor prin Thoradin's Wall."},sec={{t="Testarea Alliance-ului",b="Dupa ce a pus presiune asupra fermierilor umani si a militiei orasului din tinuturile deluroase, High Executor Darthalia intoarce furia din Tarren Mill impotriva contingentului militar din Ironforge. Trupele piticesti au luat armele in sprijinul localitatii Southshore, intarind prezenta umana din Lordaeron. Pentru Darthalia, aceasta solidaritate este un obstacol care trebuie zdrobit, pentru a le demonstra celor din Alliance ca ajutorul oferit ramasitelor umane nu va aduce decat devastare."},{t="Caderea lui Dun Garok",b="Asezat langa vechile metereze ale lui Thoradin's Wall, in sud-estul Hillsbrad, Dun Garok este un bastion pitic puternic fortificat. Pentru a lua avanpostul cu asalt, trebuie strapunse randurile de luptatori disciplinati ai muntilor, tragatori de elita si preoti caliti in lupta. Atacul culmineaza cu moartea capitanului Ironhill, dezarticuland comanda tactica inaintata a Ironforge din regiune si lasand izolate enclavele umane ramase."}},faq={{q="De ce se lupta dwarves in Hillsbrad?",a="Piticii din Ironforge au legaturi stranse cu Alliance si au trimis forte inarmate spre nord, la Dun Garok, pentru a-i ajuta pe oamenii supravietuitori din Southshore si Hillsbrad impotriva expansiunii Forsaken.",al={"de ce sunt pitici in Hillsbrad","piticii din Dun Garok","de ce ii ajuta piticii pe oameni"}},{q="Unde se afla Dun Garok?",a="Dun Garok se afla in coltul sud-estic al Hillsbrad Foothills, fiind construit direct in fundatiile lui Thoradin's Wall.",al={"locatia dun garok","unde este dun garok","gaseste dun garok"}},{q="Cine este Captain Ironhill?",a="Capitanul Ironhill este comandantul dwarf care conduce garnizoana din Dun Garok. Prezenta sa mentine organizati si operationali luptatorii de munte din regiune.",al={"capitanul Ironhill","cine este Ironhill","conducatorul din Dun Garok"}},{q="Cine da acest ordin?",a="High Executor Darthalia, comandantul militar Forsaken stationat la Tarren Mill, da misiunea de a zdrobi garnizoana piticilor.",al={"cine ofera misiunea","cel care ofera misiunea, Darthalia","Darthalia din Hillsbrad"}},{q="Ce se intampla daca fortele Horde esueaza aici?",a="High Executor Darthalia spune limpede ca esecul este de neacceptat, avertizand ca oricine nu poate infrange Dun Garok va fi retrogradat si pus sa sape morminte inapoi in Tirisfal Glades.",al={"ce se intampla daca esuezi","amenintarea lui Darthalia","consecinte"}},{q="De ce este atat de greu sa asediezi Dun Garok?",a="Spre deosebire de militia rurala din Hillsbrad, Dun Garok este garnizoana unui corp de soldati pitici instruiti, echipe de tragatori si preoti sacri, care lupta in formatii compacte si fortificate in buncarul subteran si in cel inaltat.",al={"Dun Garok de elita","de ce este Dun Garok dificil","apararea din Dun Garok"}}},fx={b055c9ea={q="De ce vrea High Executor Darthalia sa atace Dun Garok?",a="Forsaken duc o campanie totala pentru a inlatura controlul oamenilor asupra Hillsbrad Foothills, dar piticii din Ironforge au intervenit pentru a-si sprijini aliatii din Alliance. High Executor Darthalia intentioneaza sa zdrobeasca hotararea celor din Alliance, aratandu-le pretul platit pentru apararea Southshore. Distrugandu-le cazarma din Dun Garok si ucigandu-le comandantul, urmareste sa intrerupa sosirea intaririlor umane si sa aduca intreaga regiune sub dominatia Dark Lady.",al={"de ce sa ataci Dun Garok","motivul lui Darthalia","de ce sa-i ucizi pe pitici"}}},fp="19,270,20.421.0,21.433.0,38.202.0,27.128.0,24.158.0,21.132.0,39.172.0,41.205.0"}
P.entries["quest:5421"] = {n="Fish in a Bucket",s="Jinar'Zillen din Shadowprey Village, in Desolace, prefera sa faca cat mai putin posibil. Sub docurile satului se afla multe capcane pentru crustacee, iar oricine le aduna va primi in schimb ceva care merita.",h="Jinar'Zillen din Shadowprey Village, in Desolace, prefera sa faca cat mai putin posibil.",kw={"bloodbelly fish","desolace","fish in a bucket","jinar'zillen","shadowprey village","crustacee"},sec={{t="Munca facuta de altcineva",b="Jinar'Zillen tine multe capcane de crustacee sub docurile din Shadowprey Village si ar prefera nespus ca altcineva sa se ocupe de strans. Oricine e dispus sa faca treaba va primi in schimb ceva ce-si doreste: cate un peste Bloodbelly de calitate pentru fiecare cinci crustacee aduse."}},faq={{q="Cine ofera acest schimb?",a="Jinar'Zillen, in Shadowprey Village din Desolace.",al={"cine ofera Fish in a Bucket","jinar'zillen","cel care da misiunea"}},{q="Unde se afla capcanele pentru crustacee?",a="Sub docurile din Shadowprey Village.",al={"locatia capcanei","unde gasesc crustacee","capcane pentru crustacee"}},{q="De ce vrea Jinar'Zillen ca altcineva sa adune crustaceele?",a="Jinar'Zillen prefera sa faca cat mai putin, asa ca oricine strange din capcane primeste promisiunea unei recompense.",al={"de ce are nevoie de fructe de mare","motivul lui Jinar'Zillen"}},{q="Ce ofera Jinar'Zillen in schimbul fructelor de mare?",a="Un peste Bloodbelly de calitate pentru fiecare cinci moluste.",al={"rasplata pentru Fish in a Bucket","ce primesc"}}},fp="16,222,25.273.0,22.48.0,30.38.0,64.119.0,56.50.0"}
P.entries["quest:543"] = {n="The Perenolde Tiara",s="Count Remington Ridgewell cauta o mostenire pierduta in Ruins of Alterac. Aristocratul din Stormwind trimite mercenari spre nord sa recupereze Perenolde Tiara, care a apartinut candva familiei regale din Alterac si despre care se spune acum ca se afla la un mag ogre.",h="Count Remington Ridgewell cauta o mostenire pierduta in Ruins of Alterac.",kw={"alterac","crushridge","grel'borg","miser","perenolde","ridgewell","stormwind","diadema"},ang={["faction:Alliance"]="Calatorind spre nord, in muntii fara lege din Alterac Mountains, poti elimina periculosii ogres Crushridge si recupera artefacte istorice de nepretuit pentru nobilimea din Stormwind.",["race:Dwarf"]="Tiara a fost faurita de maestrii giuvaiergii din Ironforge. Munca lor migaloasa a dainuit chiar si dupa prabusirea unui regat Human.",["race:Human"]="Pentru oamenii din Alliance, tiara le aminteste de tradarea din Alterac din timpul Second War, cand familia regala umana s-a aliat cu Horde impotriva propriilor semeni."},sec={{t="O relicva a unui regat ruinat",b="Perenolde Tiara este o relicva minunata din regatul human cazut Alterac. Faurita de maestri bijutieri dwarves in Ironforge, podoaba bogat ornamentata a fost incrustata cu cele mai fine smaralde pentru a impodobi familia domnitoare Perenolde. Totusi, in timpul Second War, King Aiden Perenolde a tradat Grand Alliance in favoarea Orcish Horde, ceea ce a dus direct la prabusirea, cucerirea si ruinarea definitiva a regatului sau. In haosul si caderea care au urmat ale Alterac City, multe dintre cele mai mari comori ale dinastiei regale au disparut sub daramaturile inzapezite din Alterac Mountains."},{t="Avarul din ruine",b="Grel'borg the Miser, un ogre mage dintre ogrele Crushridge, a ajuns sa detina tiara printre ruinele din Alterac. El scotoceste printre pietrele sfaramate dupa podoabe si bogatii abandonate. Count Remington Ridgewell, colectionar de curiozitati istorice din Stormwind City, afla ca tiara a supravietuit. El angajeaza mercenari sa patrunda pe teritoriul ocupat de ogre, sa-l invinga pe Grel'borg si sa aduca bijuteria inapoi in galeria sa."}},faq={{q="Cine era familia Perenolde?",a="Perenoldes erau familia regala din Alterac, regatul Human din nord. In timpul Second War, regele Aiden Perenolde a colaborat cu invadatorii din Orcish Horde pentru a-si cruta regatul. Alliance of Lordaeron i-a descoperit tradarea, a ocupat Alterac, i-a desfiintat tronul si a lasat regatul sa se prabuseasca in anarhie si ruina.",al={"casa perenolde","cine erau perenoldii","povestea lui perenolde"}},{q="Cine a creat Perenolde Tiara?",a="Bijutierii maestri din Ironforge au facut tiara. Au impodobit-o cu smaralde, ca semn al nobletii si bogatiei familiei conducatoare din Alterac.",al={"originea tiarei","cine a creat Perenolde Tiara"}},{q="Cine detine acum tiara?",a="Grel'borg the Miser tine diadema. Mage-ul ogre cauta comori prin Ruins of Alterac inzapezite, ramasite ale vechiului oras human.",al={"grelborg","cine are Perenolde Tiara","locatia tiarei"}},{q="De ce vrea Count Remington Ridgewell tiara?",a="Count Remington Ridgewell doreste tiara pentru colectia sa privata. Nobilul bogat si anticar locuieste in Stormwind City si angajeaza mercenari pentru a recupera comori pierdute din locuri primejdioase de pe tot cuprinsul Azeroth.",al={"motivul lui Remington Ridgewell","de ce sa iei tiara"}},{q="Unde se afla Ruins of Alterac?",a="Ruins of Alterac se afla in nordul Alterac Mountains, la nord de Hillsbrad Foothills si de regiunea Durnholde. Ogrele Crushridge si haiducii Syndicate au napadit acum orasul abandonat.",al={"locatia ruinelor din alterac","unde se afla alterac"}},{q="Ce se intampla cu tiara dupa ce o recuperezi?",a="Dupa ce Count Ridgewell primeste heirloom-ul plin de noroi si patat, restauratorii profesionisti il curata si il lustruiesc. Apoi il expune ca piesa de rezistenta a colectiei sale.",al={"predare tiara","soarta tiarei"}}},fx={["19149d4d"]={q="Ce este Perenolde Tiara?",a="Perenolde Tiara este o bijuterie regala nepretuita, lucrata de bijutieri pitici maestri din Ironforge. Impodobita cu smaralde de o frumusete rara, aceasta impodobea odinioara capetele nobilimii conducatoare din Alterac. Cand regatul tradator s-a prabusit si a ajuns in ruina, tiara a disparut in negura istoriei, fiind ravnita de colectionari atat pentru frumusetea ei extravaganta, cat si pentru valoarea istorica.",al={"ce este Perenolde Tiara","povestea Perenolde Tiara","tiara lui Perenolde"}},e2bd82b9={q="De ce angajeaza Count Ridgewell un aventurier in loc sa-si trimita oamenii?",a="Count Remington Ridgewell este un nobil din Stormwind meticulos, care se ingrijoreaza sa-si pastreze curati mansetele pantalonilor croiti pe masura; nu e nicidecum omul care sa porneasca intr-o calatorie spre nord, prin salbaticia inghetata. In plus, Alterac se afla mult dincolo de jurisdictia si raza de actiune a garzii orasului Stormwind, fiind cotropit de capcauni ostili si haiduci. Recuperarea unei asemenea mosteniri din ruine indepartate cere un aventurier vanjos, gata sa faca treburi periculoase si murdare pentru bani.",al={"de ce sa-mi trimita Perenolde Tiara","de ce nu garda regala","de ce are nevoie Ridgewell de mine"}}},fp="19,231,27.373.0,22.391.0,29.339.0,29.132.0,24.139.0,50.213.0,39.188.0,47.157.1"}
P.entries["quest:544"] = {n="Prison Break In",s="Magus Wordeen Voidglare se afla in Tarren Mill pentru cercetari, dar acum se confrunta cu o criza. Cu cateva luni in urma, patru Forsaken au fugit din Undercity dupa ce au furat artefacte dintr-o seif bine pazit, iar Sylvanas le vrea inapoi.",h="Magus Wordeen Voidglare se afla in Tarren Mill pentru cercetari, dar acum se confrunta cu o criza.",kw={"alina","bloodstone","dalaran","dermot","kegan darkmar","lordamere internment camp","ricter","tarren mill","wordeen voidglare"},sec={{t="Hotii lui Dark Lady",b="Voidglare a venit la Tarren Mill sa faca cercetari, iar acum trebuie sa rezolve o criza. Patru Forsaken si-au intors spatele fata de fratii lor si, mai rau, au furat de la Dark Lady. Au patruns intr-un seif bine pazit si au luat patru artefacte de care aveau nevoie alchimistii pentru anumite studii. Sylvanas vrea sa fie aduse inapoi."},{t="Lag arul de internare",b="Hotii au fugit din Undercity la Dalaran, unde magii i-au pus in carantina la Lordamere Internment Camp. Trebuie sa-i gasesti pe tradatori, sa recuperezi artefactele si sa-i raportezi lui Voidglare, in Tarren Mill. Sunt patru: o pana Bloodstone, o marmura, un ciob si un oval. Dermot are pana, Ricter marmura, Alina ciobul, iar Kegan Darkmar ovalul."}},faq={{q="Cine este Magus Wordeen Voidglare?",a="Un magus aflat in Tarren Mill pentru cercetari, care se confrunta acum cu o criza: patru artefacte furate de la Dark Lady.",al={"magus voidglare","wordeen voidglare","cel care ofera misiunea"}},{q="Ce au furat hotii Forsaken?",a="Patru artefacte dintr-o seif bine pazit, de care aveau nevoie apotecarii pentru anumite studii: o pana Bloodstone, o piesa de Marble, un fragment si un Oval.",al={"ce a fost furat","bloodstones","artefacte furate"}},{q="Unde sunt tinuti hotii?",a="La Lordamere Internment Camp, unde vrajitorii din Dalaran i-au pus in carantina.",al={"locatia lagarului de internare","unde sunt tradatorii","unde este kegan"}},{q="Cine sunt cei patru tradatori?",a="Dermot are Bloodstone Wedge, Ricter are Marble, Alina are Shard, iar Kegan Darkmar are Oval.",al={"numele hotilor","patru Forsaken","cine a furat pietrele de sange"}}},fp="15,203,24.293.0,19.360.0,31.107.0,36.130.0,33.83.0,26.97.0"}
P.entries["quest:545"] = {n="Dalaran Patrols",s="Magus Wordeen Voidglare din Tarren Mill nu da doi bani pe motivul pentru care vrajitorii din Dalaran au ridicat o cupola magica uriasa deasupra centrului orasului lor. Important este ca ruinele de dincolo de cupola ar putea ascunde comori cu adevarat valoroase din punct de vedere magic, in timp ce vrajitorii si sclavii lor elementali patruleaza zona. Voidglare vrea ca patrulele sa fie imputinate.",h="Magus Wordeen Voidglare din Tarren Mill nu da doi bani pe motivul pentru care vrajitorii din Dalaran au...",kw={"dalaran","invocatori din dalaran","slujitori elementali","hillsbrad foothills","dom magic","tarren mill","wordeen voidglare"},sec={{t="Comori printre ruine",b="Dupa Prison Break In, Voidglare se indreapta spre vrajitorii din Dalaran, care au ridicat o cupola magica uriasa deasupra centrului orasului. Unii spun ca ii protejeaza de violenta vremurilor, iar altii ca pur si simplu au vrut singuratate pentru a studia si unelti. Lui Voidglare nu-i pasa care e adevarul. Ruinele de dincolo de cupola ar putea ascunde comori cu adevarata valoare magica, dar vrajitorii si sclavii lor elementali patruleaza zona. Trebuie sa vanezi sase Dalaran Summoners si doisprezece Elemental Slaves, apoi sa te intorci la Voidglare, in Tarren Mill."}},faq={{q="De ce vrea Magus Voidglare ca patrulele sa fie rarefiate?",a="Voidglare crede ca periferia daramata a Dalaran, dincolo de dom, ar putea ascunde comori cu o adevarata valoare magica, dar vrajitorii si sclavii lor elementali patruleaza zona.",al={"de ce sa ucizi patrulele dalaran","scopul lui magus voidglare","motivul patrulelor dalaran"}},{q="Ce este domul magic din jurul lui Dalaran?",a="O cupola magica uriasa, ridicata de vrajitorii din Dalaran deasupra inimii orasului lor. Unii spun ca ii apara de violenta epocii; altii spun ca voiau pur si simplu liniste ca sa studieze si sa unelteasca.",al={"ce este cupola din Dalaran","de ce se afla Dalaran intr-o bula","scutul din Dalaran"}},{q="Ce patruleaza imprejurimile din Dalaran?",a="Vrajitorii din Dalaran si sclavii lor elementali. Dalaran Summoners si Elemental Slaves sunt cei pe care Voidglare vrea sa-i vanezi.",al={"cine pazeste Dalaran","dusmanii din ruinele Dalaranului","cine patruleaza prin Dalaran"}},{q="Ce a precedat aceasta misiune?",a="Prison Break In, tot de la Voidglare in Tarren Mill.",al={"misiunea precedenta","ce urmeaza inainte de patrulele din dalaran"}}},fp="15,341,22.518.0,50.169.0,40.195.0,38.126.0,28.52.0"}
P.entries["quest:546"] = {n="Souvenirs of Death",s="Souvenirs of Death este o misiune oferita de Deathguard Samsa in Tarren Mill campionilor Horde care lupta impotriva asezarilor umane din Hillsbrad Foothills. Invidios pe cei trimisi pe front, Samsa cere treizeci de cranii umane luate in lupta, pentru a-si spori colectia macabra.",h="Souvenirs of Death este o misiune oferita de Deathguard Samsa in Tarren Mill campionilor Horde care lupta...",kw={"battle of hillsbrad","darthalia","deathguard samsa","forsaken","hillsbrad","hillsbrad human skull","amintiri ale mortii","tarren mill"},ang={["faction:Alliance"]="Colectarea sistematica a capetelor umane taiate subliniaza amenintarea brutala si existentiala pe care Forsaken o reprezinta pentru supravietuitorii din Hillsbrad.",["faction:Horde"]="Campania impotriva Hillsbrad reprezinta atacul direct al Horde pentru a desfiinta fortaretele ramase ale Alliance din Lordaeron, asigurand rutele de aprovizionare nordice pentru Tarren Mill.",["race:Undead"]="Deathguard Samsa reflecta cruzimea nonsalanta si animozitatea adanc inradacinata pe care multi Forsaken o nutresc fata de oamenii vii care ii considera monstri."},sec={{t="Invidia unui gardian",b="In timp ce High Executor Darthalia indreapta intreaga forta militara a Forsaken impotriva asezarilor omenesti din Hillsbrad, Deathguard Samsa se trezeste blocat in serviciul de santinela din Tarren Mill. Ros de o invidie amara fata de cei trimisi sa jefuiasca, sa incendieze si sa prade, Samsa priveste macelul celor vii ca pe un privilegiu de invidiat, refuzat garzilor care raman de paza in oras."},{t="Un trofeu macabru",b="Neputand sa-si paraseasca postul, Samsa isi hraneste ura adunand craniile oamenilor din Hillsbrad ucisi in campania in desfasurare. Cererea sa de treizeci de cranii nu tine de vreun ritual arcane sau de o strategie tactica, ci este o placere pur personala - trofee de razboi in care tanjeste sa lupte el insusi."}},faq={{q="Cine ofera aceasta misiune si unde se afla?",a="Deathguard Samsa iti incredinteaza sarcina. El este postat ca santinela in Tarren Mill, principalul bastion al Forsaken din nordul regiunii Hillsbrad Foothills.",al={"cel care da misiunea","cine da Souvenirs of Death","locatia lui Samsa"}},{q="Ce vrea Deathguard Samsa?",a="Samsa cere treizeci de Hillsbrad Human Skulls, adunate de la combatantii si locuitorii Human pe care ii ucizi in luptele din Hillsbrad Fields si din orasul Hillsbrad.",al={"obiectivul misiunii","ce obiecte sunt necesare","craniile necesare"}},{q="De ce vrea Samsa cranii de oameni?",a="Samsa este un colectionar infocat de trofee macabre. Blocat cu serviciul de garnizoana in Tarren Mill, in timp ce altii duc un razboi total, aduna cranii ca sa participe indirect la macelul celor vii.",al={"de ce sa colectezi cranii","motivul lui Samsa","la ce folosesc craniile"}},{q="Cand devine disponibila aceasta misiune?",a="Samsa ti se adreseaza doar dupa ce te-ai inrolat sub comanda lui High Executor Darthalia si ai incheiat asaltul de deschidere din sirul de misiuni Battle of Hillsbrad.",al={"cerinte preliminare ale misiunii","cum se deblocheaza","cerinte pentru Souvenirs"}},{q="Sunt craniile folosite in alchimia sau magia celor din Forsaken?",a="Nu. Spre deosebire de insarcinarile Royal Apothecary Society, care cauta reactivi biologici pentru New Plague, cererea lui Samsa este cu totul personala. El considera craniile retezate frumoase si le pretuieste ca suveniruri de razboi.",al={"cranii pentru alchimist","cranii magice","folosire in necromantie"}},{q="Ce oameni furnizeaza craniile?",a="Oricare dintre fermierii, taranii, membrii militiei si aparatorii umani care locuiesc in Hillsbrad Fields sau in orasul Hillsbrad poate lasa in urma cranii in timp ce lupti in numele Tarren Mill.",al={"unde sa caut cranii","ce inamici lasa cranii","oameni din Hillsbrad"}}},fx={["0c405e10"]={q="De ce are Deathguard Samsa nevoie de un aventurier in loc sa vaneze singur craniile?",a="Deathguard Samsa este legat de postul sau din Tarren Mill. In timp ce Forsaken duc o campanie activa impotriva Hillsbrad, Samsa e nevoit sa stea de paza in loc sa participe la raid. Cum High Executor Darthalia te-a inrolat deja pentru luptele de pe linia intai, Samsa te roaga sa ai mila de un soldat batran si sa aduni in numele lui trofee macabre.",al={"de ce eu, Deathguard Samsa","de ce nu poate Samsa sa adune craniile","de ce nu vaneaza Samsa"}},["3446168a"]={q="Cine sunt oamenii cu care te lupti in Hillsbrad?",a="Tinta o reprezinta cetatenii, muncitorii si aparatorii umani din Hillsbrad Fields si din orasul Hillsbrad. Fiind una dintre ultimele fortarete umane suverane din Lordaeron, Hillsbrad se opune direct avanpostului Forsaken din Tarren Mill. Forsaken considera ca existenta lor continua si loialitatea fata de Alliance reprezinta o amenintare inacceptabila la adresa dominatiei lor teritoriale.",al={"cine sunt oamenii din Hillsbrad","tinta din Hillsbrad","de ce sunt aici oamenii din Hillsbrad"}}},fp="18,285,14.373.0,17.303.0,49.147.0,32.170.0,33.185.0,38.151.0,50.222.0,32.173.0"}
P.entries["quest:547"] = {n="Humbert's Sword",s="In timp ce cerceta bastionul piticilor din Ironforge, Dun Garok, la ordinele lui High Executor Darthalia, Deathguard Humbert s-a indepartat de tabara ca sa adune lemne de foc. Cercetasii pitici i-au jefuit tabara si i-au luat arma personala, lasandu-l pe santinela umilita disperata sa o recupereze inainte ca superiorul sau sa observe.",h="In timp ce cerceta bastionul piticilor din Ironforge, Dun Garok, la ordinele lui High Executor Darthalia...",kw={"Darthalia","deathguard","Dun Garok","lemne de foc","Hillsbrad","Humbert","sabie","Tarren Mill"},ang={["faction:Horde"]="Fiecare atac asupra Dun Garok face parte din campania mai ampla de a zdrobi controlul militar al Ironforge asupra Hillsbrad Foothills si de a proteja Tarren Mill de incursiunile din sud.",["race:Dwarf"]="Alpinistii din Dun Garok nu-i au deloc la inima pe Forsaken de la usa lor si profita de orice prilej pentru a hartui santinelele din Tarren Mill si a le jefui taberele.",["race:Undead"]="Soldatii Forsaken din Hillsbrad cunosc disciplina brutala impusa de High Executor Darthalia; in Tarren Mill, esecul sau neglijenta sunt rasplatite cu executia nemiloasa, nu cu indurare."},sec={{t="Neglijenta unui cercetas",b="Insarcinat de High Executor Darthalia sa supravegheze Dun Garok, Deathguard Humbert a inceput sa pandeasca ascuns langa fortareata piticilor. La ivirea zorilor, si-a parasit pentru scurt timp avanpostul nepazit ca sa stranga lemne de foc pentru fiert apa. Atat le-a trebuit piticilor Ironforge, mereu in cautare de prilejuri. Cand s-a intors, Humbert si-a gasit tabara jefuita si sabia sa de incredere disparuta, luata in buncarul bine aparat."},{t="Teama de grinzile de sustinere",b="Pierderea unei arme chiar in fata dusmanului pe care trebuie sa-l supraveghezi este o rusine pedepsita cu moartea sub comanda Forsaken. Humbert stie prea bine ca High Executor Darthalia l-ar spanzura de grinzile din Tarren Mill daca ar afla de greseala sa. Neputand sa ia fortareata cu asalt de unul singur, se bazeaza pe aventurieri Horde aflati in trecere, pe care ii trimite in Dun Garok sa-i recupereze lama inainte ca Darthalia sa-si dea seama ca ceva nu este in regula."}},faq={{q="Cine este Deathguard Humbert?",a="Deathguard Humbert este un soldat Forsaken stationat la Tarren Mill, in Hillsbrad Foothills. High Executor Darthalia l-a insarcinat sa cerceteze si sa supravegheze Dun Garok, avanpostul pitic puternic fortificat din sud-estul colinelor.",al={"deathguard humbert","cine este humbert","humbert"}},{q="Cum si-a pierdut Humbert sabia?",a="In timp ce isi supraveghea postul de observatie de langa Dun Garok, Humbert s-a indepartat sa adune lemne de foc pentru a fierbe apa dimineata. Cat a lipsit, cercetasi pitici i-au descoperit tabara, i-au furat lucrurile si i-au luat sabia.",al={"cum si-a pierdut humbert arma","cine a furat sabia lui humbert","sabie furata"}},{q="De ce este Humbert atat de nerabdator sa-si recupereze sabia fara sa atraga atentia?",a="Comandanta lui Humbert, High Executor Darthalia, impune o disciplina stricta in Tarren Mill. Humbert se teme ca, daca afla ca si-a pierdut echipamentul chiar in mainile piticilor pe care fusese trimis sa-i supravegheze, ea il va executa si il va spanzura de grinzi.",al={"de ce este ingrijorat Humbert","pedeapsa lui Darthalia","de ce se teme de Darthalia"}},{q="Unde se afla sabia?",a="Sabia a fost adusa in Dun Garok de cercetasii pitici. Poate fi gasita printre mountaineerii, puscasii si ofiterii din Ironforge care ocupa buncarul.",al={"locatia sabiei","unde este sabia lui Humbert","sabia din Dun Garok"}},{q="Au furat Dwarves si altceva de la Humbert?",a="Da. Humbert s-a intors si a constatat ca-i lipseau lucrurile din tabara, nu doar sabia, insa sabia este singurul obiect pe care ti-l cere sa-l recuperezi din Dun Garok.",al={"alte echipamente ale lui Humbert","piesele de armura ale lui Humbert","pantalonii lui Humbert"}},{q="Ce este Dun Garok?",a="Dun Garok este o fortareata a piticilor din Ironforge, in coltul sud-estic al Hillsbrad Foothills, unde piticii sai ajuta la protejarea oamenilor din Hillsbrad si a minei Azurelode Mine din apropiere. Garnizoana Alliance de acolo se afla intr-o confruntare directa si ostila cu Forsaken din Tarren Mill.",al={"fortareata Dun Garok","istoria Dun Garok","Dwarves din Hillsbrad"}}},fx={["65d1b07f"]={q="De ce este sabia lui Humbert atat de importanta pentru el?",a="Pentru Deathguard Humbert, arma este deopotriva mandria sa personala si insemnul datoriei sale. Fara ea, ramane dezarmat in timpul misiunii de cercetare pentru Tarren Mill, complet expus furiei lui High Executor Darthalia. Nu are puteri magice sau vraji marete; este doar sabia lui cea mai de pret, iar recuperarea ei ii reda demnitatea si ascunde o gafa rusinoasa de ochii comandantului.",al={"ce este sabia lui humbert","de ce are humbert nevoie de sabia lui","rolul sabiei lui humbert"}},c70ad326={q="Cine sunt piticii care tin sabia lui Humbert?",a="Hotii fac parte din fortele piticilor stationate la Dun Garok, o fortareata a Alliance adapostita in sud-estul Hillsbrad Foothills. Acesti puscasii si cercetasi calareti din Ironforge trimit in mod regulat cercetasi prin dealuri pentru a stavili expansiunea Forsaken. O patrula a dat peste tabara nepazita a lui Humbert in timp ce acesta strangea lemne de foc, i-a jefuit armele si le-a dus inapoi, dincolo de zidurile fortificate.",al={"cine a furat sabia lui humbert","piticii din Dun Garok","cine are sabia"}},["6c936ae5"]={q="De ce are nevoie Humbert sa-i recuperezi sabia in loc sa o recupereze el?",a="Humbert nu poate lua cu asalt de unul singur o bastion pitic bine fortificat si nici nu le poate cere ajutorul celorlalti Deathguards fara sa recunoasca faptul ca si-a parasit postul ca sa fiarba apa, lasandu-si echipamentul sa fie furat. Daca High Executor Darthalia afla ca si-a pierdut arma in fata hotilor pitici, ar face din el un exemplu crunt. Un aventurier pe cont propriu se poate strecura inauntru si recupera discret lama.",al={"de ce nu poate Humbert sa-si ia sabia","de ce-mi cere Humbert sabia","de ce are Humbert nevoie de ajutor"}}},fp="15,329,20.425.0,19.435.0,26.235.0,31.231.0,58.246.0,27.167.0,49.148.0,18.279.0"}
P.entries["quest:5481"] = {n="Gordo's Task",s="Gordo's Task este o treaba marunta in Tirisfal Glades, data de Gordo, un abomination ratacitor care incearca sa adune plante de-a lungul drumului spre Brill. Nepotrivit pentru munca migaloasa pe teren, el recruteaza calatori sa culeaga Gloom Weed si sa i-o duca supraveghetorului sau, Junior Apothecary Holland.",h="Gordo's Task este o treaba marunta in Tirisfal Glades, data de Gordo, un abomination ratacitor care incearca...",kw={"abominatie","alchimist","Brill","buruiana osandei","buruiana intunecata","Gordo","Holland","Tirisfal Glades"},ang={["profession:Herbalism"]="Pentru herboristii instruiti, sarcina va fi floare la ureche, caci simtul lor de cautare scoate usor in evidenta peticele de Gloom Weed din iarba napadita de blestem.",["race:Undead"]="Pentru Forsaken abia ridicati din moarte, care parasesc Deathknell, aceasta sarcina este prima intalnire cu realitatile stangace ale muncii abominatiilor si cu temperamentul aprins al Royal Apothecary Society."},sec={{t="Un muncitor neindemanatic",b="Gordo este o abominatie care se taraste de colo-colo prin tinuturile dintre Deathknell si Brill. Abominatiile exceleaza in lupta bruta si la caratul greutatilor, insa mainile lor uriase, cusute laolalta, fac aproape imposibila orice manevrare delicata. Trimis pe pajisti sa adune ingrediente pentru Royal Apothecary Society, Gordo isi da repede seama ca degetele sale butucanoase strivesc mai multe tulpini decat culeg, asa ca ii intimideaza sau mituieste pe trecatori ca sa faca treaba migaloasa in locul lui."},{t="Nemultumirile unui alchimist",b="Junior Apothecary Holland asteapta livrarea in cimitirul din spatele primariei din Brill, dar treaba ia o turnura neasteptata. Gordo intelege complet gresit ordinele si ii trimite pe calatori sa adune Gloom Weed, inofensiva, in loc de periculoasa Doom Weed, necesara cercetarilor alchimice. Holland este nespus de exasperat de incompetenta uriasului cusut laolalta si considera livrarea gresita o dovada a inutilitatii abominatiei, apoi ii da imediat jucatorului sarcina de a indrepta greseala."}},faq={{q="Cine este Gordo?",a="Gordo este o monstruozitate in slujba Royal Apothecary Society. Patruleaza pajistile de la vest de Brill, incercand sa indeplineasca sarcinile de lucru primite de la stapanul sau, Junior Apothecary Holland.",al={"cine este Gordo","Gordo din Tirisfal","Gordo npc","ce este Gordo"}},{q="De ce are Gordo nevoie de ajutor pentru a strange buruieni?",a="Mainile lui Gordo sunt niste apendice uriase si neindemanatice, facute din carne moarta cusuta. Pur si simplu nu are dexteritatea necesara pentru a culege plantele delicate fara sa le strice, asa ca recruteaza aventurieri Forsaken aflati in trecere sa adune flora in locul lui.",al={"de ce are Gordo nevoie de buruieni","de ce nu poate Gordo sa culeaga buruienile","mainile lui Gordo"}},{q="Cine este Master Holland?",a="Junior Apothecary Holland este un alchimist din Royal Apothecary Society, stationat in cimitirul din Brill. El il supravegheaza pe Gordo si cerceteaza flora locala si solul afectat, pentru a sprijini efortul de razboi al Forsaken.",al={"maestrul Holland","cine este Holland","apotecarul Holland"}},{q="De ce este Holland suparat cand i se livreaza Gloom Weed?",a="Gordo spune ca Holland vrea Gloom Weed si iti cere sa o culegi. Du plantele la Junior Apothecary Holland in Brill.",al={"de ce este Holland furios","greseala cu Gloom Weed","planta gresita"}},{q="Unde se poate gasi Gloom Weed?",a="Gloom Weed rasare aproape de pamant pe campurile salbatice dintre Deathknell si Brill, mai ales pe pajistile deschise de la est de Solliden Farmstead.",al={"unde gasesc buruiana sumbra","locatii cu buruiana sumbra","cum gasesc buruiana sumbra"}},{q="Ce se intampla dupa indeplinirea Gordo's Task?",a="Holland iti ofera misiunea urmatoare, Doom Weed, in cimitirul din Brill.",al={"ce urmeaza","continuarea Gordo's Task","urmatoarea misiune dupa gordo"}}},fx={["2383074c"]={q="De ce vrea Gordo sa fie adunata iarba intunecata?",a="Gordo spune ca Master Holland vrea buruieni si cere ajutor la culesul de Gloom Weed. Mainile sale mari ingreuneaza culesul, asa ca trimite calatorii sa duca plantele la Holland, in cimitirul din Brill.",al={"de ce vrea gordo buruieni","motivul lui gordo","de ce sa adun iarba gloom"}},a763e1e7={q="La ce se foloseste Gloom Weed?",a="Din punctul de vedere al lui Master Holland, buruiana mohorata este cu totul inutila. Este doar o buruiana salbatica obisnuita si inofensiva, care creste prin Tirisfal Glades. Holland nu are niciun interes sa culeaga margarete; are nevoie de Doom Weed pentru potiuni.",al={"la ce foloseste Gloom Weed","scopul Gloom Weed","utilizarea Gloom Weed"}}},fp="12,264,16.465.0,23.484.1,13.201.0,41.229.0,22.218.0,54.120.1,30.150.0,43.71.1"}
P.entries["quest:5482"] = {n="Doom Weed",s="Doom Weed este o sarcina incredintata de Junior Apothecary Holland din Brill, care cere strangerea florei toxice ce creste langa gropile comune din nordul regiunii Tirisfal. Holland recruteaza aventurieri aflati in trecere, exasperat de incercarile stangace ale abominatiei Gordo de a o recolta.",h="Doom Weed este o sarcina incredintata de Junior Apothecary Holland din Brill, care cere strangerea florei...",kw={"Brill","iarba osandei","Gordo","Junior Apothecary Holland","groapa comuna","gnolli Rot Hide","Royal Apothecary Society","Tirisfal Glades"},ang={["faction:Horde"]="Experimentele alchimice tulburatoare desfasurate in Brill arata cat de diferit opereaza Forsaken fata de aliatii lor samanici si nomazi din Kalimdor.",["profession:Herbalism"]="In timp ce flora obisnuita care poate fi recoltata creste prin toate poienile, soiurile corupte precum iarba osandei ilustreaza transformarile botanice nenaturale provocate de molima Scourge.",["race:Undead"]="Slujirea membrilor juniori ai Royal Apothecary Society este un ritual de initiere obisnuit pentru Forsaken abia treziti, care vor sa-si dovedeasca utilitatea in tinuturile lui Sylvanas."},sec={{t="Ambitiile unui alchimist",b="Junior Apothecary Holland desfasoara cercetari in numele Royal Apothecary Society din asezarea Brill. Pentru a-si duce experimentele mai departe, are nevoie de cantitati de buruiana osandei, o planta cumplita care infesteaza solul pustiit din Tirisfal Glades. Cum Gordo nu este in stare sa deosebeasca reactivii potriviti, Holland apeleaza la maini mai pricepute pentru a-si salva recolta."},{t="Recolta din groapa comuna",b="Doom weed creste din belsug in locurile puternic corupte de moarte si ciuma, raspandindu-se dens in jurul gropii comune situate chiar la nord de cimitirul din Brill. Culegerea plantelor este primejdioasa din cauza gnollilor agresivi Rot Hide care dau tarcoale movilelor funerare profanate, scormonind printre ramasite si aparand santurile napadite de vegetatie."}},faq={{q="De ce are nevoie Junior Apothecary Holland de iarba doom?",a="Junior Apothecary Holland are nevoie de iarba nenorocirii pentru activitatea sa alchimica in folosul Royal Apothecary Society. Sustine ca munca lui o ajuta direct pe Lady Sylvanas Windrunner, desi entuziasmul sau lacom sugereaza ca este la fel de interesat sa-si propulseze propria cariera in cadrul societatii.",al={"Holland Doom Weed","de ce Doom Weed","la ce foloseste Doom Weed"}},{q="De ce nu strange Gordo buruienile de unul singur?",a="Gordo este o abominatie insarcinata sa adune ierburi in jurul Brill, dar nu are mintea necesara pentru a deosebi anumite plante. Holland se plange ca matahala a adus numai buruienile nepotrivite, obligandu-l pe alchimist sa angajeze aventurieri priceputi in schimb.",al={"de ce nu Gordo","esecul sarcinii lui Gordo","cine este Gordo"}},{q="Unde creste iarba osandei?",a="Iarba blestemului creste printre plantele pustiite din jurul gropii comune, aflata chiar la nord de cimitirul din afara Brill. Se raspandeste prin solul puternic pangarit de santurile de inhumare si de ciuma persistenta.",al={"locatia lui doom weed","unde este doom weed","buruieni de la groapa comuna"}},{q="Ce pericole pandesc langa peticele de iarba a pieirii?",a="Terenul din jurul gropii comune este napadit de gnolii Rot Hide. Acesti gunoieri salbatici, purtatori de boli, ataca cu inversunare pe oricine se apropie de locul de inhumare, in timp ce culeg buruieni.",al={"monstri Doom Weed","dusmanii din groapa comuna","gnollii de langa Brill"}},{q="Ce interes are Royal Apothecary Society fata de flora din Tirisfal?",a="Royal Apothecary Society studiaza neincetat plante, otravuri si ciuperci modificate de blight in Tirisfal Glades. Reactivi precum iarba osandei sunt recoltati pentru rafinarea toxinelor, descoperirea leacurilor alchimice si crearea unor arme noi in sprijinul Forsaken impotriva dusmanilor lor.",al={"interesul alchimistului","royal apothecary society tirisfal","culegerea plantelor de catre forsaken"}},{q="Cine este 'the Lady' pomenita de Holland?",a="Lady se refera la Lady Sylvanas Windrunner, Banshee Queen si conducatoarea Forsaken. Alchimistii din Undercity si Brill ii invoca frecvent numele, deoarece eforturile lor alchimice sunt oficial in slujba ei.",al={"cine este doamna","doamna Holland, Sylvanas","doamna din Undercity"}}},fp="9,259,20.366.0,22.333.0,50.278.0,43.266.0,26.209.0,45.201.0,66.262.0,39.211.0"}
P.entries["quest:549"] = {n="WANTED: Syndicate Personnel",s="Afisata pe panoul cu recompense din Tarren Mill sub autoritatea Lady Sylvanas, aceasta porunca condamna la moarte toti membrii Syndicate. Forsaken incearca sa-i starpeasca pe talharii adunati in ruinele din Durnholde Keep inainte ca acestia sa ameninte operatiunile Horde din tinuturile deluroase.",h="Afisata pe panoul cu recompense din Tarren Mill sub autoritatea Lady Sylvanas, aceasta porunca condamna la...",kw={"durnholde keep","high executor darthalia","hillsbrad foothills","syndicate","syndicate rogue","syndicate watchman","tarren mill","cautat"},ang={["class:Rogue"]="Syndicate desfasoara hoti de buzunare si atacatori prin surprindere priceputi in tot Durnholde, transformand acest contract intr-o confruntare directa intre practicieni rivali ai furisarii.",["faction:Horde"]="Durnholde Keep poarta amintiri sumbre, fiind fortareata de internare in care orcii au fost candva tinuti captivi; purificarea ruinelor ocupate acum de talhari are o importanta simbolica pentru Horde.",["race:Undead"]="Pentru Forsaken, eliminarea ramasitelor celor vii din nobilimea Alterac este o necesitate practica pentru a asigura controlul necontestat asupra dealurilor din Lordaeron."},sec={{t="Un ordin permanent de executie",b="Prezenta neasteptata a Syndicate la sud-est de Tarren Mill nu a trecut neobservata de Forsaken. In loc sa le ofere negocieri sau sa-i trateze ca pe niste nobili doar stramutati, Lady Sylvanas Windrunner si comandantii ei vad in Syndicate o molima activa. Recompensa cere uciderea lor imediata si precizeaza ca orice prizonieri adusi vor fi executati fara judecata."},{t="Ruinele din Durnholde",b="Candva o fortareata care servea drept lagar de internare vestit, Durnholde Keep se afla acum in ruine, fara stapanire. Hoti si paznici din Syndicate s-au strecurat in meterezele si turnurile daramate, folosind vechea fortareata drept centru de operatiuni. Pentru High Executor Darthalia, alungarea acestor banditi inarmati din ruine este esentiala pentru securizarea drumului si apararea caii de acces sud-estice spre Tarren Mill."}},faq={{q="Cine a oferit recompensa pentru membrii Syndicate?",a="Recompensa a fost instituita din ordinul direct al Lady Sylvanas Windrunner si afisata pe panoul de anunturi din Tarren Mill. High Executor Darthalia, comandantul militar al asezarii, primeste dovezile ca tinta a fost eliminata.",al={"cine a pus afisul Wanted: Syndicate Personnel","cine vrea morti membrii Syndicate","cel care ofera recompensa"}},{q="Unde se afla acesti membri ai Syndicate?",a="Se aduna printre pietrele sfaramate din Durnholde Keep, la sud-est de Tarren Mill, de cealalta parte a raului, precum si in jurul turnului de paza ruinat, chiar la sud de fortareata principala.",al={"unde sunt pungasii Sindicatului","locatia Sindicatului din Durnholde","unde gasesc strajerii"}},{q="De ce vor Forsaken sa-i omoare in loc sa-i captureze?",a="Forsaken ii considera pe membrii Syndicate niste daunatori tradatori si o amenintare inarmata care le incalca teritoriul. Decretul ordona in mod explicit executarea sumara a oricaror membri capturati, ceea ce face ca luarea lor prizonieri sa fie cu totul inutila.",al={"de ce sa omori Syndicate","de ce nu exista prizonieri","Syndicate-ul si Darthalia"}},{q="Ce face Syndicate in Durnholde Keep?",a="Alcatuit in principal din nobili Alteraci cazuti in dizgratie si mercenari, Syndicate foloseste fortaretele, ruinele si turnurile parasite din Lordaeron drept baze pentru raiduri asupra asezarilor, jafuri asupra calatorilor si refacerea puterii sale naruite.",al={"de ce se afla Syndicate in Durnholde","scopul Syndicate in Hillsbrad","ocupantii din Durnholde Keep"}},{q="Ce se intampla dupa eliminarea acestor agenti Syndicate?",a="Rarirea randurilor hotilor si ale paznicilor il determina pe High Executor Darthalia sa ofere o recompensa de mare prioritate pentru liderul local, Baron Vardus.",al={"care este urmatoarea misiune","dupa Wanted: Syndicate Personnel","urmatoarea recompensa"}}},fx={["6d6e03d8"]={q="De ce se bazeaza High Executor Darthalia pe aventurieri pentru aceasta recompensa?",a="High Executor Darthalia conduce Tarren Mill la ordinul direct al lui Lady Sylvanas, insa garnizoana sa permanenta este intinsa la maximum, aparand teritoriile Forsaken impotriva celor din Southshore si a amenintarilor regionale din Hillsbrad. Dupa cum le aminteste raspicat vizitatorilor, are chestiuni de comanda mult mai presante decat sa se ocupe personal de fiecare tabara de hoti. Oferirea unor recompense publice atrage mercenari dornici si campioni din Horde, care sa curete Durnholde Keep de paraziti fara a slabi apararea de pe linia intai a orasului.",al={"de ce sa trimita aventurieri","de ce a pus Darthalia recompensa","de ce nu trimite garzile din Tarren Mill"}}},fp="27,273,26.365.0,22.379.0,46.225.0,42.187.0,55.236.0,46.236.0,54.168.1"}
P.entries["quest:55"] = {n="Morbent Fel"}
P.entries["quest:550"] = {n="Battle of Hillsbrad",s="Aceasta misiune marcheaza incheierea campaniei Forsaken impotriva asezarii omenesti din Hillsbrad. Dupa ce ai zdrobit fortele locale din Alliance, High Executor Darthalia te trimite sa-i inmanezi o distinctie oficiala lui Varimathras in Undercity.",h="Aceasta misiune marcheaza incheierea campaniei Forsaken impotriva asezarii omenesti din Hillsbrad.",kw={"battle of hillsbrad","darthalia","poalele Hillsbrad","royal quarter","decoratie sigilata","tarren mill","undercity","varimathras"},ang={["faction:Horde"]="Alungand fortele Alliance din Lordaeron, asiguri un teritoriu vital pentru Horde in Eastern Kingdoms.",["race:Undead"]="Raportarea victoriei tale asupra celor vii din Hillsbrad iti aduce laude directe din partea Royal Quarter, confirmandu-ti locul in imperiul aflat in ascensiune al Dark Lady."},sec={{t="O campanie decisiva",b="Campania din Hillsbrad Foothills reprezinta o lupta crunta pentru sudul Lordaeronului. De-a lungul unei serii prelungite de atacuri coordonate din Tarren Mill, campionii Horde au zdrobit fermierii, militienii, fierarii si conducatorii civici ai orasului uman. Cu prezenta Alliance schilodita si teritoriul asigurat pentru Forsaken, High Executor Darthalia redacteaza o scrisoare oficiala de felicitare, pentru ca faptele campionului sa ajunga la cele mai inalte trepte ale conducerii."},{t="Audienta cu Dreadlord",b="Ducand scrisoarea de merit sigilata a lui Darthalia, ajungi direct in Royal Quarter of the Undercity, in fata lui Varimathras. Alaturi de Lady Sylvanas Windrunner, lordul groazei supravegheaza operatiunile militare din Lordaeron. Desi Scourge care coboara din Plaguelands de Nord ramane amenintarea existentiala principala pentru Dark Lady, securizarea frontierelor sudice impotriva enclavelor umane supravietuitoare este vitala pentru tanara natiune Forsaken."}},faq={{q="Ce este aceasta misiune?",a="Aceasta este predarea finala din ampla serie de misiuni Battle of Hillsbrad. Dupa ce iti indeplinesti sarcinile pentru High Executor Darthalia in Tarren Mill, ea iti da o scrisoare sigilata de recomandare, pe care sa i-o inmanezi personal lui Varimathras in Undercity.",al={"finalul Battle of Hillsbrad","misiunea finala din Hillsbrad","misiunea 550"}},{q="Unde predau Darthalia's Sealed Commendation?",a="I-l predai lui Varimathras, care sta langa Lady Sylvanas Windrunner in Royal Quarter of the Undercity.",al={"unde se afla varimathras","predarea scrisorii de recomandare","unde predau scrisoarea lui darthalia"}},{q="De ce ii pasa lui Varimathras de Hillsbrad?",a="In calitate de principal locotenent militar al Dark Lady, Varimathras supervizeaza apararea strategica si extinderea. Desi Scourge din nord reprezinta cea mai mare amenintare pentru Undercity, asezarile umane din sud hartuiesc neincetat liniile Forsaken. Eliminarea amenintarii din Hillsbrad protejeaza frontiera lor sudica.",al={"de ce Varimathras","rolul lui Varimathras in Hillsbrad"}},{q="Cine este High Executor Darthalia?",a="High Executor Darthalia este comandantul Forsaken de rang inalt stationat la Tarren Mill, in Hillsbrad Foothills, si coordoneaza operatiunile ofensive impotriva asezarii umane din apropiere.",al={"darthalia","cine a dat misiunea"}},{q="Aceasta misiune duce la alte misiuni in Hillsbrad?",a="Nu. Predarea unei dovezi de merit lui Varimathras incheie oficial povestea Battle of Hillsbrad si te rasplateste pentru ca ai infrant apararea orasului.",al={"urmatoarea misiune dupa Battle of Hillsbrad","ce urmeaza dupa misiunea 550"}},{q="De ce atacau Forsaken Hillsbrad de la bun inceput?",a="Orasul Hillsbrad este unul dintre ultimele bastioane umane organizate din Lordaeron. De partea Alliance, militia sa si apropierea de Tarren Mill si de caile sudice spre Undercity reprezinta o amenintare militara imediata.",al={"de ce atacam Hillsbrad","povestea din Hillsbrad"}}},fx={["8522c300"]={q="De ce vrea High Executor Darthalia ca aceasta scrisoare de recomandare sa fie livrata?",a="Ai luptat cu vitejie si staruinta de-a lungul campaniei brutale din Hillsbrad Foothills. High Executor Darthalia doreste ca faptele tale de vitejie de pe campul de lupta sa fie recunoscute oficial de inaltul comandament al Forsaken din Undercity. Trimitandu-te direct la Varimathras cu scrisoarea ei de merit sigilata, se asigura ca liderii il recunosc pe un campion capabil, ale carui lovituri decisive au frant rezistenta oamenilor de pe frontul sudic.",al={"de ce sa trimiti o scrisoare de recomandare","motivul Darthaliei","de ce sa trimiti la Varimathras"}}},fp="19,252,19.464.0,27.452.0,19.247.0,51.112.0,42.304.0,31.181.0,54.159.0,61.236.0"}
P.entries["quest:5501"] = {n="Bone Collector",s="La Kormek's Hut din Desolace, goblinul Bibbly F'utzbuckle e convins ca oasele de kodo sunt pe cale sa transforme lumea. Se cauta zece oase din Kodo Graveyard, la sud de coliba, iar in schimb se promite o rasplata.",h="La Kormek's Hut din Desolace, goblinul Bibbly F'utzbuckle e convins ca oasele de kodo sunt pe cale sa...",kw={"bibbly f'utzbuckle","colector de oase","desolace","antreprenor goblin","os de kodo","cimitirul kodo","kormek's hut","shadowprey village"},sec={{t="Noroc printre oase vechi",b="Bibbly insista ca aceasta coliba sta pe o mina de aur. Clientii fac mobila, instrumente muzicale si chiar praf de explozie din oase de kodo. Bibbly te trimite spre sud, la Kodo Graveyard, sa aduci zece, promitandu-ti ceva la schimb."},{t="O caravana pe drum",b="O caravana trece sa ridice oasele de kodo ale lui Bibbly, apoi le vinde la Shadowprey Village. Ar trebui sa soseasca din clipa in clipa, iar lui Bibbly ii mai lipsesc zece oase pana la ceea ce numeste recordul carierei."},{t="Marile visuri ale lui Bibbly",b="Cand sosesc oasele, Bibbly isi imagineaza cum cei de acasa vad chipul lui Bibbly pe coperta Goblin'preneur si cum ajunge cel mai bogat goblin din lume. Bibbly isi aminteste si de un profesor de educatie fizica, care spunea ca Bibbly nu va ajunge niciodata nimic."}},faq={{q="Cine este Bibbly F'utzbuckle?",a="Bibbly F'utzbuckle este un goblin din Kormek's Hut, in Desolace, convins ca oasele de kodo sunt o mina de aur si care vrea inca zece.",al={"cine ofera Bone Collector","bibbly futzbuckle","goblinul din coliba lui kormek"}},{q="De ce are Bibbly nevoie de oase de kodo?",a="Bibbly are clienti care transforma oasele de kodo in mobila, instrumente muzicale si chiar praf exploziv.",al={"la ce folosesc oasele de kodo","de ce oase de kodo"}},{q="Unde ajung oasele de kodo dupa ce le primeste Bibbly?",a="O caravana se opreste ca sa adune oasele de kodo ale lui Bibbly, apoi le vinde in Shadowprey Village.",al={"unde ajung oasele","destinatia caravanei"}},{q="Unde pot fi gasite oasele de kodo?",a="Bibbly te trimite la Kodo Graveyard, aflat la sud de Kormek's Hut, in Desolace.",al={"locatia oaselor de kodo","unde gasesc oase de kodo"}},{q="Unde este Kormek's Hut?",a="Kormek's Hut se afla in Desolace, la nord de Kodo Graveyard.",al={"locatia colibei lui kormek","unde se afla bibbly"}}},fp="14,222,20.243.0,20.174.0,19.260.1,26.130.0,32.102.0,50.89.0,34.85.0,22.57.0"}
P.entries["quest:5502"] = {n="A Warden of the Horde"}
P.entries["quest:551"] = {n="The Ensorcelled Parchment",s="O vraja de pe un pergament face scrisul ilizibil, cu exceptia unui singur cuvant din partea de sus: Nagaz. Trebuie sa-l duci la Loremaster Dibbs din Southshore.",h="O vraja de pe un pergament face scrisul ilizibil, cu exceptia unui singur cuvant din partea de sus: Nagaz.",kw={"alterac","dibbs","fermecat","nagaz","pergament","southshore"},sec={{t="Un pergament acoperit de vraji",b="Un farmec de pe pergament impiedica descifrarea scrisului. Doar un singur cuvant din partea de sus se poate citi: numele Nagaz. Trebuie sa duci pergamentul la Loremaster Dibbs in Southshore."},{t="Ce crede Dibbs despre asta",b="Dibbs intreaba daca sunt si mai multe notite criptate. Dibbs si-ar dori ca toate peticele ciudate de scris care ies din Alterac sa poata fi descifrate, dar recunoaste ca nu are cunostintele necesare."}},faq={{q="Ce scrie pe pergament?",a="O vraja impiedica citirea textului, cu exceptia unui singur cuvant din partea de sus: Nagaz.",al={"ce scrie pe pergamentul vrajit","textul pergamentului","cuvintele de pe pergamentul vrajit"}},{q="Cine ar trebui sa vada pergamentul?",a="Loremaster Dibbs din Southshore, care primeste fragmente de cunoastere adunate din munti.",al={"loremaster dibbs","cine este dibbs","loremaster din southshore"}}},fp="25,145,24.191.0,22.171.1,33.84.0,29.88.0"}
P.entries["quest:552"] = {n="Helcular's Revenge",s="Novice Thaivand din Tarren Mill vrea sa razbune moartea lui Master Helcular, un mare vrajitor aflat pe punctul de a deveni lich, ucis de o multime de Human dupa ce aceasta i-a descoperit adapostul ritualic. Inainte ca razbunarea sa se abata asupra Southshore, Thaivand are nevoie de Helcular's Rod, pe care trebuie s-o aiba unul dintre yeti de acolo.",h="Novice Thaivand din Tarren Mill vrea sa razbune moartea lui Master Helcular, un mare vrajitor aflat pe...",kw={"alterac","helcular","hillsbrad","lich","toiag","southshore","tarren mill","thaivand","yeti"},ang={["faction:Horde"]="Aceasta este pentru aventurierii Horde; Thaivand din Tarren Mill este cel care te cheama."},sec={{t="Un maestru intrerupt",b="Master Helcular era pe punctul de a deveni lich cand a fost gasit si ucis de o multime de oameni, care descoperisera barlogul ritualic pe care il avea in dealuri. Apoi i-au ingropat trupul in cimitirul din Southshore. Ucenicul sau, Thaivand, considera inacceptabil acest dispret fata de un mare vrajitor si jura ca ploile razbunarii se vor abate asupra orasului Southshore."},{t="Toiagul disparut",b="Thaivand spune ca mai intai e nevoie de Helcular's Rod. Yetii au pus stapanire pe vizuina ritualica, iar Thaivand este sigur ca unul dintre ei are toiagul. Sunt atat de multi yeti in regiune, incat va fi greu sa-l gasesti. Printre locurile in care pot fi vazuti se numara Growless Cave si Darrow Hill."}},faq={{q="Cine a fost Maestrul Helcular?",a="Un mare vrajitor aflat in pragul transformarii intr-un lich, ucis de o multime de oameni care l-au descoperit in adapostul sau ritualic din dealuri. Trupul sau a fost ingropat in cimitirul din Southshore.",al={"cine este helcular","povestea lui helcular","trecutul lui helcular"}},{q="De ce vrea Novice Thaivand toiagul lui Helcular's Rod?",a="Thaivand, ucenicul lui Helcular, planuieste sa se razbune pe orasul Southshore si spune ca mai intai este nevoie de toiag.",al={"de ce e nevoie de toiag","scopul toiagului lui helcular","scopul lui thaivand"}},{q="Unde a ajuns toiagul?",a="Yeti au pus stapanire pe barlogul ritualic al lui Helcular, iar Thaivand este sigur ca unul dintre ei are toiagul. Yeti pot fi gasiti in locuri precum Growless Cave si Darrow Hill.",al={"unde este toiagul","cum au obtinut yeti toiagul","locatia toiagului"}},{q="Unde se afla Novice Thaivand?",a="In Tarren Mill, in Hillsbrad Foothills.",al={"locatia lui thaivand","unde predau helculars revenge","novice thaivand"}}},fp="18,290,20.368.0,15.276.0,24.164.0,45.110.0,21.156.0,33.43.0"}
P.entries["quest:553"] = {n="Helcular's Revenge",s="Novice Thaivand iti da Rod of Helcular. Trei ruguri ceremoniale faurite de Helcular pentru cea mai puternica vraja a sa trebuie sa-l incarce, dupa care trebuie infipt in mormantul lui Helcular din Southshore.",h="Novice Thaivand iti da Rod of Helcular.",kw={"alterac","azel","darrow hill","growless cave","helcular","hillsbrad","southshore","thaivand","uzel","veraz"},sec={{t="Cele trei flacari",b="Helcular a faurit trei ruguri ceremoniale pentru cea mai puternica vraja a sa, iar toiagul trebuie incarcat de la fiecare dintre ele. Flacarile lui Azel si Veraz se afla in Foothill Caverns, in pestera yeti de la Darrow Hill. A treia, Flame of Uzel, se gaseste intr-o pestera mica deasupra cavernelor, mai la nord, in munti, langa Growless Cave."},{t="Mormantul din Southshore",b="Dupa ce toiagul este incarcat de la toate cele trei flacari, trebuie infipt in mormantul lui Helcular din Southshore, un oras Human puternic pazit. Cimitirul se afla in coltul de nord-est al orasului, langa rau, iar mormantul este in coltul de sud-est al cimitirului."},{t="Dupa ritual",b="Cand toiagul incarcat este infipt in mormant, pamantul se cutremura puternic, iar Helcular revine, ratacind prin cimitirul din Southshore si atacand oamenii din apropiere."}},faq={{q="Unde se afla cele trei flacari ceremoniale?",a="Flacara lui Azel si flacara lui Veraz se afla in Foothill Caverns, in pestera yeti de la Darrow Hill, in Hillsbrad Foothills. Flacara lui Uzel se afla intr-o pestera mica deasupra acelor grote, mai la nord, in munti, langa Growless Cave, in Alterac Mountains.",al={"locatiile flacarilor","unde este Flame of Azel","unde este Flame of Uzel","gaseste rugurile funerare"}},{q="Unde se afla mormantul lui Helcular?",a="La Southshore, un oras human bine pazit. Cimitirul se afla in coltul de nord-est al orasului, langa rau, iar mormantul este in coltul de sud-est al cimitirului.",al={"locatia mormantului lui Helcular","unde este mormantul","cimitirul din Southshore"}},{q="Cine ofera Rod of Helcular?",a="Novice Thaivand iti da toiagul.",al={"cine ofera toiagul","cel care da misiunea","novice thaivand"}},{q="Ce a precedat aceasta misiune?",a="Helcular's Revenge, in care Novice Thaivand a trebuit sa gaseasca Helcular's Rod. Thaivand este ucenicul lui Helcular, iar Helcular a fost ucis de o gloata de oameni care a facut dreptate cu propriile maini si a fost ingropat in cimitirul din Southshore.",al={"misiunea precedenta","partea 1 din lantul Helcular"}}},fp="18,207,16.334.0,23.261.0,16.172.1,46.250.0,26.173.0,33.34.0,28.192.0"}
P.entries["quest:554"] = {n="Stormpike's Deciphering",s="Loremaster Dibbs te trimite la Ironforge cu pergamentul vrajit, in speranta ca Prospector Stormpike, maestru al decriptarii si descifrarii, va reusi sa-l inteleaga.",h="Loremaster Dibbs te trimite la Ironforge cu pergamentul vrajit, in speranta ca Prospector Stormpike, maestru...",kw={"descifrare","dibbs","pergament vrajit","ironforge","cartierul general al prospectorilor","stormpike"},sec={{t="Un maestru al descifrarii",b="Dupa The Ensorcelled Parchment, Dibbs iti spune sa-l duci la Prospector Stormpike, care studiaza la sediul prospectorilor din Ironforge. Dibbs spune sa mentionezi ca te-a trimis el, fiindca in ultima vreme i-a adus lui Stormpike destul de multe afaceri."},{t="O chestiune de timp",b="Stormpike descopera ca pergamentul este acoperit de o vraja foarte complicata si fin tesuta. Spune ca o poate descifra, dar va dura, iar timpul este pretios pentru el, asa ca se ofera sa ti-l cumpere. Dupa ce accepti, spune ca, dupa parerea lui, niciun alt carturar nu are priceperea necesara pentru a o traduce si promite ca te va chema daca se dovedeste ca textul contine ceva interesant."}},faq={{q="Cine te trimite la Prospector Stormpike?",a="Loremaster Dibbs, care il considera pe Stormpike un maestru al descifrarii si interpretarii codurilor.",al={"cine ofera misiunea","cel care ofera misiunea","misiunea lui Loremaster Dibbs"}},{q="Unde poate fi gasit Prospector Stormpike?",a="Isi vede de studii la sediul Prospectors din Ironforge.",al={"locatia Stormpike","unde se afla Stormpike","sediul prospectorilor"}},{q="De ce este greu de citit pergamentul?",a="O vraja sta asupra lui si impiedica descifrarea scrierii; in partea de sus se poate citi doar numele Nagaz.",al={"de ce pergament fermecat","vraja pergamentului","de ce sa descifrez"}},{q="Ce urmeaza inaintea acestui pas?",a="Urmeaza dupa The Ensorcelled Parchment, prin care pergamentul vrajit a ajuns la Dibbs.",al={"misiune precedenta","inceputul lantului","conditie prealabila"}}},fp="23,162,22.254.0,16.345.1,38.77.0,40.60.0,39.111.0,28.85.0"}
P.entries["quest:5541"] = {n="Ammo for Rumbleshot"}
P.entries["quest:5545"] = {n="A Bundle of Trouble",s="La Eastvale Logging Camp, misiunea A Bundle of Trouble incepe cu lemne lasate in padure si un termen-limita care se apropie. Supervisor Raelen are nevoie ca lemnul taiat sa fie adus inapoi inainte ca livrarea sa intarzie.",h="La Eastvale Logging Camp, misiunea A Bundle of Trouble incepe cu lemne lasate in padure si un termen-limita...",kw={"ursi","bundle of wood","deputy rainer","eastvale","elwynn forest","tabara de exploatare forestiera","supervisor raelen","cherestea","lupi"},ang={["class:Hunter"]="Ca Hunter, poti urmari urme prin cranguri pline de pradatori si infrunta bestiile locului in timp ce recuperezi proviziile.",["faction:Alliance"]="Ca membru al Alliance, poti ajuta la aprovizionarea reconstructiei din Stormwind si a avanposturilor regionale cu cherestea din Eastvale."},sec={{t="Un termen-limita iminent",b="Supervisor Raelen asteapta in curand un transport de lemn. Eastvale Logging Camp taie lemn pentru Stormwind, iar echipa ei a ramas in urma cu programul. Cu termenul-limita aproape, Raelen are nevoie ca lemnul sa fie trimis la drum."},{t="Pradatori prin padure",b="Lupii si ursii de la nord de tabara i-au alungat pe taietorii de lemne de langa gramezile de lemn taiat. Muncitorii au lasat lemnele acolo unde erau. Raelen nu poate astepta ca garzile sa curete zona, asa ca iti cere sa duci gramezile inapoi in tabara."}},faq={{q="Cine este Supervisor Raelen?",a="Supervisor Raelen administreaza Eastvale Logging Camp, in estul Elwynn Forest. Ea supravegheaza taietorii de lemne si transporturile de cherestea destinate Stormwind si asezarilor din apropiere.",al={"Supervisor Raelen","Raelen","Eastvale supraveghetor"}},{q="De ce a fost parasit lemnul in padure?",a="Muncitorii taiasera si legasera bustenii inainte ca ursii si lupii sa-i alunge din poiana. Au fugit in tabara fara lemne.",al={"de ce a ramas lemnul","cherestea abandonata","lemn de padure"}},{q="De ce il mentioneaza Raelen pe Deputy Rainer?",a="Raelen spune ca l-a contactat pe Deputy Rainer in legatura cu pradatorii. El este stationat la Westbrook Garrison, departe, dincolo de Elwynn Forest, asa ca mesajul poate sa fi trecut prin mainile gardienilor sau autoritatile locale pot fi suprasolicitate.",al={"Deputy Rainer si Raelen","de ce Deputy Rainer","legatura lui Rainer"}},{q="Unde este nevoie de lemn?",a="Eastvale Logging Camp trimite lemn in tot regatul, pentru reconstructia oraselor si intarirea palisadelor si podurilor. Nerespectarea termenului poate afecta economia din Elwynn si intarzia constructiile.",al={"cine are nevoie de lemn","livrarea cherestelei","la ce foloseste lemnul"}},{q="De ce nu pot taietorii de lemne sa adune singuri lemnul?",a="Taietorii de lemne sunt muncitori care doboara copaci, nu luptatori antrenati sa infrunte pradatorii. Lupii si ursii i-au alungat, iar ei nu se vor intoarce in desis fara arme.",al={"de ce sunt speriati taietorii de lemne","de ce nu sunt speriati taietorii de lemne","taietorii de lemne si lupii"}},{q="Unde pot fi gasite legaturile de lemne?",a="Legaturile se afla in padure, chiar la nord de Eastvale Logging Camp, unde munceau lucratorii inainte ca fiarele locale sa-i alunge.",al={"locatia lemnului","unde sunt legaturile","gaseste legaturile"}}},fx={d8093908={q="De ce are Supervisor Raelen nevoie de acest lemn atat de repede?",a="Supervisor Raelen se confrunta cu un termen-limita strict pentru livrarea unei comenzi de lemn. Daca nu furnizeaza la timp lemnul promis, au de suferit atat operatiunile forestiere din Eastvale, cat si reputatia ei. Lemnul este deja taiat, dar muncitorii taberei au fost nevoiti sa fuga cand au aparut pradatori salbatici, punand in pericol intreaga livrare.",al={"de ce are Raelen nevoie de lemn","termenul limita al lui Raelen","de ce se grabeste cu comanda de cherestea"}}},fp="19,187,18.206.0,23.235.0,25.175.0,39.131.0,38.220.0,27.187.0,50.166.0,39.134.0"}
